            <span style={{ fontSize: 12, color: C.muted }}>{t('acc.currentBalance')}</span>
            <span className="lg-mono" style={{ fontSize: 32, fontWeight: 500, color: balance < 0 ? C.expense : C.ink }}>
              {money(balance, account.currency)}
