// 币种与汇率（LedgerCurrencyManagerView）+ 添加币种。
// 行排序：**基准币置顶**，其余按币种码升序。

import React from 'react'
import Icon, { Spinner } from './Icon.jsx'
import { Card, Divider, useLongPress } from './primitives.jsx'
import { C, RADIUS, SPACE, fade } from './theme.js'
import { CURRENCY_CATALOG, currencySymbol } from '../lib/currencies.js'
import { formatRate } from '../lib/fx.js'

export default function CurrencyManager({ ctx, mode = 'list' }) {
  const { store, t, actions, canMutate } = ctx
  const [refreshing, setRefreshing] = React.useState(false)
  const [failed, setFailed] = React.useState(false)

  const rows = React.useMemo(() => {
    const list = [...store.currencies]
    list.sort((a, b) => {
      if (a.isBase !== b.isBase) return a.isBase ? -1 : 1
      return a.code < b.code ? -1 : (a.code > b.code ? 1 : 0)
    })
    return list
  }, [store, store.revision]) // eslint-disable-line react-hooks/exhaustive-deps

  const refresh = async () => {
    setRefreshing(true)
    const ok = await actions.refreshRates()
    setRefreshing(false)
    setFailed(!ok)
  }

  if (mode === 'add') {
    const enabled = new Set(store.currencies.map((row) => row.code))
    const available = CURRENCY_CATALOG.filter((row) => !enabled.has(row.code))
    return (
      <Card padding={0}>
        {available.length === 0 ? (
          <div style={{ padding: SPACE.s4, fontSize: 15, color: C.muted }}>—</div>
        ) : available.map((row, index) => (
          <React.Fragment key={row.code}>
            {index > 0 ? <Divider inset={SPACE.s4} /> : null}
            <button
              type="button"
              className="lg-btn"
              onClick={() => actions.addCurrency(row.code)}
              style={{ display: 'flex', alignItems: 'center', gap: SPACE.s3, width: '100%', padding: SPACE.s3 }}
            >
              <span className="lg-mono" style={{ fontSize: 15, fontWeight: 500, color: C.ink, minWidth: 66 }}>
                {`${row.code} ${row.symbol}`}
              </span>
              <span className="lg-clamp-1" style={{ fontSize: 15, color: C.muted, flex: '1 1 auto', minWidth: 0 }}>
                {t(`cur.${row.code}`)}
              </span>
              <Icon name="arrow.right.circle" size={17} color={C.brand} />
            </button>
          </React.Fragment>
        ))}
      </Card>
    )
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: SPACE.s3 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: SPACE.s2, padding: '0 4px' }}>
        <span style={{ fontSize: 13, fontWeight: 500, color: C.muted, flex: '1 1 auto' }}>
          {t('cur.header', store.baseCode)}
        </span>
        {canMutate ? (
          <>
            <button type="button" className="lg-btn" onClick={() => actions.openAddCurrency()} aria-label={t('cur.add')}>
              <Icon name="plus" size={16} color={C.brand} />
            </button>
            <button type="button" className="lg-btn" onClick={refresh} disabled={refreshing} aria-label={t('cur.refresh')}>
              {refreshing ? <Spinner size={15} color={C.brand} /> : <Icon name="arrow.clockwise" size={15} color={C.brand} />}
            </button>
          </>
        ) : null}
      </div>

      <Card padding={0}>
        {rows.map((row, index) => (
          <React.Fragment key={row.code}>
            {index > 0 ? <Divider inset={SPACE.s4} /> : null}
            <CurrencyRow ctx={ctx} row={row} canMutate={canMutate} />
          </React.Fragment>
        ))}
      </Card>

      <span style={{ fontSize: 12, color: C.muted, padding: '0 4px', lineHeight: 1.4 }}>
        {t('cur.footer', store.baseCode)}
      </span>
      {failed ? (
        <span style={{ fontSize: 12, color: C.expense, padding: '0 4px', lineHeight: 1.4 }}>
          {t('cur.refreshFailed')}
        </span>
      ) : null}
    </div>
  )
}

function CurrencyRow({ ctx, row, canMutate }) {
  const { store, t, actions } = ctx
  const longPress = useLongPress(() => {
    if (!canMutate || row.isBase) return
    actions.showMenu([
      { id: 'base', label: t('cur.setAsBase'), icon: 'star', onSelect: () => actions.setBaseCurrency(row.code) },
    ])
  })

  return (
    <button
      type="button"
      className="lg-btn"
      onClick={() => { if (!row.isBase && canMutate) actions.editRate(row.code) }}
      {...longPress}
      style={{ display: 'flex', alignItems: 'center', gap: SPACE.s3, width: '100%', padding: SPACE.s3 }}
    >
      <div style={{ flex: '1 1 auto', minWidth: 0, display: 'flex', flexDirection: 'column', gap: 2 }}>
        <span style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          <span className="lg-mono" style={{ fontSize: 15, fontWeight: 500, color: C.ink }}>
            {`${row.code} ${currencySymbol(row.code)}`}
          </span>
          {row.isBase ? (
            <span style={{
              fontSize: 10, fontWeight: 500, color: C.brand, background: fade(C.brand, 14),
              borderRadius: RADIUS.pill, padding: '1px 6px',
            }}
            >
              {t('cur.base')}
            </span>
          ) : null}
        </span>
        <span className="lg-clamp-1" style={{ fontSize: 12, color: C.muted }}>{t(`cur.${row.code}`)}</span>
      </div>
      {row.isBase ? (
        <span className="lg-mono" style={{ fontSize: 15, color: C.muted }}>1</span>
      ) : (
        <div style={{ display: 'flex', alignItems: 'baseline', gap: 6 }}>
          <span className="lg-mono" style={{ fontSize: 15, color: row.rateConfigured ? C.ink : C.expense }}>
            {row.rateConfigured
              ? `1 ${row.code} = ${formatRate(row.rateToBase)} ${store.baseCode}`
              : t('tx.rateNeeded')}
          </span>
          {row.manualRate ? <span style={{ fontSize: 12, color: C.muted }}>{t('cur.manual')}</span> : null}
        </div>
      )}
    </button>
  )
}

// 编辑器合集：账户 / 项目 / 预算 / 成员 / 余额校准 / 汇率。
// 都是 sheet 里的表单，共用 FieldCard + Menu + Toggle 三件套。

import React from 'react'
import Icon from './Icon.jsx'
import { FieldCard, Menu, Toggle } from './primitives.jsx'
import { C, RADIUS, SPACE, alpha, fade } from './theme.js'
import { ACCOUNT_KIND_ORDER, MEMBER_COLORS, PROJECT_COLORS, PROJECT_ICONS } from '../lib/seeds.js'
import { CURRENCY_CATALOG, currencySymbol } from '../lib/currencies.js'
import { money, parseMajorToMinor, plainMajor } from '../lib/money.js'
import { balanceMinor, derivesBalanceFromFlow } from '../lib/balances.js'
import { isoDay, parseISODay } from '../lib/dates.js'
import { formatRate } from '../lib/fx.js'

function Label({ children }) {
  return <span style={{ fontSize: 13, color: C.muted, padding: '0 4px' }}>{children}</span>
}

function Footer({ children }) {
  return <span style={{ fontSize: 12, color: C.muted, padding: '0 4px', lineHeight: 1.4 }}>{children}</span>
}

function TextInput({ value, onChange, placeholder, align = 'right', inputMode }) {
  return (
    <input
      className="lg-field"
      inputMode={inputMode}
      style={{ textAlign: align, fontSize: 15 }}
      value={value}
      placeholder={placeholder}
      onChange={(event) => onChange(event.target.value)}
    />
  )
}

/** 账户编辑器（新建 / 编辑）。**已有账户不允许改币种**（会误解释既有金额）。 */
export function AccountEditor({ ctx, editing, onSubmit }) {
  const { store, t } = ctx
  const [name, setName] = React.useState(editing ? editing.name : '')
  const [kind, setKind] = React.useState(editing ? editing.kind : 'cash')
  const [currency, setCurrency] = React.useState(editing ? editing.currency : store.baseCode)
  const [opening, setOpening] = React.useState('')
  const [creditLimit, setCreditLimit] = React.useState(
    editing && editing.creditLimitMinor > 0 ? plainMajor(editing.creditLimitMinor) : '',
  )
  const [includeInNetWorth, setInclude] = React.useState(editing ? editing.includeInNetWorth : true)
  const [menu, setMenu] = React.useState(null)

  // 候选 = 已启用币种 + 目录里其余币种（选到未启用的会在建账时自动登记）。
  const currencyOptions = React.useMemo(() => {
    const enabled = store.currencies.map((row) => row.code)
    const rest = CURRENCY_CATALOG.map((row) => row.code).filter((code) => !enabled.includes(code))
    return [...enabled, ...rest]
  }, [store, store.revision]) // eslint-disable-line react-hooks/exhaustive-deps

  React.useEffect(() => {
    onSubmit.current = () => ({
      name: name.trim(),
      kind,
      currency,
      initialBalanceMinor: parseMajorToMinor(opening) ?? 0,
      creditLimitMinor: parseMajorToMinor(creditLimit) ?? 0,
      includeInNetWorth,
      valid: name.trim().length > 0,
    })
  })

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: SPACE.s2 }}>
      <FieldCard label={t('acc.name')}>
        <TextInput value={name} onChange={setName} />
      </FieldCard>
      <FieldCard label={t('x.type')} onClick={() => setMenu('kind')}>
        <span style={{ fontSize: 15, color: C.ink }}>{t(`acc.kind.${kind}`)}</span>
      </FieldCard>
      <FieldCard label={t('x.currency')} onClick={editing ? undefined : () => setMenu('currency')}>
        <span className="lg-mono" style={{ fontSize: 15, color: editing ? C.muted : C.ink }}>
          {`${currency}  ${currencySymbol(currency)}`}
        </span>
      </FieldCard>

      {!editing ? (
        <>
          <FieldCard label={kind === 'credit' ? t('acc.amountOwed') : t('acc.openingBalance')}>
            <TextInput value={opening} onChange={setOpening} placeholder="0.00" inputMode="decimal" />
          </FieldCard>
          {kind === 'credit' ? <Footer>{t('acc.creditFooter')}</Footer> : null}
        </>
      ) : null}

      {kind === 'credit' ? (
        <FieldCard label={t('acc.creditLimit')}>
          <TextInput value={creditLimit} onChange={setCreditLimit} placeholder="0.00" inputMode="decimal" />
        </FieldCard>
      ) : null}

      <FieldCard label={t('acc.includeInNetWorth')}>
        <Toggle checked={includeInNetWorth} onChange={setInclude} />
      </FieldCard>

      <Menu
        open={menu === 'kind'}
        onClose={() => setMenu(null)}
        items={ACCOUNT_KIND_ORDER.map((row) => ({
          id: row, label: t(`acc.kind.${row}`), selected: kind === row, onSelect: () => setKind(row),
        }))}
      />
      <Menu
        open={menu === 'currency'}
        onClose={() => setMenu(null)}
        items={currencyOptions.map((code) => ({
          id: code, label: `${code}  ${currencySymbol(code)}`, selected: currency === code,
          onSelect: () => setCurrency(code),
        }))}
      />
    </div>
  )
}

