// 记一笔 / 编辑（LedgerEntryView）。同一个面板既是新建也是编辑（传 editing 即编辑）。
// 目标：**3 步内落账**（金额 → 分类 → 保存）。
// 结构：类型分段 → 可滚动区（金额显示 → 分类宫格 / 转账账户 → 元信息）→ 底部计算器键盘。

import React from 'react'
import Icon from './Icon.jsx'
import { FieldCard, Menu, Segmented, Toggle } from './primitives.jsx'
import { C, RADIUS, SPACE, alpha, fade } from './theme.js'
import { KIND } from '../lib/store.js'
import {
  appendDigit, appendDot, appendOperator, displayValue, tryEvaluateMinor,
} from '../lib/expression.js'
import { currencySymbol } from '../lib/currencies.js'
import { money, plainMajor } from '../lib/money.js'
import { isoDay, parseISODay } from '../lib/dates.js'
import { lastAccountID, sortRootCategoriesByRecency } from '../lib/prefs.js'

const KEYS = [
  ['7', '8', '9', '÷'],
  ['4', '5', '6', '×'],
  ['1', '2', '3', '−'],
  ['0', '.', '⌫', '+'],
  ['=', '(', ')', 'C'],
]
const OPERATOR_KEYS = new Set(['+', '−', '×', '÷', '='])

export default function EntryEditor({ ctx, editing, onClose }) {
  const { store, t, locale, actions, canMutate } = ctx
  const isEditing = !!editing

  const initialType = editing
    ? (editing.kind === KIND.income ? 'income'
      : (editing.kind === KIND.transferOut || editing.kind === KIND.transferIn ? 'transfer' : 'expense'))
    : 'expense'

  const [type, setType] = React.useState(initialType)
  const [input, setInput] = React.useState(() => {
    if (!editing) return ''
    // 编辑载入：金额框优先填原始表达式，没有才填纯金额。
    return editing.calculationExpression || plainMajor(editing.amountMinor)
  })
  const [categoryID, setCategoryID] = React.useState(editing ? editing.categoryID : null)
  const [expandedRoot, setExpandedRoot] = React.useState(() => {
    if (!editing || !editing.categoryID) return null
    const category = store.category(editing.categoryID)
    return category && category.parentID ? category.parentID : null
  })
  const [accountID, setAccountID] = React.useState(
    () => (editing ? editing.accountID : lastAccountID(store, 'expense')),
  )
  const [toAccountID, setToAccountID] = React.useState(() => {
    if (!editing || !editing.transferPeerID) return null
    const peer = store.transaction(editing.transferPeerID)
    if (!peer) return null
    return editing.kind === KIND.transferOut ? peer.accountID : editing.accountID
  })
  const [fromAccountID, setFromAccountID] = React.useState(() => {
    if (!editing || !editing.transferPeerID) return lastAccountID(store, 'transfer')
    const peer = store.transaction(editing.transferPeerID)
    if (!peer) return editing.accountID
    return editing.kind === KIND.transferOut ? editing.accountID : peer.accountID
  })
  const [projectID, setProjectID] = React.useState(
    () => (editing ? editing.projectID : (store.currentProject()?.id ?? null)),
  )
  const [payerMemberID, setPayerMemberID] = React.useState(editing ? editing.payerMemberID : null)
  const [split, setSplit] = React.useState(editing ? editing.split : null)
  const [merchant, setMerchant] = React.useState(editing ? (editing.merchant ?? '') : '')
  const [note, setNote] = React.useState(editing ? editing.note : '')
  const [day, setDay] = React.useState(() => isoDay(editing ? editing.occurredOn : Date.now()))
  const [tags, setTags] = React.useState(editing ? (editing.tags ?? []).join(', ') : '')
  const [reimbursable, setReimbursable] = React.useState(editing ? !!editing.reimbursable : false)
  const [refundOfID, setRefundOfID] = React.useState(editing ? editing.refundOfID : null)
  const [expanded, setExpanded] = React.useState(false)
  const [menu, setMenu] = React.useState(null)
  const [bounce, setBounce] = React.useState(false)

  const accounts = store.activeAccounts()
  const projects = store.activeProjects()
  const kind = type === 'income' ? 'income' : 'expense'
  const roots = React.useMemo(
    () => sortRootCategoriesByRecency(store, store.rootCategories(kind), kind),
    [store, store.revision, kind], // eslint-disable-line react-hooks/exhaustive-deps
  )
  const children = expandedRoot ? store.childCategories(expandedRoot) : []

  const minor = tryEvaluateMinor(input)
  const account = store.account(accountID)
  const fromAccount = store.account(fromAccountID)
  const toAccount = store.account(toAccountID)
  const currency = type === 'transfer'
    ? (fromAccount ? fromAccount.currency : store.baseCode)
    : (account ? account.currency : store.baseCode)
  const accent = type === 'income' ? C.income : (type === 'expense' ? C.expense : C.brand)
  const hasOperator = /[+\-−*×/÷()]/.test(input)

  const transferRateMissing = type === 'transfer' && fromAccount && toAccount
    && fromAccount.currency !== toAccount.currency
    && (!store.hasUsableRate(fromAccount.currency) || !store.hasUsableRate(toAccount.currency))

  const canSave = canMutate && minor !== null && minor > 0 && (type === 'transfer'
    ? !!(fromAccount && toAccount && fromAccount.id !== toAccount.id && !transferRateMissing)
    : !!(account && store.hasUsableRate(account.currency)))

  const projectMembers = projectID ? store.projectMembers(projectID) : []
  const hasOtherMembers = projectMembers.some((row) => !row.isMe)

  // 切类型：清空已选分类与展开态、按类型取上次账户、非收入清空退款关联、重算 AA 默认值。
  const changeType = (next) => {
    if (isEditing) return
    setType(next)
    setCategoryID(null)
    setExpandedRoot(null)
    if (next === 'transfer') setFromAccountID(lastAccountID(store, 'transfer'))
    else setAccountID(lastAccountID(store, next === 'income' ? 'income' : 'expense'))
    if (next !== 'income') setRefundOfID(null)
    setPayerMemberID(null)
    setSplit(null)
  }

  const press = (key) => {
    if (key === 'C') { setInput(''); return }
    if (key === '⌫') { setInput((text) => text.slice(0, -1)); return }
    if (key === '=') {
      try { setInput(displayValue(input)) } catch (error) { /* 求值失败时原样保留 */ }
      return
    }
    if (key === '(' || key === ')') { setInput((text) => text + key); return }
    if (OPERATOR_KEYS.has(key)) { setInput((text) => appendOperator(text, key)); return }
    if (key === '.') { setInput((text) => appendDot(text)); return }
    setInput((text) => appendDigit(text, key))
  }

  const payload = () => ({
    type,
    amountMinor: minor,
    calculationExpression: hasOperator ? input : null,
    categoryID: type === 'transfer' ? null : categoryID,
    accountID: type === 'transfer' ? fromAccountID : accountID,
    toAccountID,
    projectID,
    payerMemberID,
    split,
    merchant: merchant.trim().length > 0 ? merchant.trim() : null,
    note,
    occurredOn: parseISODay(day) ?? Date.now(),
    tags: tags.split(',').map((piece) => piece.trim()).filter((piece) => piece.length > 0),
    reimbursable,
    refundOfID,
  })

  const submit = async (again) => {
    const ok = await actions.saveEntry(payload(), editing)
    if (!ok) return
    if (!again) { onClose(); return }
    // 「保存并再记」：清空 金额/商家/备注/标签/可报销/退款关联，**保留** 类型/分类/账户/日期/项目。
    setInput('')
    setMerchant('')
    setNote('')
    setTags('')
    setReimbursable(false)
    setRefundOfID(null)
    setBounce(true)
    window.setTimeout(() => setBounce(false), 250)
  }

  const refundCandidates = React.useMemo(() => {
    if (type !== 'income') return []
    return store.allTransactions()
      .filter((txn) => txn.kind === KIND.expense && (!editing || txn.id !== editing.id))
      .slice(0, 30)
  }, [store, store.revision, type, editing]) // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%', minHeight: 0 }}>
      <div style={{ padding: `${SPACE.s3}px ${SPACE.s4}px 0` }}>
        <Segmented
          value={type}
          onChange={changeType}
          disabled={isEditing}
          items={[
            { id: 'expense', label: t('x.expense') },
            { id: 'income', label: t('x.income') },
            { id: 'transfer', label: t('x.transfer') },
          ]}
        />
      </div>

      <div className="lg-scroll" style={{ flex: '1 1 auto', padding: SPACE.s4 }}>
        {/* 金额显示区 */}
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 2, marginBottom: SPACE.s4 }}>
          {hasOperator && input.length > 0 ? (
            <span className="lg-mono lg-clamp-1" style={{ fontSize: 15, color: C.muted }}>{input}</span>
          ) : null}
          <div style={{
            display: 'flex', alignItems: 'baseline', gap: 4,
            transform: bounce ? 'scale(1.06)' : 'none', transition: 'transform 0.2s ease',
          }}
          >
            <span style={{ fontSize: 24, fontWeight: 500, color: accent, opacity: 0.7 }}>
              {currencySymbol(currency)}
            </span>
            <span className="lg-mono lg-clamp-1" style={{ fontSize: 40, fontWeight: 500, color: accent }}>
              {minor === null ? (input.length > 0 ? input : '0') : (input.length === 0 ? '0' : displaySafe(input))}
            </span>
          </div>
        </div>

        {type === 'transfer' ? (
          <div style={{ display: 'flex', flexDirection: 'column', gap: SPACE.s2, marginBottom: SPACE.s4 }}>
            <FieldCard icon="arrow.up.right" label={t('ent.from')} onClick={() => setMenu('from')}>
              <span style={{ fontSize: 15, color: C.ink }}>{fromAccount ? fromAccount.name : '—'}</span>
            </FieldCard>
            <FieldCard icon="arrow.down.left" label={t('ent.to')} onClick={() => setMenu('to')}>
              <span style={{ fontSize: 15, color: C.ink }}>{toAccount ? toAccount.name : '—'}</span>
            </FieldCard>
            {transferRateMissing ? (
              <div style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 12, color: C.expense }}>
                <Icon name="exclamationmark.triangle.fill" size={12} color={C.expense} />
                <span>{t('ent.transferRateNeeded')}</span>
              </div>
            ) : null}
          </div>
        ) : (
          <div style={{ marginBottom: SPACE.s4 }}>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: `${SPACE.s3}px ${SPACE.s2}px` }}>
              {roots.map((root) => {
                const selected = categoryID === root.id
                  || (categoryID && store.rootCategoryID(categoryID) === root.id)
                return (
                  <button
                    key={root.id}
                    type="button"
                    className="lg-btn"
                    onClick={() => {
                      const kids = store.childCategories(root.id)
                      setCategoryID(root.id)
                      setExpandedRoot(kids.length > 0 ? root.id : null)
                    }}
                    style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4 }}
                  >
                    <div style={{
                      width: 44, height: 44, borderRadius: 22,
                      background: selected ? root.colorHex : alpha(root.colorHex, 0.14),
                      display: 'flex', alignItems: 'center', justifyContent: 'center',
                    }}
                    >
                      <Icon
                        name={root.systemImage}
                        size={20}
                        color={selected ? C.onAccent : root.colorHex}
                      />
                    </div>
                    <span
                      className="lg-clamp-1"
                      style={{ fontSize: 12, color: C.ink, maxWidth: '100%', textAlign: 'center' }}
                    >
                      {root.name}
                    </span>
                  </button>
                )
              })}
            </div>
            {children.length > 0 ? (
              <div className="lg-chips" style={{ marginTop: SPACE.s3 }}>
                {children.map((child) => {
                  const selected = categoryID === child.id
                  return (
                    <button
                      key={child.id}
                      type="button"
                      className="lg-btn"
                      onClick={() => setCategoryID(child.id)}
                      style={{
                        flex: '0 0 auto', padding: '8px 12px', borderRadius: RADIUS.pill, fontSize: 15,
                        background: selected ? C.brand : C.surface,
                        color: selected ? C.onAccent : C.ink,
                        border: selected ? 'none' : `1px solid ${C.line}`,
                      }}
                    >
                      {child.name}
                    </button>
                  )
                })}
              </div>
            ) : null}
          </div>
        )}

        {/* 元信息区 */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: SPACE.s2 }}>
          {type !== 'transfer' ? (
            <FieldCard icon="wallet.pass" label={t('x.account')} onClick={() => setMenu('account')}>
              <span style={{ fontSize: 15, color: C.ink }}>{account ? account.name : '—'}</span>
            </FieldCard>
          ) : null}

          {projects.length > 0 ? (
            <FieldCard icon="folder" label={t('x.project')} onClick={() => setMenu('project')}>
              <span style={{ fontSize: 15, color: C.ink }}>
                {projectID ? (store.project(projectID)?.name ?? t('x.noProject')) : t('x.noProject')}
              </span>
            </FieldCard>
          ) : null}

          {type === 'expense' && hasOtherMembers ? (
            <>
              <FieldCard icon="person.badge.plus" label={t('ent.paidBy')} onClick={() => setMenu('payer')}>
                <span style={{ fontSize: 15, color: C.ink }}>
                  {payerMemberID ? (store.member(payerMemberID)?.name ?? t('prj.meName')) : t('prj.meName')}
                </span>
              </FieldCard>
              <FieldCard
                icon="person.2.badge.plus"
                label={t('ent.split')}
                onClick={() => actions.openSplitEditor({
                  projectID,
                  payerMemberID,
                  totalBaseMinor: store.toBaseMinor(minor ?? 0, currency),
                  split,
                  onDone: setSplit,
                })}
              >
                <span style={{ fontSize: 15, color: C.muted }}>
                  {split && (split.shares ?? []).length > 0
                    ? `${t(`ent.${split.mode}`)} · ${t('ent.people', split.shares.length)}`
                    : t('ent.notSplit')}
                </span>
              </FieldCard>
            </>
          ) : null}

          <FieldCard icon="storefront" label={t('ent.merchant')}>
            <input
              className="lg-field lg-clamp-1"
              style={{ textAlign: 'right', fontSize: 15 }}
              value={merchant}
              onChange={(event) => setMerchant(event.target.value)}
            />
          </FieldCard>

          <FieldCard icon="calendar" label={t('x.date')}>
            <input
              className="lg-field"
              type="date"
              style={{ textAlign: 'right', fontSize: 15 }}
              value={day}
              onChange={(event) => setDay(event.target.value)}
            />
          </FieldCard>

          <FieldCard icon="text.alignleft" label={t('x.note')}>
            <input
              className="lg-field"
              style={{ textAlign: 'right', fontSize: 15 }}
              value={note}
              onChange={(event) => setNote(event.target.value)}
            />
          </FieldCard>

          {type !== 'transfer' ? (
            <>
              <button
                type="button"
                className="lg-btn"
                onClick={() => setExpanded((value) => !value)}
                style={{ display: 'flex', alignItems: 'center', gap: 6, padding: `${SPACE.s2}px 4px`, color: C.muted, fontSize: 14 }}
              >
                <Icon name="slider.horizontal.3" size={14} color={C.muted} />
                <span>{t('ent.moreDetails')}</span>
                <Icon name={expanded ? 'chevron.up' : 'chevron.down'} size={10} color={C.muted} />
              </button>
              {expanded ? (
                <>
                  <FieldCard icon="tag" label={t('ent.tags')}>
                    <input
                      className="lg-field"
                      style={{ textAlign: 'right', fontSize: 15 }}
                      value={tags}
                      onChange={(event) => setTags(event.target.value)}
                    />
                  </FieldCard>
                  <FieldCard icon="briefcase" label={t('ent.reimbursable')}>
                    <Toggle checked={reimbursable} onChange={setReimbursable} />
                  </FieldCard>
                  {type === 'income' && refundCandidates.length > 0 ? (
                    <FieldCard icon="arrow.uturn.left.circle.fill" label={t('ent.refundOf')} onClick={() => setMenu('refund')}>
                      <span className="lg-clamp-1" style={{ fontSize: 15, color: C.ink }}>
                        {refundOfID ? refundLabel(store, refundOfID, t) : t('ent.notLinked')}
                      </span>
                    </FieldCard>
                  ) : null}
                </>
              ) : null}
            </>
          ) : null}
        </div>
      </div>

      {/* 计算器键盘 */}
      <div style={{
        background: C.surface, borderTop: `1px solid ${C.line}`, flex: '0 0 auto',
        padding: `${SPACE.s2}px ${SPACE.s2}px calc(${SPACE.s2}px + env(safe-area-inset-bottom))`,
      }}
      >
        {KEYS.map((row) => (
          <div key={row.join('')} style={{ display: 'flex', gap: 6, marginBottom: 6 }}>
            {row.map((key) => (
              <button
                key={key}
                type="button"
                className="lg-btn"
                onClick={() => press(key)}
                style={{
                  flex: '1 1 0', height: 44, borderRadius: RADIUS.field,
                  background: OPERATOR_KEYS.has(key) ? fade(C.brand, 12) : C.bg,
                  color: C.ink, display: 'flex', alignItems: 'center', justifyContent: 'center',
                  fontSize: key === 'C' ? 20 : 24, fontWeight: 500,
                }}
              >
                {key === '⌫' ? <Icon name="delete.left" size={20} color={C.ink} /> : key}
              </button>
            ))}
          </div>
        ))}

        <div style={{ display: 'flex', gap: SPACE.s2, marginTop: SPACE.s2 }}>
          {!isEditing ? (
            <button
              type="button"
              className="lg-btn"
              disabled={!canSave}
              onClick={() => submit(true)}
              style={{
                flex: '1 1 0', height: 48, borderRadius: RADIUS.field, background: fade(C.brand, 14),
                color: C.brand, display: 'flex', alignItems: 'center', justifyContent: 'center',
                fontSize: 16, fontWeight: 500, opacity: canSave ? 1 : 0.5,
              }}
            >
              {t('ent.saveAndNew')}
            </button>
          ) : null}
          <button
            type="button"
            className="lg-btn"
            disabled={!canSave}
            onClick={() => submit(false)}
            style={{
              flex: '1 1 0', height: 48, borderRadius: RADIUS.field,
              background: canSave ? C.brand : fade(C.muted, 25),
              color: C.onAccent, display: 'flex', alignItems: 'center', justifyContent: 'center',
              fontSize: 16, fontWeight: 500,
            }}
          >
            {isEditing ? t('x.update') : t('x.save')}
          </button>
        </div>
      </div>

      <Menu
        open={menu === 'account'}
        onClose={() => setMenu(null)}
        items={accounts.map((row) => ({
          id: row.id, label: row.name, selected: accountID === row.id, onSelect: () => setAccountID(row.id),
        }))}
      />
      <Menu
        open={menu === 'from'}
        onClose={() => setMenu(null)}
        items={accounts.map((row) => ({
          id: row.id, label: row.name, selected: fromAccountID === row.id, onSelect: () => setFromAccountID(row.id),
        }))}
      />
      <Menu
        open={menu === 'to'}
        onClose={() => setMenu(null)}
        items={accounts.map((row) => ({
          id: row.id, label: row.name, selected: toAccountID === row.id, onSelect: () => setToAccountID(row.id),
        }))}
      />
      <Menu
        open={menu === 'project'}
        onClose={() => setMenu(null)}
        items={[
          { id: 'none', label: t('x.noProject'), selected: !projectID, onSelect: () => setProjectID(null) },
          ...projects.map((row) => ({
            id: row.id, label: row.name, selected: projectID === row.id, onSelect: () => setProjectID(row.id),
          })),
        ]}
      />
      <Menu
        open={menu === 'payer'}
        onClose={() => setMenu(null)}
        items={projectMembers.map((row) => ({
          id: row.id, label: row.name, selected: payerMemberID === row.id, onSelect: () => setPayerMemberID(row.id),
        }))}
      />
      <Menu
        open={menu === 'refund'}
        onClose={() => setMenu(null)}
        items={[
          { id: 'none', label: t('ent.notLinked'), selected: !refundOfID, onSelect: () => setRefundOfID(null) },
          ...refundCandidates.map((row) => ({
            id: row.id, label: refundLabel(store, row.id, t), selected: refundOfID === row.id,
            onSelect: () => setRefundOfID(row.id),
          })),
        ]}
      />
    </div>
  )
}

function displaySafe(input) {
  try { return displayValue(input) } catch (error) { return input }
}

function refundLabel(store, id, t) {
  const txn = store.transaction(id)
  if (!txn) return t('ent.notLinked')
  const name = txn.merchant
    || (txn.categoryID ? store.category(txn.categoryID)?.name : null)
    || txn.note
    || t('x.expense')
  return `${name} · ${money(txn.amountMinor, txn.currency)}`
}

// 页面通用零件：卡片、空态、chip、分段、开关、月份条、进度条、底部 sheet、
// 长按菜单、左右滑操作。
//
// 弹层刻意自绘（不用 antd-mobile 的 Popup/ActionSheet/Toast）——运行时已知 `Toast.show`
// 渲染为空，同族命令式弹层风险相同；自绘的 fixed 覆盖层在 WebView 里行为确定，
// 也更好对齐本包的设计令牌。

import React from 'react'
import Icon from './Icon.jsx'
import { C, RADIUS, SPACE, fade } from './theme.js'

/** ledgerCard：surface 底 + 16 圆角 + line 描边 + padding 16。 */
export function Card({ children, padding = SPACE.s4, style }) {
  return (
    <div
      style={{
        background: C.surface,
        borderRadius: RADIUS.card,
        border: `1px solid ${C.line}`,
        padding,
        overflow: 'hidden',
        ...style,
      }}
    >
      {children}
    </div>
  )
}

/** 段标题：13 medium muted 全大写。 */
export function SectionHeader({ children, trailing }) {
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: SPACE.s2, padding: `0 4px ${SPACE.s2}px` }}>
      <span style={{ fontSize: 13, fontWeight: 500, color: C.muted, textTransform: 'uppercase', letterSpacing: 0.4 }}>
        {children}
      </span>
      <div style={{ flex: '1 1 auto' }} />
      {trailing}
    </div>
  )
}

/** 空态：图标 38 light muted / 标题 17 medium ink / 正文 15 muted 居中 / 纵向 padding 32。 */
export function EmptyState({ icon, title, body }) {
  return (
    <div style={{
      display: 'flex', flexDirection: 'column', alignItems: 'center', gap: SPACE.s3,
      padding: `${SPACE.s7}px ${SPACE.s6}px`, textAlign: 'center',
    }}
    >
      <Icon name={icon} size={38} color={C.muted} />
      {title ? <span style={{ fontSize: 17, fontWeight: 500, color: C.ink }}>{title}</span> : null}
      {body ? <span style={{ fontSize: 15, color: C.muted, lineHeight: 1.45 }}>{body}</span> : null}
    </div>
  )
}

/** 筛选 chip：文字 12 + chevron.down 9；选中 = brand 字 + brand 12% 底。 */
export function Chip({ label, selected, onClick, showChevron = true }) {
  return (
    <button
      type="button"
      className="lg-btn"
      onClick={onClick}
      style={{
        display: 'flex', alignItems: 'center', gap: 5, flex: '0 0 auto',
        padding: '7px 12px', borderRadius: RADIUS.pill,
        border: `1px solid ${C.line}`,
        background: selected ? fade(C.brand, 12) : C.surface,
        color: selected ? C.brand : C.ink,
        fontSize: 12,
      }}
    >
      <span>{label}</span>
      {showChevron ? <Icon name="chevron.down" size={9} /> : null}
    </button>
  )
}

/** 分段控件（记一笔类型、报表收支、分摊方式）。 */
export function Segmented({ items, value, onChange, disabled }) {
  return (
    <div
      style={{
        display: 'flex', background: fade(C.muted, 12), borderRadius: 10, padding: 2,
        opacity: disabled ? 0.5 : 1,
      }}
    >
      {items.map((item) => (
        <button
          key={item.id}
          type="button"
          className="lg-btn"
          disabled={disabled}
          onClick={() => !disabled && onChange(item.id)}
          style={{
            flex: '1 1 0', textAlign: 'center', padding: '7px 4px', borderRadius: 8,
            background: value === item.id ? C.surface : 'transparent',
            color: value === item.id ? C.ink : C.muted,
            fontSize: 14, fontWeight: value === item.id ? 500 : 400,
            boxShadow: value === item.id ? '0 1px 3px rgba(0,0,0,0.12)' : 'none',
          }}
        >
          {item.label}
        </button>
      ))}
    </div>
  )
}

export function Toggle({ checked, onChange, disabled, tint = C.brand }) {
  return (
    <button
      type="button"
      className="lg-btn"
      role="switch"
      aria-checked={!!checked}
      disabled={disabled}
      onClick={() => !disabled && onChange(!checked)}
      style={{
        width: 50, height: 30, borderRadius: 15, flex: '0 0 auto',
        background: checked ? tint : fade(C.muted, 30),
        transition: 'background 0.18s ease', opacity: disabled ? 0.5 : 1, padding: 2,
      }}
    >
      <span style={{
        display: 'block', width: 26, height: 26, borderRadius: 13, background: '#FFFFFF',
        transform: checked ? 'translateX(20px)' : 'none', transition: 'transform 0.18s ease',
        boxShadow: '0 1px 3px rgba(0,0,0,0.25)',
      }}
      />
    </button>
  )
}

/** 月份条：左右箭头 + 月标题；右箭头在 ≥ 当前月时禁用（不能看未来）。 */
export function MonthBar({ title, onPrevious, onNext, nextDisabled }) {
  return (
    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: SPACE.s5 }}>
      <button type="button" className="lg-btn" onClick={onPrevious} aria-label="previous month">
        <Icon name="chevron.left" size={15} color={C.muted} />
      </button>
      <span style={{ fontSize: 16, fontWeight: 500, color: C.ink, minWidth: 120, textAlign: 'center' }}>{title}</span>
      <button
        type="button"
        className="lg-btn"
        onClick={onNext}
        disabled={nextDisabled}
        aria-label="next month"
        style={{ opacity: nextDisabled ? 0.3 : 1 }}
      >
        <Icon name="chevron.right" size={15} color={C.muted} />
      </button>
    </div>
  )
}

/** 进度条：胶囊，底色 line，宽度 = max(minWidth, 容器宽 × progress)。 */
export function ProgressBar({ progress, height = 10, color, minWidth = 6 }) {
  const ratio = Math.max(0, Number(progress) || 0)
  return (
    <div style={{ position: 'relative', height, borderRadius: height / 2, background: C.line, overflow: 'hidden' }}>
      <div style={{
        position: 'absolute', inset: `0 auto 0 0`, height: '100%',
        width: `max(${minWidth}px, ${Math.min(1, ratio) * 100}%)`,
        borderRadius: height / 2, background: color ?? C.brand,
        transition: 'width 0.2s ease',
      }}
      />
    </div>
  )
}

/** 行间 Divider，可左缩进（原生用 52 / 60）。 */
export function Divider({ inset = 0 }) {
  return <div style={{ height: 1, background: C.line, marginLeft: inset }} />
}

/** 元信息小卡（记一笔面板里每项都是一张 padding 12 的小卡）。 */
export function FieldCard({ icon, label, children, onClick, style }) {
  const Element = onClick ? 'button' : 'div'
  return (
    <Element
      type={onClick ? 'button' : undefined}
      className={onClick ? 'lg-btn' : undefined}
      onClick={onClick}
      style={{
        display: 'flex', alignItems: 'center', gap: SPACE.s3, width: '100%',
        background: C.surface, border: `1px solid ${C.line}`, borderRadius: RADIUS.field,
        padding: SPACE.s3, minHeight: 46, ...style,
      }}
    >
      {icon ? <Icon name={icon} size={15} color={C.muted} /> : null}
      {label ? <span style={{ fontSize: 15, color: C.muted, flex: '0 0 auto' }}>{label}</span> : null}
      <div style={{ flex: '1 1 auto', minWidth: 0, display: 'flex', justifyContent: 'flex-end' }}>{children}</div>
    </Element>
  )
}

/** 底部 sheet。`detent` 是内容区高度上限（对应原生的 detent 档位）。 */
export function Sheet({ open, onClose, title, leading, trailing, detent, children }) {
  React.useEffect(() => {
    if (!open) return undefined
    const onKey = (event) => { if (event.key === 'Escape') onClose() }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [open, onClose])
  if (!open) return null
  return (
    <div className="lg-backdrop" onClick={(event) => { if (event.target === event.currentTarget) onClose() }}>
      <div className="lg-sheet" style={detent ? { height: detent } : undefined}>
        <div style={{
          display: 'flex', alignItems: 'center', gap: SPACE.s3, padding: `${SPACE.s3}px ${SPACE.s4}px`,
          borderBottom: `1px solid ${C.line}`, flex: '0 0 auto',
        }}
        >
          <div style={{ minWidth: 60 }}>{leading}</div>
          <span style={{ flex: '1 1 auto', textAlign: 'center', fontSize: 16, fontWeight: 500 }}>{title}</span>
          <div style={{ minWidth: 60, display: 'flex', justifyContent: 'flex-end' }}>{trailing}</div>
        </div>
        <div className="lg-scroll" style={{ padding: SPACE.s4, paddingBottom: `calc(${SPACE.s4}px + env(safe-area-inset-bottom))` }}>
          {children}
        </div>
      </div>
    </div>
  )
}

export function SheetButton({ children, onClick, bold, disabled, danger }) {
  return (
    <button
      type="button"
      className="lg-btn"
      onClick={onClick}
      disabled={disabled}
      style={{
        fontSize: 16, fontWeight: bold ? 600 : 400,
        color: disabled ? C.muted : (danger ? C.expense : C.brand),
        opacity: disabled ? 0.5 : 1, whiteSpace: 'nowrap',
      }}
    >
      {children}
    </button>
  )
}

