/**
 * 长按上下文菜单（原生的 contextMenu）。500ms 触发，移动 > 10px 取消。
 * 用在账户行、项目行、成员行、币种行、项目流水行。
 */
export function useLongPress(onLongPress, { delay = 500 } = {}) {
  const timer = React.useRef(null)
  const origin = React.useRef(null)
  const fired = React.useRef(false)

  const clear = () => {
    if (timer.current) { window.clearTimeout(timer.current); timer.current = null }
  }
  return {
    onPointerDown(event) {
      fired.current = false
      origin.current = { x: event.clientX, y: event.clientY }
      clear()
      timer.current = window.setTimeout(() => { fired.current = true; onLongPress() }, delay)
    },
    onPointerMove(event) {
      if (!origin.current) return
      const dx = Math.abs(event.clientX - origin.current.x)
      const dy = Math.abs(event.clientY - origin.current.y)
      if (dx > 10 || dy > 10) clear()
    },
    onPointerUp() { clear() },
    onPointerCancel() { clear() },
    onClickCapture(event) {
      // 长按已触发时吞掉随后的 click，避免同时进详情页。
      if (fired.current) { event.preventDefault(); event.stopPropagation(); fired.current = false }
    },
  }
}

/**
 * 左右滑操作（原生 swipeActions 的等价件）。
 * `trailing` 从右往左划出（明细页的删除）；`leading` 从左往右划出（最近删除的恢复）。
 * `fullSwipe` 为真时划过阈值直接执行（对应原生 allowsFullSwipe）。
 */
export function SwipeRow({ children, leading, trailing, disabled }) {
  const [offset, setOffset] = React.useState(0)
  const start = React.useRef(null)
  const active = React.useRef(false)
  const width = 92
  const leadingWidth = leading ? width : 0
  const trailingWidth = trailing ? width : 0

  const finish = () => {
    if (offset < -trailingWidth * 0.9 && trailing && trailing.fullSwipe) { setOffset(0); trailing.onAction() }
    else if (offset > leadingWidth * 0.9 && leading && leading.fullSwipe) { setOffset(0); leading.onAction() }
    else if (offset < -trailingWidth * 0.4 && trailing) setOffset(-trailingWidth)
    else if (offset > leadingWidth * 0.4 && leading) setOffset(leadingWidth)
    else setOffset(0)
  }

  if (disabled) return <div>{children}</div>

  return (
    <div style={{ position: 'relative', overflow: 'hidden' }}>
      {trailing ? (
        <button
          type="button"
          className="lg-btn"
          onClick={() => { setOffset(0); trailing.onAction() }}
          style={{
            position: 'absolute', top: 0, bottom: 0, right: 0, width: trailingWidth,
            background: trailing.destructive ? C.expense : C.brand, color: '#FFFFFF',
            display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 4, fontSize: 13,
          }}
        >
          {trailing.icon ? <Icon name={trailing.icon} size={16} color="#FFFFFF" /> : null}
          <span>{trailing.label}</span>
        </button>
      ) : null}
      {leading ? (
        <button
          type="button"
          className="lg-btn"
          onClick={() => { setOffset(0); leading.onAction() }}
          style={{
            position: 'absolute', top: 0, bottom: 0, left: 0, width: leadingWidth,
            background: leading.destructive ? C.expense : C.brand, color: '#FFFFFF',
            display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 4, fontSize: 13,
          }}
        >
          {leading.icon ? <Icon name={leading.icon} size={16} color="#FFFFFF" /> : null}
          <span>{leading.label}</span>
        </button>
      ) : null}
      <div
        style={{
          position: 'relative', background: C.surface,
          transform: `translateX(${offset}px)`,
          transition: active.current ? 'none' : 'transform 0.2s ease',
          touchAction: 'pan-y',
        }}
        onPointerDown={(event) => { start.current = { x: event.clientX, base: offset }; active.current = false }}
        onPointerMove={(event) => {
          if (!start.current) return
          const delta = event.clientX - start.current.x
          if (!active.current && Math.abs(delta) < 8) return
          active.current = true
          const next = start.current.base + delta
          setOffset(Math.max(-trailingWidth * 1.15, Math.min(leadingWidth * 1.15, next)))
        }}
        onPointerUp={() => { if (active.current) finish(); start.current = null; active.current = false }}
        onPointerCancel={() => { setOffset(0); start.current = null; active.current = false }}
        onClickCapture={(event) => {
          // 划开时点内容 = 收起，而不是触发行的点击。
          if (offset !== 0) { event.preventDefault(); event.stopPropagation(); setOffset(0) }
        }}
      >
        {children}
      </div>
    </div>
  )
}

// 项目详情（LedgerProjectDetailView）+ 成员与 AA 结算区块（LedgerMemberSettleSection）。

import React from 'react'
import Icon, { IconBadge } from './Icon.jsx'
import { Card, Divider, EmptyState, ProgressBar, useLongPress } from './primitives.jsx'
import { ChartLegend, DonutChart } from './Charts.jsx'
import { C, RADIUS, SPACE, alpha, fade } from './theme.js'
import { KIND } from '../lib/store.js'
import { buckets, filterTransactions } from '../lib/queries.js'
import { memberBalances, projectIncomeMinor, projectSpentMinor, settlementPlan } from '../lib/split.js'
import { money, moneyCompact } from '../lib/money.js'
import { mediumDayDate, shortDate } from '../lib/dates.js'
import { entryPathTitle } from '../lib/display.js'

export default function ProjectDetail({ ctx, projectID }) {
  const { store, t, locale, actions, canMutate } = ctx
  const project = store.project(projectID)
  if (!project) {
    return (
      <div className="lg-scroll" style={{ flex: '1 1 auto', padding: SPACE.s4 }}>
        <EmptyState icon="folder" title={t('prj.notFoundTitle')} body={t('prj.notFoundBody')} />
      </div>
    )
  }

  const spent = projectSpentMinor(store, project.id)
  const income = projectIncomeMinor(store, project.id)
  const flowRows = filterTransactions(store, { projectID: project.id })
  const allRows = filterTransactions(store, { projectID: project.id, includeNonFlow: true }).slice(0, 50)
  const labels = { uncategorized: t('x.uncategorized'), noTag: t('x.noTag'), noProject: t('x.noProject') }
  const categoryBuckets = buckets(store, flowRows, 'byCategory', 'expense', locale, labels)
  const ratio = project.budgetMinor > 0 ? Math.max(0, Math.min(1, spent / project.budgetMinor)) : 0
  const over = project.budgetMinor > 0 && spent > project.budgetMinor
  const dateRange = project.startOn || project.endOn
    ? [project.startOn ? mediumDayDate(project.startOn, locale) : '',
      project.endOn ? mediumDayDate(project.endOn, locale) : ''].filter(Boolean).join(' – ')
    : null

  return (
    <div className="lg-scroll" style={{ flex: '1 1 auto' }}>
      <div style={{ display: 'flex', flexDirection: 'column', gap: SPACE.s4, padding: SPACE.s4, paddingBottom: 96 }}>
        <Card>
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: SPACE.s2 }}>
            <IconBadge
              name={project.systemImage}
              size={52}
              color={project.colorHex}
              background={alpha(project.colorHex, 0.16)}
            />
            <span style={{ fontSize: 12, color: C.muted }}>{t('prj.spent')}</span>
            <span className="lg-mono" style={{ fontSize: 32, fontWeight: 500, color: C.ink }}>
              {money(spent, store.baseCode)}
            </span>
            <div style={{ display: 'flex', gap: SPACE.s5, marginTop: SPACE.s2, flexWrap: 'wrap', justifyContent: 'center' }}>
              <Stat label={t('prj.entries')} value={String(flowRows.length)} />
              {income > 0 ? <Stat label={t('x.income')} value={moneyCompact(income, store.baseCode)} /> : null}
              {dateRange ? <Stat label={t('prj.dates')} value={dateRange} /> : null}
            </div>
          </div>
        </Card>

        {project.budgetMinor > 0 ? (
          <Card>
            <div style={{ display: 'flex', alignItems: 'center', marginBottom: SPACE.s3 }}>
              <span style={{ fontSize: 13, fontWeight: 500, color: C.muted }}>{t('x.budget')}</span>
              <div style={{ flex: '1 1 auto' }} />
              <span className="lg-mono" style={{ fontSize: 14, fontWeight: 500, color: C.ink }}>
                {`${money(spent, store.baseCode)} / ${money(project.budgetMinor, store.baseCode)}`}
              </span>
            </div>
            <ProgressBar progress={ratio} height={10} color={over ? C.expense : C.brand} />
            <div style={{ marginTop: SPACE.s2, fontSize: 12, color: over ? C.expense : C.muted }}>
              {over
                ? t('prj.overBy', money(spent - project.budgetMinor, store.baseCode))
                : t('prj.left', money(project.budgetMinor - spent, store.baseCode))}
            </div>
          </Card>
        ) : null}

        {categoryBuckets.length > 0 ? (
          <Card>
            <div style={{ fontSize: 13, fontWeight: 500, color: C.muted, marginBottom: SPACE.s3 }}>
              {t('rep.byCategory')}
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: SPACE.s4 }}>
              <DonutChart buckets={categoryBuckets} size={150} />
              <ChartLegend buckets={categoryBuckets} currency={store.baseCode} />
            </div>
          </Card>
        ) : null}

        <MemberSettleSection ctx={ctx} project={project} />

        <Card padding={0}>
          <div style={{ fontSize: 13, fontWeight: 500, color: C.muted, padding: `${SPACE.s4}px ${SPACE.s4}px ${SPACE.s2}px` }}>
            {t('prj.entries')}
          </div>
          {allRows.length === 0 ? (
            <div style={{ padding: `0 ${SPACE.s4}px ${SPACE.s4}px`, fontSize: 15, color: C.muted, textAlign: 'center' }}>
              {t('prj.noEntries')}
            </div>
          ) : allRows.map((txn, index) => (
            <React.Fragment key={txn.id}>
              {index > 0 ? <Divider inset={SPACE.s4} /> : null}
              <ProjectEntryRow ctx={ctx} txn={txn} canMutate={canMutate} />
            </React.Fragment>
          ))}
        </Card>

        {canMutate ? (
          <button
            type="button"
            className="lg-btn"
            onClick={() => actions.recordIntoProject(project)}
            style={{
              display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8, width: '100%',
              height: 50, borderRadius: RADIUS.field, background: C.brand, color: C.onAccent,
              fontSize: 16, fontWeight: 500,
            }}
          >
            <Icon name="checkmark.circle.fill" size={18} color={C.onAccent} />
            <span>{t('prj.recordInto')}</span>
          </button>
        ) : null}
      </div>
    </div>
  )
}

function Stat({ label, value }) {
  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 }}>
      <span style={{ fontSize: 12, color: C.muted }}>{label}</span>
      <span className="lg-mono" style={{ fontSize: 14, fontWeight: 500, color: C.ink }}>{value}</span>
    </div>
  )
}

function ProjectEntryRow({ ctx, txn, canMutate }) {
  const { store, t, locale, actions } = ctx
  const longPress = useLongPress(() => {
    if (!canMutate) return
    actions.showMenu([
      { id: 'delete', label: t('x.delete'), icon: 'trash', destructive: true, onSelect: () => actions.deleteEntry(txn) },
    ])
  })
  const title = txn.categoryID
    ? entryPathTitle(store, txn, t)
    : (txn.note && txn.note.trim().length > 0 ? txn.note.trim() : shortDate(txn.occurredOn, locale))
  const subtitle = [shortDate(txn.occurredOn, locale), txn.note].filter((piece) => piece && String(piece).trim().length > 0).join(' · ')
  const tone = txn.kind === KIND.income ? C.income : (txn.kind === KIND.expense ? C.ink : C.muted)
  const text = txn.kind === KIND.income
    ? money(txn.amountMinor, txn.currency, { signed: true })
    : (txn.kind === KIND.expense ? money(-txn.amountMinor, txn.currency) : money(txn.amountMinor, txn.currency))

  return (
    <button
      type="button"
      className="lg-btn"
      onClick={() => actions.editEntry(txn)}
      {...longPress}
      style={{ display: 'flex', alignItems: 'center', gap: SPACE.s3, width: '100%', padding: SPACE.s3 }}
    >
      <div style={{ flex: '1 1 auto', minWidth: 0, display: 'flex', flexDirection: 'column', gap: 2 }}>
        <span className="lg-clamp-1" style={{ fontSize: 15, color: C.ink }}>{title}</span>
        <span className="lg-clamp-1" style={{ fontSize: 12, color: C.muted }}>{subtitle}</span>
      </div>
      <span className="lg-mono" style={{ fontSize: 15, fontWeight: 500, color: tone }}>{text}</span>
    </button>
  )
}

/** 成员与分摊区块 —— 整块一张卡。 */
function MemberSettleSection({ ctx, project }) {
  const { store, t, actions, canMutate } = ctx
  const members = store.projectMembers(project.id)
  const others = members.filter((row) => !row.isMe)
  const net = React.useMemo(
    () => memberBalances(store, project.id),
    [store, store.revision, project.id], // eslint-disable-line react-hooks/exhaustive-deps
  )
  const plan = React.useMemo(
    () => settlementPlan(store, project.id),
    [store, store.revision, project.id], // eslint-disable-line react-hooks/exhaustive-deps
  )

  return (
    <Card>
      <div style={{ display: 'flex', alignItems: 'center', marginBottom: SPACE.s3 }}>
        <span style={{ fontSize: 13, fontWeight: 500, color: C.muted }}>{t('prj.membersSplit')}</span>
        <div style={{ flex: '1 1 auto' }} />
        {canMutate ? (
          <button
            type="button"
            className="lg-btn"
            aria-label={t('prj.addMember')}
            onClick={() => actions.addMember(project)}
          >
            <Icon name="person.badge.plus" size={15} color={C.brand} />
          </button>
        ) : null}
      </div>

      {others.length === 0 ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: SPACE.s3 }}>
          <span style={{ fontSize: 13, color: C.muted, lineHeight: 1.45 }}>{t('prj.membersIntro')}</span>
          {canMutate ? (
            <button
              type="button"
              className="lg-btn"
              onClick={() => actions.addMember(project)}
              style={{
                display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6, width: '100%',
                height: 44, borderRadius: RADIUS.field, background: fade(C.brand, 12), color: C.brand, fontSize: 15,
              }}
            >
              <Icon name="person.2.badge.plus" size={16} color={C.brand} />
              <span>{t('prj.addMembers')}</span>
            </button>
          ) : null}
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: SPACE.s3 }}>
          {members.map((member) => (
            <MemberRow key={member.id} ctx={ctx} member={member} amount={net[member.id] ?? 0} canMutate={canMutate} />
          ))}
          <Divider />
          {plan.length === 0 ? (
            <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
              <Icon name="checkmark.seal.fill" size={13} color={C.income} />
              <span style={{ fontSize: 13, color: C.muted }}>{t('prj.allSettled')}</span>
            </div>
          ) : (
            <>
              <span style={{ fontSize: 13, fontWeight: 500, color: C.muted, textTransform: 'uppercase', letterSpacing: 0.4 }}>
                {t('prj.settleUp')}
              </span>
              {plan.map((row) => {
                const from = store.member(row.fromMemberID)
                const to = store.member(row.toMemberID)
                return (
                  <div key={`${row.fromMemberID}-${row.toMemberID}`} style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                    <span className="lg-clamp-1" style={{ fontSize: 14, color: C.ink }}>{from ? from.name : '—'}</span>
                    <Icon name="arrow.right" size={11} color={C.muted} />
                    <span className="lg-clamp-1" style={{ fontSize: 14, color: C.ink }}>{to ? to.name : '—'}</span>
                    <span className="lg-mono" style={{ fontSize: 14, fontWeight: 500, color: C.brand, flex: '1 1 auto' }}>
                      {money(row.amountMinor, store.baseCode)}
                    </span>
                    {canMutate ? (
                      <button
                        type="button"
                        className="lg-btn"
                        onClick={() => actions.settleUp(project, row)}
                        style={{
                          fontSize: 13, fontWeight: 500, color: C.onAccent, background: C.brand,
                          borderRadius: RADIUS.pill, padding: '5px 12px', flex: '0 0 auto',
                        }}
                      >
                        {t('prj.settle')}
                      </button>
                    ) : null}
                  </div>
                )
              })}
            </>
          )}
        </div>
      )}
    </Card>
  )
}

function MemberRow({ ctx, member, amount, canMutate }) {
  const { store, t, actions } = ctx
  const longPress = useLongPress(() => {
    if (!canMutate) return
    const items = [{ id: 'edit', label: t('x.edit'), icon: 'pencil', onSelect: () => actions.editMember(member) }]
    if (!member.isMe) {
      items.push({
        id: 'remove', label: t('x.remove'), icon: 'person.badge.minus', destructive: true,
        onSelect: () => actions.removeMember(member),
      })
    }
    actions.showMenu(items)
  })
  const tone = amount > 0 ? C.income : (amount < 0 ? C.expense : C.muted)
  const initial = (member.name || '?').trim().charAt(0).toUpperCase() || '?'

  return (
    <div {...longPress} style={{ display: 'flex', alignItems: 'center', gap: SPACE.s3 }}>
      <div style={{
        width: 32, height: 32, borderRadius: 16, flex: '0 0 auto',
        background: alpha(member.colorHex, 0.18), color: member.colorHex,
        display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 14, fontWeight: 500,
      }}
      >
        {initial}
      </div>
      <span className="lg-clamp-1" style={{ fontSize: 15, fontWeight: 500, color: C.ink }}>{member.name}</span>
      {member.isMe ? (
        <span style={{
          fontSize: 10, fontWeight: 500, color: C.muted, background: fade(C.muted, 12),
          borderRadius: RADIUS.pill, padding: '1px 6px', flex: '0 0 auto',
        }}
        >
          {t('prj.me')}
        </span>
      ) : null}
      <div style={{ flex: '1 1 auto' }} />
      <span className="lg-mono" style={{ fontSize: 14, fontWeight: 500, color: tone }}>
        {amount === 0 ? money(0, store.baseCode) : money(amount, store.baseCode, { signed: true })}
      </span>
    </div>
  )
}

// 项目页（LedgerProjectsView）。
// 「项目」= 正交于分类/账户/标签的分组维度：一笔可以同时属于项目 + 分类 + 账户 + 标签。

import React from 'react'
import { IconBadge } from './Icon.jsx'
import { Card, Divider, EmptyState, SectionHeader, useLongPress } from './primitives.jsx'
import { C, RADIUS, SPACE, alpha, fade } from './theme.js'
import { projectSpentMinor } from '../lib/split.js'
import { money, moneyCompact } from '../lib/money.js'
import { mediumDayDate } from '../lib/dates.js'

export default function ProjectsPage({ ctx }) {
  const { store, t, canMutate } = ctx
  const active = store.projects.filter((row) => !row.isArchived).sort((a, b) => a.sortOrder - b.sortOrder)
  const archived = store.projects.filter((row) => row.isArchived).sort((a, b) => a.sortOrder - b.sortOrder)

  if (active.length === 0 && archived.length === 0) {
    return (
      <div className="lg-scroll" style={{ flex: '1 1 auto', padding: SPACE.s4 }}>
        <EmptyState icon="folder.badge.plus" title={t('prj.emptyTitle')} body={t('prj.emptyBody')} />
      </div>
    )
  }

  return (
    <div className="lg-scroll" style={{ flex: '1 1 auto' }}>
      <div style={{ display: 'flex', flexDirection: 'column', gap: SPACE.s4, padding: SPACE.s4, paddingBottom: 96 }}>
        {active.length > 0 ? (
          <Card padding={0}>
            {active.map((project, index) => (
              <React.Fragment key={project.id}>
                {index > 0 ? <Divider inset={60} /> : null}
                <ProjectRow ctx={ctx} project={project} canMutate={canMutate} />
              </React.Fragment>
            ))}
          </Card>
        ) : null}

        {archived.length > 0 ? (
          <div>
            <SectionHeader>{t('x.archived')}</SectionHeader>
            <Card padding={0}>
              {archived.map((project, index) => (
                <React.Fragment key={project.id}>
                  {index > 0 ? <Divider inset={60} /> : null}
                  <ProjectRow ctx={ctx} project={project} canMutate={canMutate} archived />
                </React.Fragment>
              ))}
            </Card>
          </div>
        ) : null}
      </div>
    </div>
  )
}

function subtitleFor(project, t, locale) {
  const start = project.startOn ? mediumDayDate(project.startOn, locale) : null
  const end = project.endOn ? mediumDayDate(project.endOn, locale) : null
  if (start && end) return `${start} – ${end}`
  if (start) return t('prj.since', start)
  if (end) return null              // 只有止 → 不显示副标题
  return project.isActive ? t('prj.ongoing') : null
}

function ProjectRow({ ctx, project, canMutate, archived }) {
  const { store, t, locale, actions } = ctx
  const spent = projectSpentMinor(store, project.id)
  const subtitle = subtitleFor(project, t, locale)

  const longPress = useLongPress(() => {
    if (!canMutate) return
    const items = archived
      ? [{ id: 'restore', label: t('x.restore'), icon: 'arrow.uturn.backward', onSelect: () => actions.archiveProject(project, false) }]
      : [
        project.isActive
          ? { id: 'clear', label: t('prj.clearCurrent'), icon: 'circle.slash', onSelect: () => actions.clearCurrentProject() }
          : { id: 'set', label: t('prj.setCurrent'), icon: 'checkmark.circle', onSelect: () => actions.activateProject(project) },
        { id: 'edit', label: t('x.edit'), icon: 'pencil', onSelect: () => actions.editProject(project) },
        { id: 'archive', label: t('x.archive'), icon: 'archivebox', destructive: true, onSelect: () => actions.archiveProject(project, true) },
      ]
    actions.showMenu(items)
  })

  return (
    <button
      type="button"
      className="lg-btn"
      onClick={() => actions.openProject(project)}
      {...longPress}
      style={{ display: 'flex', alignItems: 'center', gap: SPACE.s3, width: '100%', padding: SPACE.s3 }}
    >
      <IconBadge
        name={project.systemImage}
        size={40}
        color={project.colorHex}
        background={alpha(project.colorHex, 0.16)}
      />
      <div style={{ flex: '1 1 auto', minWidth: 0, display: 'flex', flexDirection: 'column', gap: 3 }}>
        <span style={{ display: 'flex', alignItems: 'center', gap: 6, minWidth: 0 }}>
          <span className="lg-clamp-1" style={{ fontSize: 15, fontWeight: 500, color: C.ink }}>{project.name}</span>
          {project.isActive ? (
            <span style={{
              fontSize: 10, fontWeight: 500, color: C.brand, background: fade(C.brand, 14),
              borderRadius: RADIUS.pill, padding: '1px 6px', flex: '0 0 auto',
            }}
            >
              {t('prj.current')}
            </span>
          ) : null}
        </span>
        {subtitle ? <span className="lg-clamp-1" style={{ fontSize: 12, color: C.muted }}>{subtitle}</span> : null}
      </div>
      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 2 }}>
        <span className="lg-mono" style={{ fontSize: 16, fontWeight: 500, color: C.ink }}>
          {money(spent, store.baseCode)}
        </span>
        {project.budgetMinor > 0 ? (
          <span className="lg-mono" style={{ fontSize: 12, color: C.muted }}>
            {t('prj.of', moneyCompact(project.budgetMinor, store.baseCode))}
          </span>
        ) : null}
      </div>
    </button>
  )
}

// 最近删除（LedgerRecentlyDeletedView）。
// 左滑（leading，可整滑）→ 恢复；右滑（trailing，不允许整滑）→ 永久删除（带二次确认）。
// **转账两腿只展示一条**（以两个 id 里字典序较小的那个作为配对键去重）。

import React from 'react'
import { IconBadge } from './Icon.jsx'
import { Card, Divider, EmptyState, SwipeRow } from './primitives.jsx'
import { C, SPACE, alpha, fade } from './theme.js'
import { KIND } from '../lib/store.js'
import { recentlyDeleted } from '../lib/entries.js'
import { money } from '../lib/money.js'
import { shortDate } from '../lib/dates.js'
import { entryGlyph, entryPathTitle } from '../lib/display.js'

export default function RecentlyDeleted({ ctx }) {
  const { store, t, locale, actions, canMutate } = ctx
  const rows = React.useMemo(
    () => recentlyDeleted(store, 200),
    [store, store.revision], // eslint-disable-line react-hooks/exhaustive-deps
  )

  if (rows.length === 0) {
    return <EmptyState icon="trash" title={t('del.emptyTitle')} body={t('del.emptyBody')} />
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: SPACE.s3 }}>
      <Card padding={0}>
        {rows.map((txn, index) => {
          const glyph = entryGlyph(store, txn)
          const account = store.account(txn.accountID)
          const text = txn.kind === KIND.income
            ? money(txn.amountMinor, txn.currency, { signed: true })
            : (txn.kind === KIND.expense
              ? money(-txn.amountMinor, txn.currency)
              : (txn.kind === KIND.adjustment
                ? money(txn.signedAdjustment ?? 0, txn.currency, { signed: true })
                : money(txn.amountMinor, txn.currency)))
          const tone = txn.kind === KIND.income ? C.income : (txn.kind === KIND.expense ? C.ink : C.muted)

          const body = (
            <div style={{ display: 'flex', alignItems: 'center', gap: SPACE.s3, padding: SPACE.s3 }}>
              <IconBadge name={glyph.icon} size={34} color={glyph.color} background={alpha(glyph.color, 0.16)} />
              <div style={{ flex: '1 1 auto', minWidth: 0, display: 'flex', flexDirection: 'column', gap: 2 }}>
                <span className="lg-clamp-1" style={{ fontSize: 15, color: C.ink }}>
                  {entryPathTitle(store, txn, t)}
                </span>
                <span className="lg-clamp-1" style={{ fontSize: 12, color: C.muted }}>
                  {[account ? account.name : null, shortDate(txn.occurredOn, locale)].filter(Boolean).join(' · ')}
                </span>
              </div>
              <span className="lg-mono" style={{ fontSize: 15, fontWeight: 500, color: tone }}>{text}</span>
            </div>
          )

          return (
            <React.Fragment key={txn.id}>
              {index > 0 ? <Divider inset={50} /> : null}
              {canMutate ? (
                <SwipeRow
                  leading={{
                    label: t('x.restore'), icon: 'arrow.uturn.backward', fullSwipe: true,
                    onAction: () => actions.restoreEntry(txn),
                  }}
                  trailing={{
                    label: t('del.permanently'), icon: 'trash.slash', destructive: true, fullSwipe: false,
                    onAction: () => actions.purgeEntry(txn),
                  }}
                >
                  {body}
                </SwipeRow>
              ) : body}
            </React.Fragment>
          )
        })}
      </Card>
      <span style={{ fontSize: 12, color: C.muted, padding: '0 4px', lineHeight: 1.4 }}>
        {t('del.transferFooter')}
      </span>
    </div>
  )
}

// 报表页（LedgerReportsView）+ 下钻列表（LedgerFilteredTransactionsView）。
// 布局：月份条 → 收支切换 → 总额卡 →（占比卡）→（趋势卡）→（排行卡）。

import React from 'react'
import Icon, { IconBadge } from './Icon.jsx'
import { Card, Divider, EmptyState, MonthBar, Segmented } from './primitives.jsx'
import { ChartLegend, DonutChart, TimeBarChart, bucketColor } from './Charts.jsx'
import { C, SPACE, alpha } from './theme.js'
import { KIND } from '../lib/store.js'
import { buckets } from '../lib/queries.js'
import { monthFlowTransactions } from '../lib/reporting.js'
import { addMonths, monthKeyNow, monthTitle, shortDate } from '../lib/dates.js'
import { money } from '../lib/money.js'
import { entryPathTitle } from '../lib/display.js'

export default function ReportsPage({ ctx }) {
  const { store, t, locale, actions } = ctx
  const [monthKey, setMonthKey] = React.useState(monthKeyNow)
  const [metric, setMetric] = React.useState('expense')
  const [drill, setDrill] = React.useState(null)

  const rows = React.useMemo(
    () => monthFlowTransactions(store, monthKey),
    [store, store.revision, monthKey], // eslint-disable-line react-hooks/exhaustive-deps
  )
  const labels = { uncategorized: t('x.uncategorized'), noTag: t('x.noTag'), noProject: t('x.noProject') }
  const categoryBuckets = React.useMemo(
    () => buckets(store, rows, 'byCategory', metric, locale, labels),
    [store, rows, metric, locale], // eslint-disable-line react-hooks/exhaustive-deps
  )
  const dayBuckets = React.useMemo(
    () => buckets(store, rows, 'byDay', metric, locale, labels),
    [store, rows, metric, locale], // eslint-disable-line react-hooks/exhaustive-deps
  )
  const total = categoryBuckets.reduce((sum, bucket) => sum + bucket.amountMinor, 0)
  const isEmpty = rows.length === 0

  if (drill) {
    return (
      <DrillDown
        ctx={ctx}
        monthKey={monthKey}
        metric={metric}
        bucket={drill}
        onBack={() => setDrill(null)}
      />
    )
  }

  return (
    <div className="lg-scroll" style={{ flex: '1 1 auto' }}>
      <div style={{ display: 'flex', flexDirection: 'column', gap: SPACE.s4, padding: SPACE.s4, paddingBottom: 96 }}>
        <MonthBar
          title={monthTitle(monthKey, locale)}
          onPrevious={() => setMonthKey((key) => addMonths(key, -1))}
          onNext={() => setMonthKey((key) => addMonths(key, 1))}
          nextDisabled={monthKey >= monthKeyNow()}
        />
        <Segmented
          value={metric}
          onChange={setMetric}
          items={[{ id: 'expense', label: t('x.expense') }, { id: 'income', label: t('x.income') }]}
        />

        {isEmpty ? (
          <EmptyState icon="chart.pie" title={t('rep.emptyTitle')} body={t('rep.emptyBody')} />
        ) : (
          <>
            <Card>
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 6 }}>
                <span style={{ fontSize: 12, color: C.muted }}>
                  {metric === 'expense' ? t('rep.totalSpending') : t('rep.totalIncome')}
                </span>
                <span
                  className="lg-mono"
                  style={{ fontSize: 30, fontWeight: 500, color: metric === 'expense' ? C.expense : C.income }}
                >
                  {money(total, store.baseCode)}
                </span>
              </div>
            </Card>

            {categoryBuckets.length > 0 ? (
              <Card>
                <div style={{ fontSize: 13, fontWeight: 500, color: C.muted, marginBottom: SPACE.s3 }}>
                  {t('rep.byCategory')}
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: SPACE.s4 }}>
                  <DonutChart buckets={categoryBuckets} size={150} />
                  <ChartLegend buckets={categoryBuckets} currency={store.baseCode} />
                </div>
              </Card>
            ) : null}

            {dayBuckets.length >= 2 ? (
              <Card>
                <div style={{ fontSize: 13, fontWeight: 500, color: C.muted, marginBottom: SPACE.s3 }}>
                  {t('rep.dailyTrend')}
                </div>
                <TimeBarChart
                  buckets={dayBuckets}
                  currency={store.baseCode}
                  height={170}
                  color={metric === 'expense' ? C.expense : C.income}
                />
              </Card>
            ) : null}

            {categoryBuckets.length > 0 ? (
              <Card padding={0}>
                <div style={{ fontSize: 13, fontWeight: 500, color: C.muted, padding: `${SPACE.s4}px ${SPACE.s4}px ${SPACE.s2}px` }}>
                  {t('rep.ranking')}
                </div>
                {categoryBuckets.slice(0, 10).map((bucket, index) => (
                  <React.Fragment key={bucket.key}>
                    {index > 0 ? <Divider inset={SPACE.s4} /> : null}
                    <button
                      type="button"
                      className="lg-btn"
                      onClick={() => setDrill(bucket)}
                      style={{
                        display: 'flex', alignItems: 'center', gap: SPACE.s3, width: '100%',
                        padding: `11px ${SPACE.s4}px`,
                      }}
                    >
                      <span style={{
                        width: 9, height: 9, borderRadius: 4.5, flex: '0 0 auto',
                        background: bucketColor(bucket, index),
                      }}
                      />
                      <span className="lg-clamp-1" style={{ fontSize: 15, color: C.ink, flex: '1 1 auto', minWidth: 0 }}>
                        {bucket.label}
                      </span>
                      {total > 0 ? (
                        <span className="lg-mono" style={{ fontSize: 12, color: C.muted }}>
                          {Math.round((Math.abs(bucket.amountMinor) / Math.abs(total)) * 100)}%
                        </span>
                      ) : null}
                      <span className="lg-mono" style={{ fontSize: 14, fontWeight: 500, color: C.ink }}>
                        {money(Math.abs(bucket.amountMinor), store.baseCode)}
                      </span>
                      <Icon name="chevron.right" size={10} color={C.muted} />
                    </button>
                  </React.Fragment>
                ))}
              </Card>
            ) : null}
          </>
        )}
      </div>
    </div>
  )
}

/** 下钻列表：该月 + metric 对应 kind +（若来自分类桶）一级分类或其子分类。 */
function DrillDown({ ctx, monthKey, metric, bucket, onBack }) {
  const { store, t, locale, actions } = ctx
  const rows = React.useMemo(() => monthFlowTransactions(store, monthKey).filter((txn) => {
    if (metric === 'expense' && txn.kind !== KIND.expense) return false
    if (metric === 'income' && txn.kind !== KIND.income) return false
    if (bucket.key === '__uncat__') return !txn.categoryID
    const root = store.rootCategoryID(txn.categoryID)
    return txn.categoryID === bucket.key || root === bucket.key
  }), [store, store.revision, monthKey, metric, bucket]) // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <div className="lg-scroll" style={{ flex: '1 1 auto' }}>
      <div style={{ display: 'flex', flexDirection: 'column', gap: SPACE.s3, padding: SPACE.s4, paddingBottom: 96 }}>
        <button
          type="button"
          className="lg-btn"
          onClick={onBack}
          style={{ display: 'flex', alignItems: 'center', gap: 4, color: C.brand, fontSize: 15 }}
        >
          <Icon name="chevron.left" size={14} color={C.brand} />
          <span>{monthTitle(monthKey, locale)}</span>
        </button>

        {rows.length === 0 ? (
          <EmptyState icon="list.bullet.rectangle" title={t('tx.noMatchTitle')} body={t('rep.drillEmptyBody')} />
        ) : (
          <>
            <Card padding={0}>
              {rows.map((txn, index) => {
                const category = txn.categoryID ? store.category(txn.categoryID) : null
                const color = category ? category.colorHex : C.brand
                return (
                  <React.Fragment key={txn.id}>
                    {index > 0 ? <Divider inset={48} /> : null}
                    <button
                      type="button"
                      className="lg-btn"
                      onClick={() => actions.editEntry(txn)}
                      style={{ display: 'flex', alignItems: 'center', gap: SPACE.s3, width: '100%', padding: SPACE.s3 }}
                    >
                      <IconBadge
                        name={category ? (category.systemImage || 'tag') : 'tag'}
                        size={34}
                        color={color}
                        background={category ? alpha(category.colorHex, 0.16) : undefined}
                        style={category ? undefined : { background: 'color-mix(in srgb, var(--lg-brand) 16%, transparent)' }}
                      />
                      <div style={{ flex: '1 1 auto', minWidth: 0, display: 'flex', flexDirection: 'column', gap: 2 }}>
                        <span className="lg-clamp-1" style={{ fontSize: 15, color: C.ink }}>
                          {entryPathTitle(store, txn, t)}
                        </span>
                        <span className="lg-clamp-1" style={{ fontSize: 12, color: C.muted }}>
                          {[store.account(txn.accountID)?.name, txn.note].filter(Boolean).join(' · ')}
                        </span>
                      </div>
                      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 2 }}>
                        <span className="lg-mono" style={{ fontSize: 14, fontWeight: 500, color: C.ink }}>
                          {money(txn.kind === KIND.income ? txn.amountMinor : -txn.amountMinor, txn.currency, {
                            signed: txn.kind === KIND.income,
                          })}
                        </span>
                        <span className="lg-mono" style={{ fontSize: 10, color: C.muted }}>
                          {shortDate(txn.occurredOn, locale)}
                        </span>
                      </div>
                    </button>
                  </React.Fragment>
                )
              })}
            </Card>
            <span style={{ fontSize: 12, color: C.muted, padding: '0 4px', lineHeight: 1.4 }}>
              {t('rep.drillFooter')}
            </span>
          </>
        )}
      </div>
    </div>
  )
}

// 根级弹层清单 —— 一一对应原生的「根视图弹层」那一组：
// 记一笔 / AI 面板 / 账户编辑器 / 项目编辑器 / 预算编辑器 / 成员编辑器 / 余额校准 /
// 汇率编辑 / 币种管理 / 添加币种 / CSV 导入预览 / 最近删除。
//
// 每个「保存」都在写完之后看 `store.lastMutationSucceeded`（经 failIfNeeded）——
// 写失败时弹层**不关闭**，也不假装成功。

import React from 'react'
import { Sheet, SheetButton } from './primitives.jsx'
import { C, SPACE } from './theme.js'
import EntryEditor from './EntryEditor.jsx'
import SplitEditor from './SplitEditor.jsx'
import CurrencyManager from './CurrencyManager.jsx'
import RecentlyDeleted from './RecentlyDeleted.jsx'
import CSVImportPreview from './CSVImportPreview.jsx'
import AIPanel from './AIPanel.jsx'
import {
  AccountEditor, BudgetEditor, MemberEditor, ProjectEditor, RateEditor, ReconcileSheet,
} from './Editors.jsx'
import {
  addMember, createAccount, createProject, setRate, updateAccount, updateMember, updateProject, upsertBudget,
} from '../lib/entities.js'
import { setBalance } from '../lib/balances.js'
import { performImport } from '../lib/csv.js'
import { nativeAlert } from '../lib/host.js'

/** ⋯ 菜单固定顺序：AI 分析（仅有 AI 时）/ 导出 CSV / 导入 CSV / 最近删除。 */
export function overflowItems({ t, caps, canMutate, setSheet, doExport, doImport }) {
  const items = []
  if (caps.ai) items.push({ id: 'ai', label: t('menu.ai'), icon: 'sparkles', onSelect: () => setSheet({ kind: 'ai' }) })
  if (caps.share) items.push({ id: 'export', label: t('menu.exportCSV'), icon: 'square.and.arrow.up', onSelect: doExport })
  if (caps.picker && canMutate) {
    items.push({ id: 'import', label: t('menu.importCSV'), icon: 'square.and.arrow.down', onSelect: doImport })
  }
  items.push({
    id: 'deleted', label: t('menu.recentlyDeleted'), icon: 'trash',
    onSelect: () => setSheet({ kind: 'recentlyDeleted' }),
  })
  return items
}

export default function Sheets({ sheet, setSheet, ctx, submitRef, failIfNeeded }) {
  if (!sheet) return null
  const { store, t } = ctx
  const close = () => setSheet(null)

  const formSheet = ({ title, detent, body, onSave, saveLabel }) => (
    <Sheet
      open
      onClose={close}
      title={title}
      detent={detent}
      leading={<SheetButton onClick={close}>{t('x.cancel')}</SheetButton>}
      trailing={<SheetButton bold onClick={onSave}>{saveLabel ?? t('x.save')}</SheetButton>}
    >
      {body}
    </Sheet>
  )

  switch (sheet.kind) {
    case 'entry':
      // 记一笔是全高面板（自带底部计算器键盘），不走通用 formSheet。
      return (
        <div className="lg-backdrop" onClick={(event) => { if (event.target === event.currentTarget) close() }}>
          <div className="lg-sheet" style={{ height: 'calc(100dvh - 40px)' }}>
            <div style={{
              display: 'flex', alignItems: 'center', padding: `${SPACE.s3}px ${SPACE.s4}px`,
              borderBottom: `1px solid ${C.line}`, flex: '0 0 auto',
            }}
            >
              <SheetButton onClick={close}>{t('x.cancel')}</SheetButton>
              <span style={{ flex: '1 1 auto', textAlign: 'center', fontSize: 16, fontWeight: 500 }}>
                {sheet.editing ? t('ent.edit') : t('ent.new')}
              </span>
              <span style={{ minWidth: 44 }} />
            </div>
            <EntryEditor ctx={ctx} editing={sheet.editing} onClose={close} />
          </div>
        </div>
      )

    case 'account':
      return formSheet({
        title: sheet.editing ? t('acc.edit') : t('acc.new'),
        body: <AccountEditor ctx={ctx} editing={sheet.editing} onSubmit={submitRef} />,
        onSave: async () => {
          const value = submitRef.current()
          if (!value.valid) return
          if (sheet.editing) await updateAccount(store, sheet.editing.id, value)
          else await createAccount(store, value)
          if (await failIfNeeded()) close()
        },
      })

    case 'project':
      return formSheet({
        title: sheet.editing ? t('prj.edit') : t('prj.new'),
        body: <ProjectEditor ctx={ctx} editing={sheet.editing} onSubmit={submitRef} />,
        onSave: async () => {
          const value = submitRef.current()
          if (!value.valid) return
          if (sheet.editing) await updateProject(store, sheet.editing.id, value)
          else await createProject(store, value)
          if (await failIfNeeded()) close()
        },
      })

    case 'budget':
      return formSheet({
        title: t('x.budget'),
        detent: 360,
        body: <BudgetEditor ctx={ctx} monthKey={ctx.monthKey} categoryID={sheet.categoryID} onSubmit={submitRef} />,
        onSave: async () => {
          const value = submitRef.current()
          await upsertBudget(store, value.monthKey, value.categoryID, value.limitMinor, value.carryover)
          if (await failIfNeeded()) close()
        },
      })

    case 'member':
      return formSheet({
        title: sheet.editing ? t('prj.editMember') : t('prj.newMember'),
        detent: 320,
        body: (
          <MemberEditor
            ctx={ctx}
            editing={sheet.editing}
            order={store.projectMembers(sheet.projectID).length}
            onSubmit={submitRef}
          />
        ),
        onSave: async () => {
          const value = submitRef.current()
          if (!value.valid) return
          if (sheet.editing) await updateMember(store, sheet.editing.id, value)
          else await addMember(store, sheet.projectID, value)
          if (await failIfNeeded()) close()
        },
      })

    case 'reconcile':
      return formSheet({
        title: sheet.account.name,
        detent: 320,
        body: <ReconcileSheet ctx={ctx} account={sheet.account} onSubmit={submitRef} />,
        onSave: async () => {
          const value = submitRef.current()
          if (!value.valid) return
          await setBalance(store, sheet.account, value.targetMinor)
          if (await failIfNeeded()) close()
        },
      })

    case 'rate':
      return formSheet({
        title: sheet.code,
        detent: 280,
        body: <RateEditor ctx={ctx} code={sheet.code} onSubmit={submitRef} />,
        onSave: async () => {
          const value = submitRef.current()
          if (!value.valid) return
          await setRate(store, value.code, value.rate)
          if (await failIfNeeded()) setSheet({ kind: 'currencies' })
        },
      })

    case 'split':
      return formSheet({
        title: t('ent.split'),
        saveLabel: t('x.done'),
        body: <SplitEditor ctx={ctx} request={sheet.request} onSubmit={submitRef} />,
        onSave: () => {
          const value = submitRef.current()
          if (!value.valid) return
          sheet.request.onDone(value.split)
          close()
        },
      })

    case 'currencies':
      return (
        <Sheet
          open
          onClose={close}
          title={t('acc.currencies')}
          leading={<SheetButton onClick={close}>{t('x.done')}</SheetButton>}
        >
          <CurrencyManager ctx={ctx} />
        </Sheet>
      )

    case 'addCurrency':
      return (
        <Sheet
          open
          onClose={() => setSheet({ kind: 'currencies' })}
          title={t('cur.add')}
          leading={<SheetButton onClick={() => setSheet({ kind: 'currencies' })}>{t('x.cancel')}</SheetButton>}
        >
          <CurrencyManager ctx={ctx} mode="add" />
        </Sheet>
      )

    case 'recentlyDeleted':
      return (
        <Sheet
          open
          onClose={close}
          title={t('menu.recentlyDeleted')}
          trailing={<SheetButton bold onClick={close}>{t('x.done')}</SheetButton>}
        >
          <RecentlyDeleted ctx={ctx} />
        </Sheet>
      )

    case 'csvPreview': {
      const draft = sheet.draft
      // 「导入」**仅当「有效行非空 且 问题数为 0」才可点**。
      const importable = (draft.rows ?? []).length > 0 && (draft.problems ?? []).length === 0
      return (
        <Sheet
          open
          onClose={close}
          title={t('csv.title')}
          leading={<SheetButton onClick={close}>{t('x.cancel')}</SheetButton>}
          trailing={(
            <SheetButton
              bold
              disabled={!importable}
              onClick={async () => {
                const result = await performImport(store, draft.rows)
                close()
                await nativeAlert({
                  title: t('import.complete'),
                  message: t('import.summary', result.imported, result.skipped, result.failed),
                })
              }}
            >
              {t('csv.import')}
            </SheetButton>
          )}
        >
          <CSVImportPreview ctx={ctx} draft={draft} />
        </Sheet>
      )
    }

