export default function TransactionsPage({ ctx }) {
  const { store, t, locale, query, actions, canMutate } = ctx
  const [visibleMonths, setVisibleMonths] = React.useState(3)
  const [typeFilter, setTypeFilter] = React.useState('all')
  const [accountFilter, setAccountFilter] = React.useState(null)
  const [projectFilter, setProjectFilter] = React.useState(null)
  const [menu, setMenu] = React.useState(null)

  const currentProject = store.currentProject()
  const accounts = store.activeAccounts()
  const projects = store.activeProjects()

  // 分段加载（不是分页）：只查「当前月往前数第 N 个月的 1 号」之后的全部流水，无上界。
  const since = React.useMemo(() => {
    try {
      return monthStart(addMonths(monthKeyNow(), -(visibleMonths - 1)))
    } catch (error) {
      return null
    }
  }, [visibleMonths])

  const loaded = React.useMemo(() => {
    const all = store.allTransactions()
    // 月份运算失败的兜底：取最近 500 条。
    return since === null ? all.slice(0, 500) : all.filter((txn) => txn.occurredOn >= since)
  }, [store, store.revision, since]) // eslint-disable-line react-hooks/exhaustive-deps

  const filtered = React.useMemo(() => loaded.filter((txn) => {
    if (typeFilter === 'expense' && txn.kind !== KIND.expense) return false
    if (typeFilter === 'income' && txn.kind !== KIND.income) return false
    if (typeFilter === 'transfer' && txn.kind !== KIND.transferOut && txn.kind !== KIND.transferIn) return false
    if (accountFilter && txn.accountID !== accountFilter) return false
    if (projectFilter && txn.projectID !== projectFilter) return false
    return matchesSearch(store, txn, query)
  }), [loaded, typeFilter, accountFilter, projectFilter, query, store])

  const groups = React.useMemo(() => groupByDay(filtered), [filtered])

  const hasFilter = typeFilter !== 'all' || accountFilter || projectFilter || String(query ?? '').trim().length > 0
  const accountName = accountFilter
    ? (store.account(accountFilter)?.name ?? t('tx.allAccounts'))
    : t('tx.allAccounts')
  const projectName = projectFilter
    ? (store.project(projectFilter)?.name ?? t('tx.allProjects'))
    : t('tx.allProjects')
  const typeLabel = { all: t('x.all'), expense: t('x.expense'), income: t('x.income'), transfer: t('x.transfer') }[typeFilter]

  const clearFilters = () => {
    setTypeFilter('all')
    setAccountFilter(null)
    setProjectFilter(null)
    actions.setQuery('')
  }

  const header = (
    <div style={{ display: 'flex', flexDirection: 'column', gap: SPACE.s4, padding: SPACE.s4, paddingBottom: 0 }}>
      {currentProject ? (
        <div style={{
          display: 'flex', alignItems: 'center', gap: SPACE.s2, background: fade(C.brand, 10),
          borderRadius: RADIUS.pill, padding: '8px 12px',
        }}
        >
          <Icon name={currentProject.systemImage || 'folder'} size={12} color={C.brand} />
          <span className="lg-clamp-1" style={{ fontSize: 12, color: C.ink, flex: '1 1 auto' }}>
            {t('tx.recordingInto', currentProject.name)}
          </span>
          {canMutate ? (
            <button
              type="button"
              className="lg-btn"
              aria-label={t('tx.clearCurrentProject')}
              onClick={() => actions.clearCurrentProject()}
            >
              <Icon name="xmark.circle.fill" size={14} color={C.muted} />
            </button>
          ) : null}
        </div>
      ) : null}

      <SummaryCard store={store} t={t} />

      <div className="lg-chips">
        <Chip
          label={typeLabel}
          selected={typeFilter !== 'all'}
          onClick={() => setMenu('type')}
        />
        <Chip label={accountName} selected={!!accountFilter} onClick={() => setMenu('account')} />
        {projects.length > 0 ? (
          <Chip label={projectName} selected={!!projectFilter} onClick={() => setMenu('project')} />
        ) : null}
        {hasFilter ? (
          <button
            type="button"
            className="lg-btn"
            onClick={clearFilters}
            style={{ display: 'flex', alignItems: 'center', gap: 4, color: C.brand, fontSize: 12, flex: '0 0 auto', padding: '7px 4px' }}
          >
            <Icon name="xmark.circle" size={12} color={C.brand} />
            <span>{t('tx.clearFilters')}</span>
          </button>
        ) : null}
      </div>
    </div>
  )

  const footer = (
    <div style={{ padding: `0 ${SPACE.s4}px`, paddingBottom: 96 }}>
      {groups.length > 0 ? (
        <button
          type="button"
          className="lg-btn"
          onClick={() => setVisibleMonths((count) => count + 3)}
          style={{
            display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6, width: '100%',
            height: 44, borderRadius: RADIUS.field, background: fade(C.brand, 10), color: C.brand, fontSize: 15,
          }}
        >
          <Icon name="clock.arrow.circlepath" size={15} color={C.brand} />
          <span>{t('tx.loadOlder')}</span>
        </button>
      ) : null}
    </div>
  )

  const empty = loaded.length === 0
    ? <EmptyState icon="tray" title={t('tx.emptyTitle')} body={t('tx.emptyBody')} />
    : <EmptyState icon="line.3.horizontal.decrease.circle" title={t('tx.noMatchTitle')} body={t('tx.noMatchBody')} />

  return (
    <>
      <VirtualList
        className="lg-scroll"
        style={{ flex: '1 1 auto' }}
        items={groups}
        keyExtractor={(group) => group.day}
        estimatedRowHeight={140}
        restoreKey="transactions"
        header={header}
        footer={groups.length === 0
          ? <div style={{ padding: `${SPACE.s6}px ${SPACE.s4}px 96px` }}>{empty}</div>
          : footer}
        renderRow={(group) => (
          <div style={{ padding: `0 ${SPACE.s4}px` }}>
            <DayGroup
              store={store}
              group={group}
              t={t}
              locale={locale}
              canMutate={canMutate}
              onOpen={actions.editEntry}
              onDelete={actions.deleteEntry}
            />
          </div>
        )}
      />

      <Menu
        open={menu === 'type'}
        onClose={() => setMenu(null)}
        items={[
          { id: 'all', label: t('x.all'), selected: typeFilter === 'all', onSelect: () => setTypeFilter('all') },
          { id: 'expense', label: t('x.expense'), selected: typeFilter === 'expense', onSelect: () => setTypeFilter('expense') },
          { id: 'income', label: t('x.income'), selected: typeFilter === 'income', onSelect: () => setTypeFilter('income') },
          { id: 'transfer', label: t('x.transfer'), selected: typeFilter === 'transfer', onSelect: () => setTypeFilter('transfer') },
        ]}
      />
      <Menu
        open={menu === 'account'}
        onClose={() => setMenu(null)}
        items={[
          { id: 'all', label: t('tx.allAccounts'), selected: !accountFilter, onSelect: () => setAccountFilter(null) },
          ...accounts.map((account) => ({
            id: account.id, label: account.name, selected: accountFilter === account.id,
            onSelect: () => setAccountFilter(account.id),
          })),
        ]}
      />
      <Menu
        open={menu === 'project'}
        onClose={() => setMenu(null)}
        items={[
          { id: 'all', label: t('tx.allProjects'), selected: !projectFilter, onSelect: () => setProjectFilter(null) },
          ...projects.map((project) => ({
            id: project.id, label: project.name, selected: projectFilter === project.id,
            onSelect: () => setProjectFilter(project.id),
          })),
        ]}
      />
    </>
  )
}

// 语言：跟随宿主有效 UI 语言（documentStart 就写好的 window.__aiboxEnvironment），
// 并监听 aibox.events 的 environment.localeChanged 重渲染（不重载 WebView）。
//
// 记账多一条纪律：**首启种子分类/账户名按当时的 App 内语言物化，之后永不回灌**，
// 所以 open() 前必须先拿到正确的 locale（见 app.jsx 的启动顺序）。

import { STRINGS } from './strings.js'

export function normalizeLocale(locale) {
  const raw = String(locale || 'en').toLowerCase()
  return raw.startsWith('zh') ? 'zh-Hans' : 'en'
}

export function currentLocale() {
  const env = typeof window !== 'undefined' ? window.__aiboxEnvironment : null
  return normalizeLocale(env && (env.locale || env.language))
}

export function onLocaleChanged(handler) {
  const bus = typeof window !== 'undefined' && window.aibox && window.aibox.events
  if (!bus || typeof bus.on !== 'function') return () => {}
  return bus.on('environment.localeChanged', (payload) => {
    handler(normalizeLocale(payload && (payload.locale || payload.language)))
  })
}

/** 取一条文案。缺键回落 en，再回落键名本身（漏键会显形，不会渲染成空白）。 */
export function translate(locale, key) {
  const table = STRINGS[locale] || STRINGS.en
  if (table[key] !== undefined) return table[key]
  if (STRINGS.en[key] !== undefined) return STRINGS.en[key]
  return key
}

export function fmt(template, ...args) {
  return String(template).replace(/\{(\d+)\}/g, (whole, index) => {
    const value = args[Number(index)]
    return value === undefined || value === null ? whole : String(value)
  })
}

export function makeT(locale) {
  return (key, ...args) => {
    const value = translate(locale, key)
    return args.length > 0 ? fmt(value, ...args) : value
  }
}

export function bcp47(locale) {
  return locale === 'zh-Hans' ? 'zh-CN' : 'en-US'
}

// AI 工具面（续）：账户 / 分类 / 币种 / 项目+AA 四个工具。
// 与 actions.js 同一套纪律：无 UI 也能跑、走同一条 WAL 写路径、金额第一步转整数分。

import { money, majorNumberToMinor } from './money.js'
import { normalizeCurrencyCode } from './currencies.js'
import { monthTitle } from './dates.js'
import { buckets, filterTransactions } from './queries.js'
import { balancesByAccount, netWorth, setBalance } from './balances.js'
import {
  activateProject, addCurrency, addMember, applyFetchedRates, archiveAccount, createAccount,
  createCategory, createProject, removeMember, setBaseCurrency, setRate, updateAccount,
  updateCategory, updateProject,
} from './entities.js'
import { isNoneToken, resolveAccount, resolveCategory, resolveMember, resolveProject } from './resolve.js'
import { memberBalances, projectIncomeMinor, projectSpentMinor, recordSettlement, settlementPlan } from './split.js'
import { fetchRates } from './fx.js'
import { httpGetJSON } from './host.js'
import { PERSISTENCE_FAILURE, actionCandidatesText, actionDone, actionFail, parseFlexibleDate } from './actions.js'

const fail = actionFail
const done = actionDone
const candidatesText = actionCandidatesText

export async function actionAccount(store, args, locale) {
  const action = String(args.action ?? 'list').toLowerCase()

  if (action === 'create') {
    const result = await createAccount(store, {
      name: args.name,
      kind: args.kind ?? 'cash',
      currency: normalizeCurrencyCode(args.currency ?? store.baseCode),
      initialBalanceMinor: majorNumberToMinor(args.initial_balance ?? 0),
      creditLimitMinor: majorNumberToMinor(args.credit_limit ?? 0),
      includeInNetWorth: args.include_in_net_worth !== false,
    })
    if (!result.ok) return fail(result.reason === 'emptyName' ? 'create needs a name.' : PERSISTENCE_FAILURE)
    return done(`Created account "${result.account.name}" (${result.account.kind}, ${result.account.currency}).`,
      { id: result.account.id })
  }

  const target = args.account || args.name
  if (['set_balance', 'archive', 'update'].includes(action)) {
    const resolved = resolveAccount(store, target, args.currency)
    if (!resolved.found) return fail(candidatesText('account', resolved.candidates))
    const account = resolved.value

    if (action === 'set_balance') {
      if (args.balance === undefined || args.balance === null) return fail('set_balance needs balance.')
      const result = await setBalance(store, account, majorNumberToMinor(args.balance))
      if (!result.ok) return fail(PERSISTENCE_FAILURE)
      if (result.noop) return done(`"${account.name}" already matches that balance — nothing to adjust.`)
      return done(`Adjusted "${account.name}" by ${money(result.delta, account.currency, { signed: true })}.`,
        { deltaMinor: result.delta })
    }
    if (action === 'archive') {
      const result = await archiveAccount(store, account.id, args.archived !== false)
      if (!result.ok) return fail(PERSISTENCE_FAILURE)
      return done(`${args.archived === false ? 'Restored' : 'Archived'} account "${account.name}".`)
    }
    const result = await updateAccount(store, account.id, {
      name: args.new_name ?? args.name,
      kind: args.kind,
      includeInNetWorth: args.include_in_net_worth,
      creditLimitMinor: args.credit_limit !== undefined ? majorNumberToMinor(args.credit_limit) : undefined,
    })
    if (!result.ok) return fail(PERSISTENCE_FAILURE)
    return done(`Updated account "${account.name}".`)
  }

  const balances = balancesByAccount(store)
  const worth = netWorth(store, balances)
  const lines = store.activeAccounts().map((account) => {
    const own = money(balances[account.id] ?? 0, account.currency)
    const base = account.currency === store.baseCode
      ? ''
      : ` ≈ ${money(store.toBaseMinor(balances[account.id] ?? 0, account.currency), store.baseCode)}`
    return `${account.name} (${account.kind}, ${account.currency}): ${own}${base} [id: ${account.id}]`
  })
  return done(
    `Net worth ${money(worth.net, store.baseCode)} · assets ${money(worth.assets, store.baseCode)} · `
    + `liabilities ${money(worth.liabilities, store.baseCode)}\n${lines.join('\n')}`,
    { netWorthMinor: worth.net, assetsMinor: worth.assets, liabilitiesMinor: worth.liabilities, baseCurrency: store.baseCode },
  )
}

export async function actionCategory(store, args, locale) {
  const action = String(args.action ?? 'list').toLowerCase()
  const kind = args.kind === 'income' ? 'income' : 'expense'

  if (action === 'create') {
    let parentID = null
    if (args.parent) {
      const resolved = resolveCategory(store, args.parent, kind)
      if (!resolved.found) return fail(candidatesText('parent category', resolved.candidates))
      parentID = resolved.value.id
    }
    const result = await createCategory(store, { name: args.name, kind, parentID })
    if (!result.ok) return fail(result.reason === 'emptyName' ? 'create needs a name.' : PERSISTENCE_FAILURE)
    return done(`Created category "${store.categoryPath(result.category.id)}".`, { id: result.category.id })
  }

  if (action === 'rename' || action === 'archive') {
    const resolved = resolveCategory(store, args.name, kind)
    if (!resolved.found) return fail(candidatesText('category', resolved.candidates))
    const patch = action === 'rename' ? { name: args.new_name } : { isArchived: args.archived !== false }
    if (action === 'rename' && !String(args.new_name ?? '').trim()) return fail('rename needs new_name.')
    const result = await updateCategory(store, resolved.value.id, patch)
    if (!result.ok) return fail(PERSISTENCE_FAILURE)
    return done(action === 'rename'
      ? `Renamed to "${String(args.new_name).trim()}".`
      : `${args.archived === false ? 'Restored' : 'Archived'} "${resolved.value.name}".`)
  }

  const roots = store.rootCategories(kind)
  const lines = roots.map((root) => {
    const children = store.childCategories(root.id)
    return children.length > 0 ? `${root.name}: ${children.map((row) => row.name).join(', ')}` : root.name
  })
  return done(`${kind} categories:\n${lines.join('\n')}`, { categories: lines })
}

export async function actionCurrency(store, args, locale) {
  const action = String(args.action ?? 'list').toLowerCase()
  const code = args.code ? normalizeCurrencyCode(args.code) : null

  if (action === 'add') {
    if (!code || code.length !== 3) return fail('add needs a 3-letter ISO currency code.')
    const result = await addCurrency(store, code, args.rate)
    if (!result.ok) return fail(PERSISTENCE_FAILURE)
    const configured = Number(args.rate) > 0
    return done(configured
      ? `Added ${code} at 1 ${code} = ${Number(args.rate)} ${store.baseCode}.`
      : `Added ${code} without a rate — it is EXCLUDED from converted totals until a real rate is configured.`)
  }
  if (action === 'set_rate') {
    if (!code) return fail('set_rate needs code.')
    const result = await setRate(store, code, args.rate)
    if (!result.ok) return fail(result.reason === 'invalidRate' ? 'rate must be greater than 0.' : PERSISTENCE_FAILURE)
    return done(`1 ${code} = ${Number(args.rate)} ${store.baseCode} (marked manual; online refresh will not overwrite it).`)
  }
  if (action === 'set_preferred') {
    if (!code) return fail('set_preferred needs code.')
    const result = await setBaseCurrency(store, code)
    if (!result.ok) {
      return fail(result.reason === 'rateNeeded'
        ? `${code} has no configured rate yet — set one before making it the base currency.`
        : PERSISTENCE_FAILURE)
    }
    return done(`Base currency is now ${code}. All stats, net worth and budgets are priced in it.`)
  }
  if (action === 'refresh') {
    const rates = await fetchRates(store.baseCode, httpGetJSON)
    if (!rates) return fail('Could not fetch live rates just now. Set them manually with set_rate.')
    const result = await applyFetchedRates(store, rates)
    if (!result.ok) return fail(PERSISTENCE_FAILURE)
    return done(result.changed ? 'Exchange rates refreshed.' : 'Rates were already up to date.')
  }

  const lines = store.currencies.map((row) => (row.isBase
    ? `${row.code} (base)`
    : `1 ${row.code} = ${row.rateConfigured ? Number(row.rateToBase).toFixed(4) : 'no rate'} ${store.baseCode}`
      + `${row.manualRate ? ' (manual)' : ''}`))
  return done(`Base currency ${store.baseCode}.\n${lines.join('\n')}`, { baseCurrency: store.baseCode })
}

export async function actionProject(store, args, locale) {
  const action = String(args.action ?? 'list').toLowerCase()

  if (action === 'create') {
    const result = await createProject(store, {
      name: args.name,
      budgetMinor: majorNumberToMinor(args.budget ?? 0),
      startOn: args.start ? parseFlexibleDate(args.start) : null,
      endOn: args.end ? parseFlexibleDate(args.end) : null,
      isActive: !!args.activate,
    })
    if (!result.ok) return fail(result.reason === 'emptyName' ? 'create needs a name.' : PERSISTENCE_FAILURE)
    return done(`Created project "${result.project.name}".`, { id: result.project.id })
  }
  if (action === 'activate') {
    if (isNoneToken(args.name)) {
      const result = await activateProject(store, null)
      return result.ok ? done('Cleared the current project.') : fail(PERSISTENCE_FAILURE)
    }
    const resolved = resolveProject(store, args.name)
    if (!resolved.found) return fail(candidatesText('project', resolved.candidates))
    const result = await activateProject(store, resolved.value.id)
    return result.ok ? done(`"${resolved.value.name}" is now the current project.`) : fail(PERSISTENCE_FAILURE)
  }

  if (action === 'list') {
    const rows = store.projects.map((project) => {
      const spent = projectSpentMinor(store, project.id)
      return `${project.name}${project.isActive ? ' (current)' : ''}${project.isArchived ? ' (archived)' : ''}: `
        + `${money(spent, store.baseCode)}`
        + `${project.budgetMinor > 0 ? ` / ${money(project.budgetMinor, store.baseCode)}` : ''} [id: ${project.id}]`
    })
    return done(rows.length > 0 ? rows.join('\n') : 'No projects yet.', { count: store.projects.length })
  }

  const resolved = resolveProject(store, args.name)
  if (!resolved.found) return fail(candidatesText('project', resolved.candidates))
  const project = resolved.value

  switch (action) {
    case 'update': {
      const result = await updateProject(store, project.id, {
        name: args.new_name,
        budgetMinor: args.budget !== undefined ? majorNumberToMinor(args.budget) : undefined,
        startOn: args.start ? parseFlexibleDate(args.start) : undefined,
        endOn: args.end ? parseFlexibleDate(args.end) : undefined,
      })
      return result.ok ? done(`Updated project "${project.name}".`) : fail(PERSISTENCE_FAILURE)
    }
    case 'archive': {
      const result = await updateProject(store, project.id, { isArchived: args.archived !== false })
      return result.ok ? done(`${args.archived === false ? 'Restored' : 'Archived'} "${project.name}".`) : fail(PERSISTENCE_FAILURE)
    }
    case 'members': {
      const rows = store.projectMembers(project.id).map((row) => `${row.name}${row.isMe ? ' (me)' : ''} [id: ${row.id}]`)
      return done(rows.length > 0 ? rows.join('\n') : 'No members yet.', { count: rows.length })
    }
    case 'add_member': {
      const name = String(args.member ?? '').trim()
      if (name.length === 0) return fail('add_member needs member.')
      // 项目还没成员且这次不是加「我」→ 先自动补一个名为 "Me" 的自己。
      if (store.projectMembers(project.id).length === 0 && !args.is_me) {
        const seeded = await addMember(store, project.id, { name: 'Me', isMe: true })
        if (!seeded.ok) return fail(PERSISTENCE_FAILURE)
      }
      const result = await addMember(store, project.id, { name, isMe: !!args.is_me })
      return result.ok ? done(`Added member "${name}".`, { id: result.member.id }) : fail(PERSISTENCE_FAILURE)
    }
    case 'remove_member': {
      const resolvedMember = resolveMember(store, project.id, args.member)
      if (!resolvedMember.found) return fail(candidatesText('member', resolvedMember.candidates))
      const result = await removeMember(store, resolvedMember.value.id)
      return result.ok ? done(`Removed member "${resolvedMember.value.name}".`) : fail(PERSISTENCE_FAILURE)
    }
    case 'settle': {
      const net = memberBalances(store, project.id)
      const plan = settlementPlan(store, project.id)
      const balanceLines = store.projectMembers(project.id)
        .map((row) => `${row.name}: ${money(net[row.id] ?? 0, store.baseCode, { signed: true })}`)
      const planLines = plan.map((row) => {
        const from = store.member(row.fromMemberID)
        const to = store.member(row.toMemberID)
        return `${from ? from.name : '?'} → ${to ? to.name : '?'} ${money(row.amountMinor, store.baseCode)}`
      })
      return done(
        `${balanceLines.join('\n')}\n${planLines.length > 0 ? `Settle up:\n${planLines.join('\n')}` : "Everyone's settled up."}`,
        { balances: net, plan },
      )
    }
    case 'record_settlement': {
      const from = resolveMember(store, project.id, args.from)
      const to = resolveMember(store, project.id, args.to)
      if (!from.found) return fail(candidatesText('member', from.candidates))
      if (!to.found) return fail(candidatesText('member', to.candidates))
      const result = await recordSettlement(store, project.id, from.value.id, to.value.id, majorNumberToMinor(args.amount ?? 0))
      if (!result.ok) return fail(result.reason === 'invalidAmount' ? 'amount must be greater than 0.' : PERSISTENCE_FAILURE)
      return done(`Recorded ${from.value.name} → ${to.value.name} ${money(result.settlement.amountBaseMinor, store.baseCode)}.`,
        { id: result.settlement.id, linkedTransactionID: result.settlement.linkedTransactionID })
    }
    default: {
      const spent = projectSpentMinor(store, project.id)
      const income = projectIncomeMinor(store, project.id)
      const rows = filterTransactions(store, { projectID: project.id })
      const list = buckets(store, rows, 'byCategory', 'expense', locale)
      const lines = list.slice(0, 10).map((bucket) => `${bucket.label}: ${money(bucket.amountMinor, store.baseCode)}`)
      return done(
        `"${project.name}" — spent ${money(spent, store.baseCode)}`
        + `${income > 0 ? `, income ${money(income, store.baseCode)}` : ''}`
        + `${project.budgetMinor > 0 ? `, budget ${money(project.budgetMinor, store.baseCode)}` : ''}`
        + `, ${rows.length} entries.\n${lines.join('\n')}`,
        { spentMinor: spent, incomeMinor: income, budgetMinor: project.budgetMinor, buckets: list },
      )
    }
  }
}

// AI 工具面（对应原生 8 个 `ledger_*` 工具，§8.4）。
//
// 三条纪律：
//  1. **无 UI 也能跑**：只依赖 store 与 lib/ 里的纯函数，不碰任何 React 状态；
//  2. **同一条写路径**：全部走 store.mutate → WAL，绝不绕过去直接写库；
//     写完必须看 `store.lastMutationSucceeded`，失败返回明确的「未保存」错误文本；
//  3. **金额第一步就转整数分**：AI 给的是浮点主单位，进系统立刻 majorNumberToMinor。

import { KIND } from './store.js'
import { majorNumberToMinor, money } from './money.js'
import { normalizeCurrencyCode } from './currencies.js'
import { dayStart, isoDay, monthKeyOf, monthTitle, parseISODay, DAY_MS } from './dates.js'
import { buckets, filterTransactions, periodRange } from './queries.js'
import { budgetPayload } from './reporting.js'
import { deleteEntry, findByIdempotencyKey, recordEntry, recordTransfer, updateEntry } from './entries.js'
import { createAccount, createProject, upsertBudget } from './entities.js'
import { isNoneToken, resolveAccount, resolveCategory, resolveMember, resolveProject } from './resolve.js'

/** 写失败时给模型的统一错误文本（对应原生 `persistenceFailure()`）。 */
export const PERSISTENCE_FAILURE = 'The ledger change was NOT saved — the database is read-only or the write failed. '
  + 'No success should be assumed. Ask the user to retry after the ledger becomes writable.'

export const actionFail = (text) => ({ ok: false, text })
export const actionDone = (text, extra) => ({ ok: true, text, ...(extra ?? {}) })

const fail = actionFail
const done = actionDone

// MARK: - 参数归一

const ACTION_SYNONYMS = {
  edit: 'update', change: 'update', modify: 'update', set: 'update',
  remove: 'delete', del: 'delete', cancel: 'delete', trash: 'delete',
  create: 'add', record: 'add', new: 'add', log: 'add', insert: 'add',
}

function normalizeRecordAction(raw, args) {
  const text = String(raw ?? '').trim().toLowerCase()
  const mapped = ACTION_SYNONYMS[text] ?? text
  if (['add', 'update', 'delete'].includes(mapped)) return mapped
  // 乱填或缺失：有 transaction_id 且无 amount → update，否则 add。**绝不臆测 delete**。
  if (args.transaction_id && (args.amount === undefined || args.amount === null)) return 'update'
  return 'add'
}

const TYPE_SYNONYMS = {
  in: 'income', earn: 'income', salary: 'income', receive: 'income', revenue: 'income', 收入: 'income',
  move: 'transfer', xfer: 'transfer', 转账: 'transfer',
  out: 'expense', spend: 'expense', 支出: 'expense',
}

function normalizeType(raw) {
  const text = String(raw ?? '').trim().toLowerCase()
  if (['expense', 'income', 'transfer'].includes(text)) return text
  return TYPE_SYNONYMS[text] ?? 'expense'
}

/** 日期：`YYYY-MM-DD` 或「昨天 / 3天前 / yesterday」等自然语言；默认今天。 */
export function parseFlexibleDate(raw, now = Date.now()) {
  const text = String(raw ?? '').trim().toLowerCase()
  if (text.length === 0) return dayStart(now)
  const iso = parseISODay(text)
  if (iso !== null) return iso
  if (['today', '今天', '今日'].includes(text)) return dayStart(now)
  if (['yesterday', '昨天', '昨日'].includes(text)) return dayStart(now) - DAY_MS
  if (['tomorrow', '明天'].includes(text)) return dayStart(now) + DAY_MS
  const zh = /^(\d+)\s*天前$/.exec(text)
  if (zh) return dayStart(now) - Number(zh[1]) * DAY_MS
  const en = /^(\d+)\s*days?\s*ago$/.exec(text)
  if (en) return dayStart(now) - Number(en[1]) * DAY_MS
  return dayStart(now)
}

/** 解析失败/歧义时**回一份候选清单**让模型自愈重试，而不是硬报错。 */
export function actionCandidatesText(label, candidates) {
  if (!candidates || candidates.length === 0) return `No ${label} matched. Ask the user which one to use.`
  return `Ambiguous ${label}. Candidates: ${candidates.join(' | ')}. Ask the user which one, then retry.`
}

const candidatesText = actionCandidatesText

function windowFor(args, now) {
  if (args.date_from || args.date_to) {
    return {
      from: args.date_from ? parseISODay(args.date_from) : null,
      to: args.date_to ? parseISODay(args.date_to) : null,
    }
  }
  return periodRange(args.period ?? 'this_month', now)
}

function describeTransaction(store, txn) {
  const account = store.account(txn.accountID)
  const sign = txn.kind === KIND.income ? '+' : (txn.kind === KIND.expense ? '-' : '')
  const parts = [
    isoDay(txn.occurredOn),
    `${sign}${money(txn.amountMinor, txn.currency)}`,
    txn.merchant ?? '',
    txn.categoryID ? store.categoryPath(txn.categoryID) : '',
    account ? account.name : '',
    txn.note ?? '',
  ].filter((piece) => String(piece).length > 0)
  return `${parts.join(' · ')} [id: ${txn.id}]`
}

// MARK: - ① ledger_record

export async function actionRecord(store, args, locale) {
  const action = normalizeRecordAction(args.action, args)

  if (action === 'delete') {
    if (!args.transaction_id) return fail('delete needs transaction_id.')
    const result = await deleteEntry(store, String(args.transaction_id))
    if (!result.ok) return fail(result.reason === 'notFound' ? 'No entry with that id.' : PERSISTENCE_FAILURE)
    return done(`Deleted entry [id: ${args.transaction_id}].`, { id: args.transaction_id, deleted: true })
  }

  if (action === 'update') {
    if (!args.transaction_id) return fail('update needs transaction_id.')
    const current = store.transaction(String(args.transaction_id))
    if (!current) return fail('No entry with that id.')
    const patch = {}
    if (args.amount !== undefined && args.amount !== null) patch.amountMinor = majorNumberToMinor(args.amount)
    if (args.note !== undefined) patch.note = String(args.note)
    if (args.merchant !== undefined) patch.merchant = String(args.merchant)
    if (args.tags !== undefined) patch.tags = args.tags
    if (args.reimbursable !== undefined) patch.reimbursable = !!args.reimbursable
    if (args.date !== undefined) patch.occurredOn = parseFlexibleDate(args.date)
    if (args.refund_of !== undefined) patch.refundOfID = isNoneToken(args.refund_of) ? null : String(args.refund_of)
    if (args.category) {
      const kind = current.kind === KIND.income ? 'income' : 'expense'
      const resolved = resolveCategory(store, args.category, kind)
      if (!resolved.found) return fail(candidatesText('category', resolved.candidates))
      patch.categoryID = resolved.value.id
    }
    if (args.account) {
      const resolved = resolveAccount(store, args.account, args.currency)
      if (!resolved.found) return fail(candidatesText('account', resolved.candidates))
      patch.accountID = resolved.value.id
    }
    if (args.project !== undefined) {
      if (isNoneToken(args.project)) patch.projectID = null
      else {
        const resolved = resolveProject(store, args.project)
        if (!resolved.found) return fail(candidatesText('project', resolved.candidates))
        patch.projectID = resolved.value.id
      }
    }
    const result = await updateEntry(store, current.id, patch)
    if (!result.ok) {
      if (result.reason === 'rateNeeded') return fail(`No exchange rate configured for ${result.currency}. Set it first with ledger_currency.`)
      return fail(PERSISTENCE_FAILURE)
    }
    return done(`Updated. ${describeTransaction(store, result.transaction)}`, { id: result.transaction.id })
  }

  // add
  const requestID = args.request_id ? String(args.request_id) : null
  if (requestID) {
    const existing = findByIdempotencyKey(store, requestID)
    if (existing) return done(`Already recorded (idempotent retry). ${describeTransaction(store, existing)}`, { id: existing.id, duplicate: true })
  }
  const amount = Number(args.amount)
  if (!Number.isFinite(amount) || amount <= 0) return fail('add needs a positive amount.')
  const amountMinor = majorNumberToMinor(amount)
  const type = normalizeType(args.type)
  const occurredOn = parseFlexibleDate(args.date)

  if (type === 'transfer') {
    const from = resolveAccount(store, args.account ?? '', args.currency)
    const to = resolveAccount(store, args.to_account ?? '')
    if (!from.found) return fail(candidatesText('source account', from.candidates))
    if (!to.found) return fail(candidatesText('destination account', to.candidates))
    if (!store.hasUsableRate(from.value.currency) || !store.hasUsableRate(to.value.currency)) {
      return fail('Set exchange rates for both currencies before transferring. Nothing was written.')
    }
    const result = await recordTransfer(store, {
      fromAccountID: from.value.id,
      toAccountID: to.value.id,
      amountMinor,
      toAmountMinor: args.to_amount !== undefined && args.to_amount !== null ? majorNumberToMinor(args.to_amount) : null,
      occurredOn,
      note: args.note ? String(args.note) : '',
      merchant: args.merchant ? String(args.merchant) : null,
      tags: args.tags,
      source: 'ai',
      idempotencyKey: requestID,
      batchID: args.batch_id ? String(args.batch_id) : null,
    })
    if (!result.ok) return fail(result.reason === 'persistence' ? PERSISTENCE_FAILURE : `Transfer failed: ${result.reason}.`)
    return done(`Transferred ${money(amountMinor, from.value.currency)} ${from.value.name} → ${to.value.name}. [id: ${result.transaction.id}]`,
      { id: result.transaction.id, peerID: result.peer.id })
  }

  const kind = type === 'income' ? KIND.income : KIND.expense
  let accountID = null
  if (args.account) {
    const resolved = resolveAccount(store, args.account, args.currency)
    if (!resolved.found) return fail(candidatesText('account', resolved.candidates))
    accountID = resolved.value.id
  } else if (args.currency) {
    // 给了币种但没点名账户 → 路由到同币种账户；没有就自动建一个现金账户。
    const code = normalizeCurrencyCode(args.currency)
    if (!store.hasUsableRate(code)) {
      return fail(`Currency ${code} has no configured exchange rate, so the entry was NOT recorded. Add it with ledger_currency first.`)
    }
    const same = store.activeAccounts().filter((row) => row.currency === code)
    if (same.length > 0) accountID = same[0].id
    else {
      const created = await createAccount(store, { name: `Cash (${code})`, kind: 'cash', currency: code })
      if (!created.ok) return fail(PERSISTENCE_FAILURE)
      accountID = created.account.id
    }
  }

  let categoryID = null
  if (args.category) {
    const resolved = resolveCategory(store, args.category, kind === KIND.income ? 'income' : 'expense')
    if (!resolved.found) return fail(candidatesText('category', resolved.candidates))
    categoryID = resolved.value.id
  }

  // **AI 记账缺省不归任何项目**（哪怕存在当前激活项目）——只有 UI 手动记账才默认归入当前项目。
  let projectID = null
  if (args.project && !isNoneToken(args.project)) {
    const resolved = resolveProject(store, args.project)
    if (resolved.found) projectID = resolved.value.id
    else {
      const created = await createProject(store, { name: String(args.project) })
      if (!created.ok) return fail(PERSISTENCE_FAILURE)
      projectID = created.project.id
    }
  }

  let payerMemberID = null
  let split = null
  if (projectID && args.payer) {
    const resolved = resolveMember(store, projectID, args.payer)
    if (resolved.found) payerMemberID = resolved.value.id
  }
  if (projectID && args.split_mode) {
    const members = store.projectMembers(projectID)
    const names = Array.isArray(args.split_with) && args.split_with.length > 0 ? args.split_with : members.map((row) => row.name)
    const ids = []
    for (const name of names) {
      const resolved = resolveMember(store, projectID, name)
      if (resolved.found) ids.push(resolved.value.id)
    }
    if (ids.length > 0) {
      // 付款人排到首位 → 零头落在付款人身上。
      const ordered = payerMemberID ? [payerMemberID, ...ids.filter((id) => id !== payerMemberID)] : ids
      const values = Array.isArray(args.split_values) ? args.split_values : []
      split = {
        mode: String(args.split_mode),
        shares: ordered.map((id) => {
          const position = ids.indexOf(id)
          return { memberID: id, value: Number(values[position] ?? 0) }
        }),
      }
    }
  }

  const result = await recordEntry(store, {
    kind,
    amountMinor,
    accountID,
    categoryID,
    projectID,
    payerMemberID,
    split,
    occurredOn,
    merchant: args.merchant ? String(args.merchant) : null,
    note: args.note ? String(args.note) : '',
    tags: args.tags,
    reimbursable: !!args.reimbursable,
    refundOfID: args.refund_of && !isNoneToken(args.refund_of) ? String(args.refund_of) : null,
    source: 'ai',
    idempotencyKey: requestID,
    batchID: args.batch_id ? String(args.batch_id) : null,
    sourceFingerprint: args.source_fingerprint ? String(args.source_fingerprint) : null,
  })
  if (!result.ok) {
    if (result.reason === 'rateNeeded') return fail(`No exchange rate configured for ${result.currency}. Nothing was written.`)
    if (result.reason === 'noAccount') return fail('There is no account to record into. Create one with ledger_account first.')
    return fail(PERSISTENCE_FAILURE)
  }
  const account = store.account(result.transaction.accountID)
  return done(
    `Recorded ${type} ${money(amountMinor, result.transaction.currency)} on ${isoDay(occurredOn)}`
    + `${categoryID ? ` · ${store.categoryPath(categoryID)}` : ''}${account ? ` · ${account.name}` : ''} `
    + `[id: ${result.transaction.id}]`,
    { id: result.transaction.id, amountMinor, currency: result.transaction.currency },
  )
}

// MARK: - ② ledger_query

export async function actionQuery(store, args, locale) {
  const now = Date.now()
  const range = windowFor(args, now)
  const filter = { dateFrom: range.from, dateTo: range.to }
  if (args.type) {
    const type = normalizeType(args.type)
    filter.kinds = type === 'transfer' ? [KIND.transferOut, KIND.transferIn]
      : type === 'income' ? [KIND.income] : [KIND.expense]
  }
  if (args.category) {
    const resolved = resolveCategory(store, args.category, args.type === 'income' ? 'income' : 'expense')
    if (!resolved.found) return fail(candidatesText('category', resolved.candidates))
    filter.categoryID = resolved.value.id
  }
  if (args.account) {
    const resolved = resolveAccount(store, args.account)
    if (!resolved.found) return fail(candidatesText('account', resolved.candidates))
    filter.accountID = resolved.value.id
  }
  if (args.project) {
    const resolved = resolveProject(store, args.project)
    if (!resolved.found) return fail(candidatesText('project', resolved.candidates))
    filter.projectID = resolved.value.id
  }
  if (args.tag) filter.tag = args.tag
  if (args.keyword) filter.keyword = args.keyword
  if (args.reimbursable !== undefined) filter.reimbursable = !!args.reimbursable
  if (args.min_amount !== undefined && args.min_amount !== null) filter.minAmountMinor = majorNumberToMinor(args.min_amount)
  if (args.max_amount !== undefined && args.max_amount !== null) filter.maxAmountMinor = majorNumberToMinor(args.max_amount)

  const limit = Math.min(100, Math.max(1, Number(args.limit) || 20))
  const rows = filterTransactions(store, filter)
  if (rows.length === 0) return done('No matching ledger entries.', { count: 0, entries: [] })
  const shown = rows.slice(0, limit)
  const expenseTotal = rows
    .filter((txn) => txn.kind === KIND.expense)
    .reduce((total, txn) => total + store.reportingBaseMinor(txn), 0)
  const lines = shown.map((txn) => describeTransaction(store, txn))
  return done(
    `${rows.length} matching entries (showing ${shown.length}). Expense total ${money(expenseTotal, store.baseCode)} `
    + `(in base currency ${store.baseCode}).\n${lines.join('\n')}`,
    {
      count: rows.length,
      totalExpenseMinor: expenseTotal,
      baseCurrency: store.baseCode,
      entries: shown.map((txn) => ({
        id: txn.id, kind: txn.kind, amountMinor: txn.amountMinor, currency: txn.currency,
        date: isoDay(txn.occurredOn), merchant: txn.merchant, note: txn.note,
        category: txn.categoryID ? store.categoryPath(txn.categoryID) : null,
      })),
    },
  )
}

// MARK: - ③ ledger_stats

const DIMENSION_MAP = {
  by_category: 'byCategory', by_subcategory: 'bySubcategory', by_day: 'byDay',
  by_month: 'byMonth', by_account: 'byAccount', by_tag: 'byTag', by_project: 'byProject',
}

export async function actionStats(store, args, locale, labels) {
  const now = Date.now()
  const range = windowFor(args, now)
  const dimension = DIMENSION_MAP[String(args.dimension ?? 'by_category')] ?? 'byCategory'
  const metric = ['expense', 'income', 'net'].includes(args.metric) ? args.metric : 'expense'
  const filter = { dateFrom: range.from, dateTo: range.to }
  if (args.project) {
    const resolved = resolveProject(store, args.project)
    if (!resolved.found) return fail(candidatesText('project', resolved.candidates))
    filter.projectID = resolved.value.id
  }
  const rows = filterTransactions(store, filter)
  const list = buckets(store, rows, dimension, metric, locale, labels)
  const total = list.reduce((sum, bucket) => sum + bucket.amountMinor, 0)

  let previousTotal = null
  if (args.compare_previous && range.from !== null && range.to !== null) {
    const span = range.to - range.from
    const previous = filterTransactions(store, {
      ...filter, dateFrom: range.from - span - DAY_MS, dateTo: range.from - DAY_MS,
    })
    previousTotal = buckets(store, previous, dimension, metric, locale, labels)
      .reduce((sum, bucket) => sum + bucket.amountMinor, 0)
  }

  const isTime = dimension === 'byDay' || dimension === 'byMonth'
  const capped = isTime ? list : list.slice(0, Math.min(50, Math.max(1, Number(args.top_n) || 50)))
  const head = capped.slice(0, 15)
    .map((bucket) => `${bucket.label}: ${money(bucket.amountMinor, store.baseCode)} (${bucket.count})`)
  return done(
    `${metric} by ${args.dimension ?? 'by_category'} — total ${money(total, store.baseCode)} `
    + `(base currency ${store.baseCode}, historical posting rates)`
    + `${previousTotal !== null ? `; previous window ${money(previousTotal, store.baseCode)}` : ''}\n${head.join('\n')}`,
    { totalMinor: total, previousTotalMinor: previousTotal, baseCurrency: store.baseCode, buckets: capped },
  )
}

// MARK: - ⑤ ledger_budget

export function parseMonthKey(raw, now = Date.now()) {
  const text = String(raw ?? '').trim()
  if (text.length === 0) return monthKeyOf(now)
  const match = /^(\d{4})[-/]?(\d{2})$/.exec(text)
  if (!match) return monthKeyOf(now)
  return Number(match[1]) * 100 + Number(match[2])
}

export async function actionBudget(store, args, locale) {
  const monthKey = parseMonthKey(args.month)
  const action = String(args.action ?? 'status').toLowerCase()

  if (action === 'set') {
    let categoryID = null
    if (args.category) {
      const resolved = resolveCategory(store, args.category, 'expense')
      if (!resolved.found) return fail(candidatesText('category', resolved.candidates))
      categoryID = store.rootCategoryID(resolved.value.id)
    }
    const limitMinor = majorNumberToMinor(args.limit ?? 0)
    const result = await upsertBudget(store, monthKey, categoryID, limitMinor, args.carryover)
    if (!result.ok) return fail(PERSISTENCE_FAILURE)
    if (result.removed) return done(`Removed the budget for ${monthTitle(monthKey, locale)}${categoryID ? '' : ' (overall total)'}.`)
    return done(`Budget set: ${money(limitMinor, store.baseCode)} for ${monthTitle(monthKey, locale)}.`)
  }

  const payload = budgetPayload(store, monthKey)
  if (payload.totalLimitMinor === 0 && payload.lines.length === 0) {
    return done(`No budgets set for ${monthTitle(monthKey, locale)}.`, { payload })
  }
  const lines = payload.lines.map((line) => {
    const over = line.spentMinor > line.limitMinor ? ' ⚠ over' : ''
    const carried = line.carriedMinor > 0 ? ` (+${money(line.carriedMinor, store.baseCode)} carried)` : ''
    return `${line.name}: ${money(line.spentMinor, store.baseCode)} / ${money(line.limitMinor, store.baseCode)}${carried}${over}`
  })
  return done(
    `${monthTitle(monthKey, locale)} — limit ${money(payload.totalLimitMinor, store.baseCode)}, `
    + `spent ${money(payload.totalSpentMinor, store.baseCode)}, remaining ${money(payload.remainingMinor, store.baseCode)}, `
    + `${money(payload.dailyRemainingMinor, store.baseCode)}/day over ${payload.daysLeft} day(s) left.`
    + `${lines.length > 0 ? `\n${lines.join('\n')}` : ''}`,
    { payload },
  )
}

// 账户余额、净资产、余额校准（§4.4）。

import { DAY_MS, dayStart } from './dates.js'
import { KIND, newID, signedAmountMinor } from './store.js'

/** 估值型账户（investment）走快照，其余从流水派生。 */
export function derivesBalanceFromFlow(account) {
  return account.kind !== 'investment'
}

/**
 * 单账户余额：
 *   cutoff = dayStart(asOf) + 24h                      // 含当天
 *   投资账户 → cutoff 前最近一条快照，没有则 initialBalanceMinor
 *   其它     → initialBalanceMinor + Σ(未软删、occurredOn < cutoff 的 signedAmountMinor)
 */
export function balanceMinor(store, account, asOf = Date.now()) {
  const cutoff = dayStart(asOf) + DAY_MS
  if (!derivesBalanceFromFlow(account)) {
    const rows = store.snapshots
      .filter((row) => row.accountID === account.id && row.date < cutoff)
      .sort((a, b) => b.date - a.date)
    return rows.length > 0 ? rows[0].balanceMinor : account.initialBalanceMinor
  }
  let total = account.initialBalanceMinor
  for (const txn of store.allTransactions()) {
    if (txn.accountID !== account.id) continue
    if (txn.occurredOn >= cutoff) continue
    total += signedAmountMinor(txn)
  }
  return total
}

/** 整页共用的一份余额快照：`{accountID: minor}`。 */
export function balancesByAccount(store, asOf = Date.now()) {
  const cutoff = dayStart(asOf) + DAY_MS
  const out = {}
  for (const account of store.accounts) {
    out[account.id] = derivesBalanceFromFlow(account) ? account.initialBalanceMinor : null
  }
  for (const txn of store.allTransactions()) {
    if (txn.occurredOn >= cutoff) continue
    if (out[txn.accountID] === undefined || out[txn.accountID] === null) continue
    out[txn.accountID] += signedAmountMinor(txn)
  }
  for (const account of store.accounts) {
    if (out[account.id] !== null) continue
    out[account.id] = balanceMinor(store, account, asOf)
  }
  return out
}

/**
 * 净资产口径：只统计 `includeInNetWorth` 的未归档账户，余额换算基准币后：
 *   净资产 = 全部求和；资产 = 只加正数；负债 = 负数取绝对值求和。
 */
export function netWorth(store, balances) {
  let net = 0
  let assets = 0
  let liabilities = 0
  for (const account of store.accounts) {
    if (account.isArchived || !account.includeInNetWorth) continue
    const base = store.toBaseMinor(balances[account.id] ?? 0, account.currency)
    net += base
    if (base > 0) assets += base
    else liabilities += -base
  }
  return { net, assets, liabilities }
}

/**
 * 余额校准（MOZE 式）：
 *  - 流水账户：落一笔可见、可审计、可撤销的 `.adjustment` 校准流水 + 一条 `calibration` 快照
 *  - 估值账户：只写一条 `manual` 快照，不产生流水
 * 两者都在**同一次 mutate** 里落地。
 */
export async function setBalance(store, account, targetMinor, now = Date.now()) {
  if (!derivesBalanceFromFlow(account)) {
    const snapshot = {
      id: newID(), accountID: account.id, date: dayStart(now),
      balanceMinor: Math.round(targetMinor), source: 'manual',
    }
    const ok = await store.mutate((draft) => { draft.table('snapshots').push(snapshot) })
    return ok ? { ok: true, delta: 0 } : { ok: false, reason: 'persistence' }
  }

  const current = balanceMinor(store, account, now)
  const delta = Math.round(targetMinor) - current
  if (delta === 0) return { ok: true, delta: 0, noop: true }

  const txn = store.makeTransaction({
    kind: KIND.adjustment,
    amountMinor: Math.abs(delta),
    signedAdjustment: delta,
    accountID: account.id,
    currency: account.currency,
    occurredOn: now,
    source: 'manual',
  })
  store.applyPostingSnapshot(txn)
  const snapshot = {
    id: newID(), accountID: account.id, date: dayStart(now),
    balanceMinor: Math.round(targetMinor), source: 'calibration',
  }
  const ok = await store.mutate((draft) => {
    draft.putTx(txn)
    draft.table('snapshots').push(snapshot)
  })
  return ok ? { ok: true, delta } : { ok: false, reason: 'persistence' }
}

// CSV 导入 / 导出（§2.10）。
//
// 导出：全部未软删流水，`allTransactions()` 顺序，CRLF 换行，RFC 4180 转义，22 列固定顺序。
// 导入：**先预览、后确认，绝不「选文件即写库」**；幂等键 `csv:{原 transaction_id}`；
//       引用（转账互指 / 退款关联）靠「原 id → 新对象」映射两遍回填。

import { KIND, newID, normalizeTags } from './store.js'
import { isoDay, isoTimestamp, parseISODay, parseTimestamp } from './dates.js'
import { majorNumberToMinor, plainMajor } from './money.js'
import { createAccount, createCategory, createProject } from './entities.js'

export const CSV_COLUMNS = [
  'transaction_id', 'kind', 'amount_minor', 'currency', 'base_amount_minor_at_posting',
  'base_currency_at_posting', 'fx_rate_to_base_at_posting', 'occurred_on', 'created_at',
  'account_name', 'account_kind', 'category_path', 'project_name', 'merchant', 'note', 'tags',
  'reimbursable', 'refund_of_id', 'source', 'transfer_peer_id', 'calculation_expression',
  'source_fingerprint',
]

// 旧版 20 列（无 merchant、无 refund_of_id）仍接受导入，保证旧备份可恢复。
export const CSV_COLUMNS_V1 = CSV_COLUMNS.filter((name) => name !== 'merchant' && name !== 'refund_of_id')

// 解析失败文案：与原生一致，**纯英文硬编码、有意不本地化**。
export const CSV_ERRORS = {
  notUTF8: 'The file is not valid UTF-8 CSV.',
  empty: 'The CSV file is empty.',
  columns: (found) => `The CSV columns do not match the AiBox Ledger export format (found ${found} columns).`,
  rowColumns: (expected, found) => `Expected ${expected} columns but found ${found}.`,
  required: 'Required transaction fields are missing or invalid.',
}

// MARK: - 导出

function escapeField(value) {
  const text = String(value ?? '')
  if (/[",\n\r]/.test(text)) return `"${text.replace(/"/g, '""')}"`
  return text
}

/** `%.12g` 的等价：12 位有效数字，去掉多余零。 */
function formatRate(value) {
  if (value === null || value === undefined) return ''
  const number = Number(value)
  if (!Number.isFinite(number)) return ''
  return String(Number(number.toPrecision(12)))
}

export function exportCSV(store) {
  const lines = [CSV_COLUMNS.join(',')]
  for (const txn of store.allTransactions()) {
    const account = store.account(txn.accountID)
    const project = txn.projectID ? store.project(txn.projectID) : null
    const row = [
      txn.id,
      txn.kind,
      txn.amountMinor,
      txn.currency,
      txn.baseAmountMinorAtPosting ?? '',
      txn.baseCurrencyAtPosting ?? '',
      formatRate(txn.fxRateToBaseAtPosting),
      isoTimestamp(txn.occurredOn),
      isoTimestamp(txn.createdAt),
      account ? account.name : '',
      account ? account.kind : '',
      txn.categoryID ? store.categoryPath(txn.categoryID) : '',
      project ? project.name : '',
      txn.merchant ?? '',
      txn.note ?? '',
      (txn.tags ?? []).join('|'),
      txn.reimbursable ? 'true' : 'false',
      txn.refundOfID ?? '',
      txn.source ?? '',
      txn.transferPeerID ?? '',
      txn.calculationExpression ?? '',
      txn.sourceFingerprint ?? '',
    ]
    lines.push(row.map(escapeField).join(','))
  }
  return `${lines.join('\r\n')}\r\n`
}

export function exportFilename(now = Date.now()) {
  return `AiBox-Ledger-${isoDay(now)}.csv`
}

// MARK: - 解析

/** RFC 4180 解析成二维数组。 */
export function parseCSV(text) {
  const rows = []
  let row = []
  let field = ''
  let quoted = false
  let i = 0
  const source = String(text ?? '').replace(/^﻿/, '')
  while (i < source.length) {
    const ch = source[i]
    if (quoted) {
      if (ch === '"') {
        if (source[i + 1] === '"') { field += '"'; i += 2; continue }
        quoted = false; i += 1; continue
      }
      field += ch; i += 1; continue
    }
    if (ch === '"') { quoted = true; i += 1; continue }
    if (ch === ',') { row.push(field); field = ''; i += 1; continue }
    if (ch === '\r') { i += 1; continue }
    if (ch === '\n') { row.push(field); rows.push(row); row = []; field = ''; i += 1; continue }
    field += ch; i += 1
  }
  if (field.length > 0 || row.length > 0) { row.push(field); rows.push(row) }
  return rows.filter((line) => line.length > 1 || (line[0] ?? '').trim().length > 0)
}

const KIND_VALUES = new Set(Object.values(KIND))

/**
 * 解析成 draft（有效行 + 问题列表），**不写任何数据**。
 * 返回 `{ rows, problems, columns }`；`rows` 是待落库的中间结构。
 */
export function parseImport(text, store) {
  const problems = []
  const table = parseCSV(text)
  if (table.length === 0) return { rows: [], problems: [{ row: 0, message: CSV_ERRORS.empty }] }

  const header = table[0].map((name) => String(name ?? '').trim())
  let columns = null
  if (header.length === CSV_COLUMNS.length) columns = CSV_COLUMNS
  else if (header.length === CSV_COLUMNS_V1.length) columns = CSV_COLUMNS_V1
  if (!columns) return { rows: [], problems: [{ row: 1, message: CSV_ERRORS.columns(header.length) }] }

  const index = Object.fromEntries(columns.map((name, position) => [name, position]))
  const rows = []
  for (let line = 1; line < table.length; line += 1) {
    const cells = table[line]
    if (cells.length !== columns.length) {
      problems.push({ row: line + 1, message: CSV_ERRORS.rowColumns(columns.length, cells.length) })
      continue
    }
    const get = (name) => (index[name] === undefined ? '' : String(cells[index[name]] ?? '').trim())
    const amountMinor = Number.parseInt(get('amount_minor'), 10)
    const kind = get('kind')
    const occurredOn = parseTimestamp(get('occurred_on'), null)
    if (!Number.isFinite(amountMinor) || !KIND_VALUES.has(kind) || occurredOn === null) {
      problems.push({ row: line + 1, message: CSV_ERRORS.required })
      continue
    }
    rows.push({
      line: line + 1,
      originalID: get('transaction_id'),
      kind,
      amountMinor: Math.abs(amountMinor),
      currency: (get('currency') || store.baseCode).toUpperCase(),
      baseAmountMinorAtPosting: get('base_amount_minor_at_posting') === '' ? null : Number.parseInt(get('base_amount_minor_at_posting'), 10),
      baseCurrencyAtPosting: get('base_currency_at_posting') || null,
      fxRateToBaseAtPosting: get('fx_rate_to_base_at_posting') === '' ? null : Number(get('fx_rate_to_base_at_posting')),
      occurredOn,
      createdAt: parseTimestamp(get('created_at'), occurredOn),
      accountName: get('account_name'),
      accountKind: get('account_kind') || 'cash',
      categoryPath: get('category_path'),
      projectName: get('project_name'),
      merchant: get('merchant') || null,
      note: get('note'),
      tags: get('tags').length > 0 ? get('tags').split('|') : [],
      reimbursable: get('reimbursable').toLowerCase() === 'true',
      refundOfID: get('refund_of_id') || null,
      transferPeerID: get('transfer_peer_id') || null,
      calculationExpression: get('calculation_expression') || null,
      sourceFingerprint: get('source_fingerprint') || get('transaction_id') || null,
    })
  }
  return { rows, problems, columns }
}

// MARK: - 落库

function findCategoryByPath(store, path) {
  const trimmed = String(path ?? '').trim()
  if (trimmed.length === 0) return { ok: true, id: null }
  const parts = trimmed.split('/').map((piece) => piece.trim()).filter((piece) => piece.length > 0)
  const rootName = parts[0]
  const childName = parts.length > 1 ? parts[1] : null
  const roots = store.categories.filter((row) => !row.parentID && row.name === rootName)
  if (roots.length > 1) return { ok: false }
  const root = roots[0] ?? null
  if (!childName) return { ok: true, id: root ? root.id : null, missingRoot: root ? null : rootName }
  if (!root) return { ok: true, id: null, missingRoot: rootName, missingChild: childName }
  const children = store.childCategories(root.id).filter((row) => row.name === childName)
  if (children.length > 1) return { ok: false }
  if (children.length === 1) return { ok: true, id: children[0].id }
  return { ok: true, id: null, parentID: root.id, missingChild: childName }
}

/**
 * 确认后写库。**整批共享一个 batchID**；`source` 一律改写成 `"import"`；
 * 落盘失败 → 整批算失败（imported 归 0，全部计入 failed）。
 */
export async function performImport(store, rows) {
  const batchID = newID()
  const existingKeys = new Set(store.allTransactions().map((row) => row.idempotencyKey).filter(Boolean))
  let skipped = 0
  let failed = 0
  const staged = []
  const idMap = new Map()

  // ① 先把缺的账户/分类/项目补齐（各自一次 mutate，失败即整批失败）。
  for (const row of rows) {
    const key = `csv:${row.originalID}`
    if (row.originalID && existingKeys.has(key)) { skipped += 1; continue }

    let account = store.accounts.find((entry) => entry.name === row.accountName
      && entry.currency === row.currency) ?? null
    if (!account) account = store.accounts.find((entry) => entry.name === row.accountName) ?? null
    if (!account && row.accountName) {
      const created = await createAccount(store, {
        name: row.accountName, kind: row.accountKind, currency: row.currency,
      })
      if (!created.ok) { failed += 1; continue }
      account = created.account
    }
    if (!account) account = store.defaultAccount()
    if (!account) { failed += 1; continue }

    const resolved = findCategoryByPath(store, row.categoryPath)
    if (!resolved.ok) { failed += 1; continue }
    let categoryID = resolved.id
    if (categoryID === null && (resolved.missingRoot || resolved.missingChild)) {
      const built = await ensureCategoryPath(store, row.categoryPath, row.kind === KIND.income ? 'income' : 'expense')
      if (!built.ok) { failed += 1; continue }
      categoryID = built.id
    }

    let projectID = null
    if (row.projectName) {
      const project = store.projects.find((entry) => entry.name === row.projectName)
      if (project) projectID = project.id
      else {
        const created = await createProject(store, { name: row.projectName })
        if (!created.ok) { failed += 1; continue }
        projectID = created.project.id
      }
    }

    const txn = store.makeTransaction({
      kind: row.kind,
      amountMinor: row.amountMinor,
      currency: account.currency,
      accountID: account.id,
      categoryID,
      projectID,
      merchant: row.merchant,
      note: row.note,
      tags: normalizeTags(row.tags),
      reimbursable: row.reimbursable,
      occurredOn: row.occurredOn,
      createdAt: row.createdAt,
      calculationExpression: row.calculationExpression,
      idempotencyKey: row.originalID ? `csv:${row.originalID}` : null,
      batchID,
      sourceFingerprint: row.sourceFingerprint,
      source: 'import',
    })
    txn.baseAmountMinorAtPosting = Number.isFinite(row.baseAmountMinorAtPosting) ? row.baseAmountMinorAtPosting : null
    txn.baseCurrencyAtPosting = row.baseCurrencyAtPosting
    txn.fxRateToBaseAtPosting = Number.isFinite(row.fxRateToBaseAtPosting) ? row.fxRateToBaseAtPosting : null
    if (txn.baseAmountMinorAtPosting === null) store.applyPostingSnapshot(txn)
    staged.push({ txn, row })
    if (row.originalID) idMap.set(row.originalID, txn.id)
  }

  if (staged.length === 0) return { imported: 0, skipped, failed }

  // ② 用「原 id → 新 id」映射回填 transferPeerID / refundOfID，再一次性落库。
  for (const { txn, row } of staged) {
    if (row.transferPeerID) txn.transferPeerID = idMap.get(row.transferPeerID) ?? null
    if (row.refundOfID) {
      txn.refundOfID = idMap.get(row.refundOfID)
        ?? (store.allTransactions().find((entry) => entry.idempotencyKey === `csv:${row.refundOfID}`)?.id ?? null)
    }
  }
  const ok = await store.mutate((draft) => { for (const { txn } of staged) draft.putTx(txn) })
  if (!ok) return { imported: 0, skipped, failed: failed + staged.length }
  return { imported: staged.length, skipped, failed }
}

async function ensureCategoryPath(store, path, kind) {
  const parts = String(path ?? '').split('/').map((piece) => piece.trim()).filter((piece) => piece.length > 0)
  if (parts.length === 0) return { ok: true, id: null }
  let root = store.categories.find((row) => !row.parentID && row.name === parts[0] && row.kind === kind) ?? null
  if (!root) {
    const created = await createCategory(store, { name: parts[0], kind })
    if (!created.ok) return { ok: false }
    root = created.category
  }
  if (parts.length === 1) return { ok: true, id: root.id }
  let child = store.categories.find((row) => row.parentID === root.id && row.name === parts[1]) ?? null
  if (!child) {
    const created = await createCategory(store, { name: parts[1], kind, parentID: root.id })
    if (!created.ok) return { ok: false }
    child = created.category
  }
  return { ok: true, id: child.id }
}

export { parseISODay, majorNumberToMinor, plainMajor }

// 币种目录（§4.8「币种目录（20 种）」的完整清单，「添加币种」选择器的来源）。
//
// 纪律：**存储恒 ×100**，与币种小数位无关；`decimals` 只影响显示截位
// （JPY / KRW / VND 是 0 位币，不显示小数部分）。

/** 20 个内置币种：code / 符号 / 小数位。名称走 i18n（键 `cur.<CODE>`）。 */
export const CURRENCY_CATALOG = [
  { code: 'CNY', symbol: '¥', decimals: 2 },
  { code: 'MYR', symbol: 'RM', decimals: 2 },
  { code: 'USD', symbol: '$', decimals: 2 },
  { code: 'EUR', symbol: '€', decimals: 2 },
  { code: 'GBP', symbol: '£', decimals: 2 },
  { code: 'HKD', symbol: 'HK$', decimals: 2 },
  { code: 'SGD', symbol: 'S$', decimals: 2 },
  { code: 'TWD', symbol: 'NT$', decimals: 2 },
  { code: 'THB', symbol: '฿', decimals: 2 },
  { code: 'JPY', symbol: '¥', decimals: 0 },
  { code: 'KRW', symbol: '₩', decimals: 0 },
  { code: 'AUD', symbol: 'A$', decimals: 2 },
  { code: 'CAD', symbol: 'C$', decimals: 2 },
  { code: 'IDR', symbol: 'Rp', decimals: 2 },
  { code: 'VND', symbol: '₫', decimals: 0 },
  { code: 'INR', symbol: '₹', decimals: 2 },
  { code: 'PHP', symbol: '₱', decimals: 2 },
  { code: 'MOP', symbol: 'MOP$', decimals: 2 },
  { code: 'CHF', symbol: 'CHF', decimals: 2 },
  { code: 'NZD', symbol: 'NZ$', decimals: 2 },
]

const BY_CODE = new Map(CURRENCY_CATALOG.map((row) => [row.code, row]))

/** 目录条目；未知币种返回 null。 */
export function catalogEntry(code) {
  return BY_CODE.get(String(code ?? '').toUpperCase()) ?? null
}

/** 符号。未知币种回退 `"{CODE} "`（大写码 + 一个空格）；`RMB` 特判成 `¥`。 */
export function currencySymbol(code) {
  const upper = String(code ?? '').toUpperCase()
  if (upper === 'RMB') return '¥'
  const entry = BY_CODE.get(upper)
  if (entry) return entry.symbol
  return `${upper} `
}

/** 显示小数位。未知币种默认 2。 */
export function currencyDecimals(code) {
  const entry = BY_CODE.get(String(code ?? '').toUpperCase())
  return entry ? entry.decimals : 2
}

// 俗名 / 母语名 → ISO 码（AI 与导入的宽松解析用）。
const ALIASES = {
  rmb: 'CNY', 人民币: 'CNY', 元: 'CNY', 块: 'CNY', yuan: 'CNY', 'chinese yuan': 'CNY',
  ringgit: 'MYR', 马币: 'MYR', 林吉特: 'MYR',
  dollar: 'USD', 美元: 'USD', 美金: 'USD', usdollar: 'USD',
  euro: 'EUR', 欧元: 'EUR',
  pound: 'GBP', 英镑: 'GBP', sterling: 'GBP',
  港币: 'HKD', 港元: 'HKD',
  新币: 'SGD', 新加坡元: 'SGD',
  台币: 'TWD', 新台币: 'TWD',
  泰铢: 'THB', baht: 'THB',
  日元: 'JPY', 日圆: 'JPY', yen: 'JPY',
  韩元: 'KRW', won: 'KRW',
  澳元: 'AUD', 澳币: 'AUD',
  加元: 'CAD', 加币: 'CAD',
  印尼盾: 'IDR', rupiah: 'IDR',
  越南盾: 'VND', dong: 'VND',
  卢比: 'INR', rupee: 'INR',
  比索: 'PHP', peso: 'PHP',
  澳门元: 'MOP', 葡币: 'MOP',
  法郎: 'CHF', franc: 'CHF',
  新西兰元: 'NZD',
}

/** 归一成 ISO 码；无法归一时返回大写原串。 */
export function normalizeCurrencyCode(raw) {
  const text = String(raw ?? '').trim()
  if (text.length === 0) return ''
  const upper = text.toUpperCase()
  if (BY_CODE.has(upper)) return upper
  const alias = ALIASES[text.toLowerCase()] ?? ALIASES[text]
  return alias ?? upper
}

// 日期口径（§6.4）。全部走本地时区；记账日恒归一到当天 00:00。

/** 本地时区当天 00:00 的时间戳（ms）。 */
export function dayStart(value) {
  const date = new Date(value)
  date.setHours(0, 0, 0, 0)
  return date.getTime()
}

export const DAY_MS = 24 * 60 * 60 * 1000

/** 月键 `YYYYMM` 整数。 */
export function monthKeyOf(value) {
  const date = new Date(value)
  return date.getFullYear() * 100 + (date.getMonth() + 1)
}

export function monthKeyNow() {
  return monthKeyOf(Date.now())
}

/** 月键 → 该月 1 号 00:00 的时间戳。 */
export function monthStart(monthKey) {
  const year = Math.trunc(monthKey / 100)
  const month = monthKey % 100
  return new Date(year, month - 1, 1, 0, 0, 0, 0).getTime()
}

/** 月键 → 次月 1 号 00:00（开区间上界）。 */
export function monthEnd(monthKey) {
  const year = Math.trunc(monthKey / 100)
  const month = monthKey % 100
  return new Date(month === 12 ? year + 1 : year, month === 12 ? 0 : month, 1, 0, 0, 0, 0).getTime()
}

export function addMonths(monthKey, delta) {
  const year = Math.trunc(monthKey / 100)
  const month = monthKey % 100 - 1 + delta
  const nextYear = year + Math.floor(month / 12)
  const nextMonth = ((month % 12) + 12) % 12
  return nextYear * 100 + nextMonth + 1
}

export function daysInMonth(monthKey) {
  return Math.round((monthEnd(monthKey) - monthStart(monthKey)) / DAY_MS)
}

/**
 * 本月剩余天数（含今天）：
 *  - 今天早于该月起始（查未来月）→ 整月天数
 *  - 今天 ≥ 该月结束（查过去月）→ 0
 */
export function daysRemainingInMonth(monthKey, now = Date.now()) {
  const today = dayStart(now)
  const start = monthStart(monthKey)
  const end = monthEnd(monthKey)
  if (today < start) return daysInMonth(monthKey)
  if (today >= end) return 0
  return Math.round((end - DAY_MS - today) / DAY_MS) + 1
}

// MARK: - 本地化格式

const BCP47 = { 'zh-Hans': 'zh-CN', en: 'en-US' }

function tag(locale) {
  return BCP47[locale] ?? 'en-US'
}

const cache = new Map()

function formatter(locale, options) {
  const key = `${locale}|${JSON.stringify(options)}`
  let value = cache.get(key)
  if (!value) {
    value = new Intl.DateTimeFormat(tag(locale), options)
    cache.set(key, value)
  }
  return value
}

/** 月标题：zh「2026年7月」/ en「July 2026」。 */
export function monthTitle(monthKey, locale) {
  return formatter(locale, { year: 'numeric', month: 'long' }).format(new Date(monthStart(monthKey)))
}

/** 明细日期表头的 `MMMd EEE`：zh「7月4日周五」/ en「Jul 4, Fri」。 */
export function dayHeaderDate(value, locale) {
  return formatter(locale, { month: 'long', day: 'numeric', weekday: 'short' }).format(new Date(value))
}

/** 短日期 `Md`（账户详情、导入预览、下钻列表）。 */
export function shortDate(value, locale) {
  return formatter(locale, { month: 'numeric', day: 'numeric' }).format(new Date(value))
}

/** 项目日期区间用的 `MMMd`。 */
export function mediumDayDate(value, locale) {
  return formatter(locale, { month: 'short', day: 'numeric' }).format(new Date(value))
}

/** ISO 日 `yyyy-MM-dd`（本地时区，不是 UTC——记账日是本地概念）。 */
export function isoDay(value) {
  const date = new Date(value)
  const month = String(date.getMonth() + 1).padStart(2, '0')
  const day = String(date.getDate()).padStart(2, '0')
  return `${date.getFullYear()}-${month}-${day}`
}

/** ISO 8601 含小数秒（CSV 时间戳）。 */
export function isoTimestamp(value) {
  return new Date(value).toISOString()
}

/** 宽松日期解析：取前 10 字符按 `yyyy-MM-dd`；失败返回 null。 */
export function parseISODay(text) {
  const raw = String(text ?? '').trim().slice(0, 10)
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(raw)
  if (!match) return null
  const date = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]), 0, 0, 0, 0)
  return Number.isNaN(date.getTime()) ? null : date.getTime()
}

/** 宽松时间戳解析（CSV 的 createdAt）。失败回落到 occurredOn。 */
export function parseTimestamp(text, fallback) {
  const value = Date.parse(String(text ?? ''))
  return Number.isNaN(value) ? fallback : value
}

export function isSameDay(a, b) {
  return dayStart(a) === dayStart(b)
}

// 持久层：`aibox.db.*` + 自建写前日志（WAL）。
//
// —— 为什么要自己做 WAL ——
// 实测宿主的 `aibox.db`（`AppletDocumentDatabase.swift`）**没有事务语义**：
// 它是「每个 collection 一个 JSON 文件」，`insert/update/remove` 各自做一次
// 「整表读 → 改 → 原子写文件」。**单次调用是原子的，跨调用不是**。
// 而记账有两处绝不允许写一半（§10）：
//   ① 转账 = 两笔互指的流水；② AA 结算 = 结算记录 + 关联流水。
//
// —— 结构 ——
// collection `tables` ：小表各一个文档 `{_id:'accounts', rows:[…]}`，写一次 = 重写这张小表；
// collection `tx`     ：流水**按月分片** `{_id:'m202608', rows:[…]}`。同月的转账两腿落在同一个
//                       文档里 → 天然一次原子写；跨月/跨表才需要 WAL。分片同时把 CSV 导入
//                       从「每行一次整表重写」压成「每月一次」。
// collection `wal`    ：`{_id:'pending', ops:[…]}`。
//
// —— 协议 ——
// 1. 先把整批变更写进 `wal/pending`（一次原子写）；
// 2. 逐个落地 ops；
// 3. 全部成功后删掉 pending。
// 启动时若发现 pending → **重放**（不是回滚）：每个 op 都是「按 _id 整文档 put / del」，
// 幂等，重放一定收敛到批次完成后的状态。任何一步抛错都向上冒泡 → 上层切只读态。

const TABLES = 'tables'
const TX = 'tx'
const WAL = 'wal'
const PENDING_ID = 'pending'
const PAGE = 500

function api() {
  const root = typeof window !== 'undefined' ? window.aibox : undefined
  return root && root.db && typeof root.db.query === 'function' ? root.db : null
}

export function databaseAvailable() {
  return api() !== null
}

export const txDocID = (monthKey) => `m${monthKey}`

// MARK: - 底层调用（**不吞异常**）

async function queryAll(collection) {
  const db = api()
  if (!db) throw new Error('aibox/db-unavailable')
  const out = []
  for (let offset = 0; ; offset += PAGE) {
    const page = await db.query({ collection, limit: PAGE, offset })
    const rows = Array.isArray(page) ? page : []
    out.push(...rows)
    if (rows.length < PAGE) break
  }
  return out
}

async function put(collection, id, rows) {
  const db = api()
  if (!db) throw new Error('aibox/db-unavailable')
  await db.insert({ collection, document: { _id: id, rows } })
}

async function drop(collection, id) {
  const db = api()
  if (!db) throw new Error('aibox/db-unavailable')
  await db.remove({ collection, id })
}

// MARK: - 启动

/** 读回全部数据：`{ tables: {name: rows}, tx: {monthKey: rows} }`。抛错交给上层切降级态。 */
export async function loadAll() {
  await replayPendingWAL()
  const tables = {}
  for (const doc of await queryAll(TABLES)) {
    if (doc && typeof doc._id === 'string') tables[doc._id] = Array.isArray(doc.rows) ? doc.rows : []
  }
  const tx = {}
  for (const doc of await queryAll(TX)) {
    if (doc && typeof doc._id === 'string' && doc._id.startsWith('m')) {
      tx[Number(doc._id.slice(1))] = Array.isArray(doc.rows) ? doc.rows : []
    }
  }
  return { tables, tx }
}

/** 若上次写到一半崩了，把 pending 批次重放完再删。 */
async function replayPendingWAL() {
  const rows = await queryAll(WAL)
  const pending = rows.find((row) => row && row._id === PENDING_ID)
  if (!pending || !Array.isArray(pending.ops) || pending.ops.length === 0) {
    if (pending) await drop(WAL, PENDING_ID)
    return
  }
  await applyOps(pending.ops)
  await drop(WAL, PENDING_ID)
}

async function applyOps(ops) {
  for (const op of ops) {
    if (!op || typeof op.c !== 'string' || typeof op.id !== 'string') continue
    if (op.del) await drop(op.c, op.id)
    else await put(op.c, op.id, Array.isArray(op.rows) ? op.rows : [])
  }
}

// MARK: - 写

/**
 * 原子提交一批变更。`ops` 形如
 *   `{ c: 'tables', id: 'accounts', rows: [...] }`（整表 put）
 *   `{ c: 'tx', id: 'm202608', rows: [...] }`
 *   `{ c: 'tx', id: 'm202607', del: true }`（该月已空）
 *
 * 单条 op 时跳过 WAL（宿主单次写本身就是原子的），省两次桥调用。
 * 任何一步失败都向上抛 —— 调用方必须切只读态并告知用户，**绝不能吞掉后照常刷新 UI**。
 */
export async function commit(ops) {
  const batch = (ops ?? []).filter((op) => op && typeof op.c === 'string' && typeof op.id === 'string')
  if (batch.length === 0) return
  if (batch.length === 1) { await applyOps(batch); return }
  const db = api()
  if (!db) throw new Error('aibox/db-unavailable')
  await db.insert({
    collection: WAL,
    document: { _id: PENDING_ID, ops: batch, at: new Date().toISOString() },
  })
  await applyOps(batch)
  await drop(WAL, PENDING_ID)
}

// 展示口径（§6.2「正负号与颜色」是最容易做错的一节，集中在这里，别在页面里各写一遍）。
//
// | 场景 | 文本 | 颜色 |
// |---|---|---|
// | 明细行 · 收入 | `+¥xx` | incomeColor 绿 |
// | 明细行 · **支出** | `−¥xx` | **ink（正文色），不是红色** |
// | 明细行 · 校准 | 带符号金额 | muted |
// | 明细行 · 转账两腿 | 无符号金额 | muted |
// | 账户余额 | 负数带 `−` | 负数 expenseColor |
// | 净资产 | **恒带符号** | onAccent |
// | AA 成员净额 | `+` 债权 / `−` 债务 | 绿 / 红 / 0 用 muted |

import { KIND, signedAmountMinor } from './store.js'
import { money } from './money.js'
import { dayHeaderDate, dayStart, DAY_MS } from './dates.js'

export const COLOR_TOKEN = { ink: 'ink', muted: 'muted', income: 'income', expense: 'expense' }

/** 明细行右侧金额。返回 `{ text, tone }`，tone 由页面映射到 CSS 变量。 */
export function entryAmount(txn) {
  switch (txn.kind) {
    case KIND.income:
      return { text: money(txn.amountMinor, txn.currency, { signed: true }), tone: COLOR_TOKEN.income }
    case KIND.expense:
      // 明细行的支出金额是 ink 正文色，**不是红色**。
      return { text: money(-txn.amountMinor, txn.currency), tone: COLOR_TOKEN.ink }
    case KIND.adjustment:
      return { text: money(signedAmountMinor(txn), txn.currency, { signed: true }), tone: COLOR_TOKEN.muted }
    default:
      return { text: money(txn.amountMinor, txn.currency), tone: COLOR_TOKEN.muted }
  }
}

/** 行图标：分类图标/色优先，缺省按 kind 兜底。 */
export function entryGlyph(store, txn) {
  const category = txn.categoryID ? store.category(txn.categoryID) : null
  if (category) return { icon: category.systemImage || 'tag', color: category.colorHex || '#68665E' }
  switch (txn.kind) {
    case KIND.transferOut:
    case KIND.transferIn: return { icon: 'arrow.left.arrow.right', color: '#3A83D0' }
    case KIND.adjustment: return { icon: 'equal.circle', color: '#3A83D0' }
    case KIND.income: return { icon: 'arrow.down.left', color: '#2A9D63' }
    default: return { icon: 'arrow.up.right', color: '#D9534F' }
  }
}

/** kind 兜底名（没有商家也没有分类时用）。 */
export function kindFallbackTitle(store, txn, t) {
  switch (txn.kind) {
    case KIND.transferOut:
    case KIND.transferIn: {
      const own = store.account(txn.accountID)
      const peer = txn.transferPeerID ? store.transaction(txn.transferPeerID) : null
      const other = peer ? store.account(peer.accountID) : null
      const a = own ? own.name : '—'
      const b = other ? other.name : '—'
      return txn.kind === KIND.transferOut ? `${a} → ${b}` : `${b} → ${a}`
    }
    case KIND.adjustment: return t('x.balanceAdjustment')
    case KIND.income: return t('x.income')
    default: return t('x.expense')
  }
}

/** 主标题：商家 → 分类名 → kind 兜底。 */
export function entryTitle(store, txn, t) {
  if (txn.merchant && txn.merchant.trim().length > 0) return txn.merchant.trim()
  if (txn.categoryID) {
    const category = store.category(txn.categoryID)
    if (category) return category.name
  }
  return kindFallbackTitle(store, txn, t)
}

/** 副标题：`[有商家时的分类名, 账户名, 非空备注]` 用 ` · ` 拼接。 */
export function entrySubtitle(store, txn) {
  const parts = []
  const hasMerchant = !!(txn.merchant && txn.merchant.trim().length > 0)
  if (hasMerchant && txn.categoryID) {
    const category = store.category(txn.categoryID)
    if (category) parts.push(category.name)
  }
  const account = store.account(txn.accountID)
  if (account) parts.push(account.name)
  if (txn.note && txn.note.trim().length > 0) parts.push(txn.note.trim())
  return parts.join(' · ')
}

/** 分类展示路径，缺省用 kind 兜底名（下钻列表、账户详情、最近删除都用这个）。 */
export function entryPathTitle(store, txn, t) {
  if (txn.categoryID) {
    const path = store.categoryPath(txn.categoryID)
    if (path) return path
  }
  return kindFallbackTitle(store, txn, t)
}

/** 外币行的第二行：有汇率 → `≈ ±{基准币}`；无汇率 → 「缺汇率」。 */
export function entryConversion(store, txn, t) {
  if (txn.currency === store.baseCode) return null
  if (!store.hasUsableRate(txn.currency)) return { text: t('tx.rateNeeded'), tone: COLOR_TOKEN.expense }
  const base = store.reportingBaseMinor(txn)
  const signed = txn.kind === KIND.income ? base : (txn.kind === KIND.expense ? -base : base)
  return { text: `≈ ${money(signed, store.baseCode, { signed: txn.kind === KIND.income })}`, tone: COLOR_TOKEN.muted }
}

/** 日期表头：今天 / 昨天 / 本地化 `MMMd EEE`。 */
export function dayHeaderTitle(day, locale, t, now = Date.now()) {
  const today = dayStart(now)
  if (day === today) return t('tx.today')
  if (day === today - DAY_MS) return t('tx.yesterday')
  return dayHeaderDate(day, locale)
}

/** 当日支出合计（仅 > 0 时显示）：含非基准币支出时前面加 `≈`。 */
export function dayExpenseTotal(store, rows) {
  let total = 0
  let approximate = false
  for (const txn of rows) {
    if (txn.kind !== KIND.expense) continue
    total += store.reportingBaseMinor(txn)
    if (txn.currency !== store.baseCode) approximate = true
  }
  if (total <= 0) return null
  return `${approximate ? '≈ ' : ''}${money(-total, store.baseCode)}`
}

// 账户 / 分类 / 币种 / 预算 / 项目 / 成员的写操作。UI 与 AI action 共用。

import { newID } from './store.js'
import { ACCOUNT_KIND_COLOR, ACCOUNT_KIND_ICON, MEMBER_COLORS } from './seeds.js'
import { currencyDecimals, currencySymbol } from './currencies.js'
import { dayStart } from './dates.js'

const nextOrder = (rows) => rows.reduce((max, row) => Math.max(max, row.sortOrder ?? 0), -1) + 1

// MARK: - 账户

export async function createAccount(store, input) {
  const name = String(input.name ?? '').trim()
  if (name.length === 0) return { ok: false, reason: 'emptyName' }
  const kind = input.kind ?? 'cash'
  const currency = String(input.currency ?? store.baseCode).toUpperCase()
  // 信用账户的「初始余额」是欠款，正数取负（欠款用负余额表达）。
  let opening = Math.round(input.initialBalanceMinor ?? 0)
  if (kind === 'credit' && opening > 0) opening = -opening
  const account = {
    id: newID(),
    name,
    kind,
    currency,
    initialBalanceMinor: opening,
    includeInNetWorth: input.includeInNetWorth !== false,
    creditLimitMinor: Math.max(0, Math.round(input.creditLimitMinor ?? 0)),
    iconName: ACCOUNT_KIND_ICON[kind] ?? 'banknote',
    colorHex: ACCOUNT_KIND_COLOR[kind] ?? '#2A9D63',
    sortOrder: nextOrder(store.accounts),
    isArchived: false,
    createdAt: Date.now(),
  }
  const ok = await store.mutate((draft) => {
    // 选到尚未启用的币种时自动登记（不带汇率 → rateConfigured=false，进不了汇总）。
    ensureCurrency(draft, currency)
    draft.table('accounts').push(account)
  })
  return ok ? { ok: true, account } : { ok: false, reason: 'persistence' }
}

/** 编辑模式只改 名称 / 类型 / 计入净资产 / 信用额度（**币种不可变**）。 */
export async function updateAccount(store, id, patch) {
  const ok = await store.mutate((draft) => {
    const rows = draft.table('accounts')
    const index = rows.findIndex((row) => row.id === id)
    if (index < 0) return false
    const next = { ...rows[index] }
    if (patch.name !== undefined) next.name = String(patch.name).trim()
    if (patch.kind !== undefined) next.kind = patch.kind
    if (patch.includeInNetWorth !== undefined) next.includeInNetWorth = !!patch.includeInNetWorth
    if (patch.creditLimitMinor !== undefined) next.creditLimitMinor = Math.max(0, Math.round(patch.creditLimitMinor))
    if (patch.isArchived !== undefined) next.isArchived = !!patch.isArchived
    rows[index] = next
    return true
  })
  return ok ? { ok: true } : { ok: false, reason: 'persistence' }
}

export function archiveAccount(store, id, archived = true) {
  return updateAccount(store, id, { isArchived: archived })
}

// MARK: - 分类

export async function createCategory(store, input) {
  const name = String(input.name ?? '').trim()
  if (name.length === 0) return { ok: false, reason: 'emptyName' }
  const kind = input.kind === 'income' ? 'income' : 'expense'
  const parent = input.parentID ? store.category(input.parentID) : null
  // 两级封顶：挂到二级分类下时上提到它的父类。
  const parentID = parent ? (parent.parentID ?? parent.id) : null
  const siblings = store.categories.filter((row) => (row.parentID ?? null) === parentID && row.kind === kind)
  const category = {
    id: newID(),
    name,
    systemImage: input.systemImage ?? 'tag',
    kind,
    parentID,
    colorHex: input.colorHex ?? (parent ? parent.colorHex : '#68665E'),
    sortOrder: nextOrder(siblings),
    isArchived: false,
    isSeed: false,
  }
  const ok = await store.mutate((draft) => { draft.table('categories').push(category) })
  return ok ? { ok: true, category } : { ok: false, reason: 'persistence' }
}

export async function updateCategory(store, id, patch) {
  const ok = await store.mutate((draft) => {
    const rows = draft.table('categories')
    const index = rows.findIndex((row) => row.id === id)
    if (index < 0) return false
    const next = { ...rows[index] }
    if (patch.name !== undefined) next.name = String(patch.name).trim()
    if (patch.isArchived !== undefined) next.isArchived = !!patch.isArchived
    if (patch.colorHex !== undefined) next.colorHex = patch.colorHex
    if (patch.systemImage !== undefined) next.systemImage = patch.systemImage
    rows[index] = next
    return true
  })
  return ok ? { ok: true } : { ok: false, reason: 'persistence' }
}

// MARK: - 币种

function ensureCurrency(draft, code, rate) {
  const rows = draft.table('currencies')
  const upper = String(code ?? '').toUpperCase()
  if (upper.length === 0) return null
  const existing = rows.find((row) => row.code === upper)
  if (existing) return existing
  const value = Number(rate)
  const configured = Number.isFinite(value) && value > 0
  const row = {
    code: upper,
    symbol: currencySymbol(upper),
    decimals: currencyDecimals(upper),
    // rate <= 0 视为没给：rateToBase 占位 1，但 rateConfigured = false（进不了汇总）。
    rateToBase: configured ? value : 1,
    isBase: rows.length === 0,
    manualRate: false,
    rateConfigured: rows.length === 0 ? true : configured,
    sortOrder: rows.length,
    updatedAt: Date.now(),
  }
  rows.push(row)
  return row
}

export async function addCurrency(store, code, rate) {
  const upper = String(code ?? '').toUpperCase()
  if (upper.length !== 3) return { ok: false, reason: 'invalidCode' }
  if (store.currencyRow(upper)) return { ok: true, duplicate: true }
  const ok = await store.mutate((draft) => { ensureCurrency(draft, upper, rate) })
  return ok ? { ok: true } : { ok: false, reason: 'persistence' }
}

/** 手动设定汇率 → 标 manual（在线刷新不再覆盖）。 */
export async function setRate(store, code, rate) {
  const value = Number(rate)
  if (!Number.isFinite(value) || value <= 0) return { ok: false, reason: 'invalidRate' }
  const ok = await store.mutate((draft) => {
    const rows = draft.table('currencies')
    const index = rows.findIndex((row) => row.code === String(code).toUpperCase())
    if (index < 0) return false
    rows[index] = { ...rows[index], rateToBase: value, manualRate: true, rateConfigured: true, updatedAt: Date.now() }
    return true
  })
  return ok ? { ok: true } : { ok: false, reason: 'persistence' }
}

/**
 * 切换基准币：要求目标币已配置汇率且 > 0。
 * `divisor = 目标币当前 rateToBase`，把**所有币**的 rateToBase 除以它，再把目标币置 1 并标 isBase。
 */
export async function setBaseCurrency(store, code) {
  const upper = String(code ?? '').toUpperCase()
  const target = store.currencyRow(upper)
  if (!target) return { ok: false, reason: 'unknownCurrency' }
  if (target.isBase) return { ok: true, noop: true }
  const divisor = Number(target.rateToBase)
  if (!target.rateConfigured || !(divisor > 0)) return { ok: false, reason: 'rateNeeded' }
  const ok = await store.mutate((draft) => {
    const rows = draft.table('currencies')
    for (let i = 0; i < rows.length; i += 1) {
      const row = rows[i]
      rows[i] = {
        ...row,
        rateToBase: row.code === upper ? 1 : Number(row.rateToBase) / divisor,
        isBase: row.code === upper,
        rateConfigured: row.code === upper ? true : row.rateConfigured,
        updatedAt: Date.now(),
      }
    }
    return true
  })
  return ok ? { ok: true } : { ok: false, reason: 'persistence' }
}

/**
 * 在线刷新写回：只更新 `!isBase && !manualRate` 的币；**手动锁定的币绝不覆盖**。
 * 先算出会不会真的变，没变就完全不进 mutate ——「无事发生」不能被报成写失败。
 */
export async function applyFetchedRates(store, rates) {
  if (!rates) return { ok: false, reason: 'unavailable' }
  const updates = []
  for (const row of store.currencies) {
    if (row.isBase || row.manualRate) continue
    const inverse = Number(rates[row.code])
    if (!Number.isFinite(inverse) || inverse <= 0) continue
    const next = 1 / inverse
    if (row.rateConfigured && Math.abs(next - Number(row.rateToBase)) < 1e-12) continue
    updates.push({ code: row.code, rateToBase: next })
  }
  if (updates.length === 0) return { ok: true, changed: false }
  const ok = await store.mutate((draft) => {
    const rows = draft.table('currencies')
    for (const update of updates) {
      const index = rows.findIndex((row) => row.code === update.code)
      if (index < 0) continue
      rows[index] = { ...rows[index], rateToBase: update.rateToBase, rateConfigured: true, updatedAt: Date.now() }
    }
    return true
  })
  return ok ? { ok: true, changed: true } : { ok: false, reason: 'persistence' }
}

// MARK: - 预算（upsert：limit ≤ 0 视为删除该行）

export async function upsertBudget(store, monthKey, categoryID, limitMinor, carryover) {
  const limit = Math.round(limitMinor ?? 0)
  const ok = await store.mutate((draft) => {
    const rows = draft.table('budgets')
    const index = rows.findIndex((row) => row.monthKey === monthKey && (row.categoryID ?? null) === (categoryID ?? null))
    if (limit <= 0) {
      if (index >= 0) rows.splice(index, 1)
      return true
    }
    const next = {
      id: index >= 0 ? rows[index].id : newID(),
      monthKey,
      categoryID: categoryID ?? null,
      limitMinor: limit,
      carryover: !!carryover,
    }
    if (index >= 0) rows[index] = next
    else rows.push(next)
    return true
  })
  return ok ? { ok: true, removed: limit <= 0 } : { ok: false, reason: 'persistence' }
}

// MARK: - 项目

export async function createProject(store, input) {
  const name = String(input.name ?? '').trim()
  if (name.length === 0) return { ok: false, reason: 'emptyName' }
  const project = {
    id: newID(),
    name,
    note: String(input.note ?? ''),
    systemImage: input.systemImage ?? 'airplane',
    colorHex: input.colorHex ?? '#3A83D0',
    startOn: input.startOn !== undefined && input.startOn !== null ? dayStart(input.startOn) : null,
    endOn: input.endOn !== undefined && input.endOn !== null ? dayStart(input.endOn) : null,
    budgetMinor: Math.max(0, Math.round(input.budgetMinor ?? 0)),
    isActive: !!input.isActive,
    isArchived: false,
    sortOrder: nextOrder(store.projects),
    createdAt: Date.now(),
  }
  const ok = await store.mutate((draft) => {
    const rows = draft.table('projects')
    if (project.isActive) {
      for (let i = 0; i < rows.length; i += 1) if (rows[i].isActive) rows[i] = { ...rows[i], isActive: false }
    }
    rows.push(project)
  })
  return ok ? { ok: true, project } : { ok: false, reason: 'persistence' }
}

export async function updateProject(store, id, patch) {
  const ok = await store.mutate((draft) => {
    const rows = draft.table('projects')
    const index = rows.findIndex((row) => row.id === id)
    if (index < 0) return false
    const next = { ...rows[index] }
    if (patch.name !== undefined) next.name = String(patch.name).trim()
    if (patch.note !== undefined) next.note = String(patch.note)
    if (patch.systemImage !== undefined) next.systemImage = patch.systemImage
    if (patch.colorHex !== undefined) next.colorHex = patch.colorHex
    if (patch.startOn !== undefined) next.startOn = patch.startOn === null ? null : dayStart(patch.startOn)
    if (patch.endOn !== undefined) next.endOn = patch.endOn === null ? null : dayStart(patch.endOn)
    if (patch.budgetMinor !== undefined) next.budgetMinor = Math.max(0, Math.round(patch.budgetMinor))
    if (patch.isArchived !== undefined) next.isArchived = !!patch.isArchived
    if (patch.isActive !== undefined) {
      next.isActive = !!patch.isActive
      // 至多一个 true。
      if (next.isActive) {
        for (let i = 0; i < rows.length; i += 1) {
          if (rows[i].id !== id && rows[i].isActive) rows[i] = { ...rows[i], isActive: false }
        }
      }
    }
    if (next.isArchived) next.isActive = false
    rows[index] = next
    return true
  })
  return ok ? { ok: true } : { ok: false, reason: 'persistence' }
}

/** 设为当前项目；`null` 清空。 */
export async function activateProject(store, id) {
  const ok = await store.mutate((draft) => {
    const rows = draft.table('projects')
    for (let i = 0; i < rows.length; i += 1) {
      const shouldBeActive = id !== null && rows[i].id === id
      if (rows[i].isActive !== shouldBeActive) rows[i] = { ...rows[i], isActive: shouldBeActive }
    }
    return true
  })
  return ok ? { ok: true } : { ok: false, reason: 'persistence' }
}

// MARK: - 成员

export async function addMember(store, projectID, input) {
  const name = String(input.name ?? '').trim()
  if (name.length === 0) return { ok: false, reason: 'emptyName' }
  const existing = store.projectMembers(projectID)
  const member = {
    id: newID(),
    projectID,
    name,
    isMe: !!input.isMe,
    colorHex: input.colorHex ?? MEMBER_COLORS[existing.length % MEMBER_COLORS.length],
    sortOrder: nextOrder(existing),
    createdAt: Date.now(),
  }
  const ok = await store.mutate((draft) => {
    const rows = draft.table('members')
    // 每项目至多一个 isMe。
    if (member.isMe) {
      for (let i = 0; i < rows.length; i += 1) {
        if (rows[i].projectID === projectID && rows[i].isMe) rows[i] = { ...rows[i], isMe: false }
      }
    }
    rows.push(member)
  })
  return ok ? { ok: true, member } : { ok: false, reason: 'persistence' }
}

export async function updateMember(store, id, patch) {
  const ok = await store.mutate((draft) => {
    const rows = draft.table('members')
    const index = rows.findIndex((row) => row.id === id)
    if (index < 0) return false
    const next = { ...rows[index] }
    if (patch.name !== undefined) next.name = String(patch.name).trim()
    if (patch.colorHex !== undefined) next.colorHex = patch.colorHex
    if (patch.isMe !== undefined) {
      next.isMe = !!patch.isMe
      if (next.isMe) {
        for (let i = 0; i < rows.length; i += 1) {
          if (rows[i].id !== id && rows[i].projectID === next.projectID && rows[i].isMe) {
            rows[i] = { ...rows[i], isMe: false }
          }
        }
      }
    }
    rows[index] = next
    return true
  })
  return ok ? { ok: true } : { ok: false, reason: 'persistence' }
}

/**
 * 删成员（§4.6）：清掉其付款流水的 payerMemberID（回落到「我」）→ 从所有分摊方案里剔除
 * → 删掉涉及 TA 的结算 → 删成员。全部在**同一次 mutate** 里落地。
 */
export async function removeMember(store, id) {
  const member = store.member(id)
  if (!member) return { ok: false, reason: 'notFound' }
  const affected = store.allTransactions().filter((row) => (
    row.projectID === member.projectID
    && (row.payerMemberID === id || (row.split && (row.split.shares ?? []).some((s) => s.memberID === id)))
  ))
  const doomed = store.settlements.filter((row) => row.fromMemberID === id || row.toMemberID === id)
  const ok = await store.mutate((draft) => {
    for (const txn of affected) {
      const next = { ...txn }
      if (next.payerMemberID === id) next.payerMemberID = null
      if (next.split) {
        const shares = (next.split.shares ?? []).filter((s) => s.memberID !== id)
        next.split = shares.length > 0 ? { ...next.split, shares } : null
      }
      draft.putTx(next)
    }
    if (doomed.length > 0) {
      const rows = draft.table('settlements')
      for (const row of doomed) {
        const index = rows.findIndex((entry) => entry.id === row.id)
        if (index >= 0) rows.splice(index, 1)
      }
    }
    const members = draft.table('members')
    const index = members.findIndex((row) => row.id === id)
    if (index >= 0) members.splice(index, 1)
    return true
  })
  return ok ? { ok: true } : { ok: false, reason: 'persistence' }
}

export { ensureCurrency }

// 流水写操作（UI 与 AI action 共用同一份；**都必须走 store.mutate → WAL**，不允许绕过去直接写库）。
//
// 铁律（§10）：
//  1. `amountMinor` 恒正，方向靠 kind；唯一例外是校准的 `signedAdjustment`。
//  2. 转账 = 两笔互指的配对流水，删除/恢复/永久删除必须两腿一起。
//  3. 流水币种恒等于所属账户币种。
//  4. 保存成功与否以 `store.lastMutationSucceeded` 为准。

import { KIND, newID, normalizeTags } from './store.js'
import { dayStart, monthKeyOf } from './dates.js'

/** 幂等命中：同键已存在（未软删）就直接返回那条，不重复落账。 */
export function findByIdempotencyKey(store, key) {
  if (!key) return null
  return store.allTransactions().find((row) => row.idempotencyKey === key) ?? null
}

function accountCurrency(store, accountID) {
  const account = store.account(accountID)
  return account ? account.currency : store.baseCode
}

/**
 * 记一笔收支。`input` 用主单位以外的一切都已归一好（amountMinor 是整数分）。
 * 返回 `{ ok, transaction, reason }`。
 */
export async function recordEntry(store, input) {
  const existing = findByIdempotencyKey(store, input.idempotencyKey)
  if (existing) return { ok: true, transaction: existing, duplicate: true }

  const accountID = input.accountID ?? (store.defaultAccount() ? store.defaultAccount().id : null)
  if (!accountID) return { ok: false, reason: 'noAccount' }
  const currency = accountCurrency(store, accountID)
  if (!store.hasUsableRate(currency)) return { ok: false, reason: 'rateNeeded', currency }

  const txn = store.makeTransaction({ ...input, accountID, currency })
  store.applyPostingSnapshot(txn)
  const ok = await store.mutate((draft) => { draft.putTx(txn) })
  return ok ? { ok: true, transaction: txn } : { ok: false, reason: 'persistence' }
}

/**
 * 转账：两笔互指的配对流水，一次 mutate 落地。
 * 同月落在同一个月份文档里 = 一次原子写；跨月由 WAL 兜底。
 */
export async function recordTransfer(store, input) {
  const existing = findByIdempotencyKey(store, input.idempotencyKey)
  if (existing) return { ok: true, transaction: existing, duplicate: true }

  const fromAccount = store.account(input.fromAccountID)
  const toAccount = store.account(input.toAccountID)
  if (!fromAccount || !toAccount) return { ok: false, reason: 'noAccount' }
  if (fromAccount.id === toAccount.id) return { ok: false, reason: 'sameAccount' }
  if (!store.hasUsableRate(fromAccount.currency) || !store.hasUsableRate(toAccount.currency)) {
    return { ok: false, reason: 'rateNeeded' }
  }

  const outID = newID()
  const inID = newID()
  const outAmount = Math.abs(Math.round(input.amountMinor))
  const inAmount = input.toAmountMinor !== undefined && input.toAmountMinor !== null
    ? Math.abs(Math.round(input.toAmountMinor))
    : store.convertMinor(outAmount, fromAccount.currency, toAccount.currency)

  const shared = {
    occurredOn: input.occurredOn,
    createdAt: input.createdAt,
    note: input.note,
    merchant: input.merchant,
    tags: input.tags,
    projectID: input.projectID ?? null,
    source: input.source ?? 'manual',
    calculationExpression: input.calculationExpression ?? null,
    batchID: input.batchID ?? null,
  }
  const legOut = store.makeTransaction({
    ...shared, id: outID, kind: KIND.transferOut, amountMinor: outAmount,
    accountID: fromAccount.id, currency: fromAccount.currency, transferPeerID: inID,
    idempotencyKey: input.idempotencyKey ?? null,
  })
  const legIn = store.makeTransaction({
    ...shared, id: inID, kind: KIND.transferIn, amountMinor: inAmount,
    accountID: toAccount.id, currency: toAccount.currency, transferPeerID: outID,
  })
  store.applyPostingSnapshot(legOut)
  store.applyPostingSnapshot(legIn)

  const ok = await store.mutate((draft) => { draft.putTx(legOut); draft.putTx(legIn) })
  return ok ? { ok: true, transaction: legOut, peer: legIn } : { ok: false, reason: 'persistence' }
}

/** 需要重新锁定入账快照的「实质变更」。 */
function needsResnapshot(before, after) {
  return before.amountMinor !== after.amountMinor
    || before.currency !== after.currency
    || before.accountID !== after.accountID
}

/** 编辑一笔（转账会顺着 transferPeerID 同步对手腿的日期/备注/项目）。 */
export async function updateEntry(store, id, patch) {
  const current = store.transaction(id)
  if (!current) return { ok: false, reason: 'notFound' }

  const next = { ...current }
  for (const [key, value] of Object.entries(patch)) {
    if (value === undefined) continue
    next[key] = value
  }
  if (patch.tags !== undefined) next.tags = normalizeTags(patch.tags)
  if (patch.occurredOn !== undefined) next.occurredOn = dayStart(patch.occurredOn)
  if (patch.accountID !== undefined) next.currency = accountCurrency(store, next.accountID)
  next.amountMinor = Math.abs(Math.round(next.amountMinor))
  if (next.kind !== KIND.adjustment) next.signedAdjustment = 0
  if (!store.hasUsableRate(next.currency)) return { ok: false, reason: 'rateNeeded', currency: next.currency }
  if (needsResnapshot(current, next)) store.applyPostingSnapshot(next)

  const peerID = current.transferPeerID
  const ok = await store.mutate((draft) => {
    draft.putTx(next)
    if (peerID) {
      const peer = draft.tx(peerID)
      if (peer) {
        const updated = { ...peer, occurredOn: next.occurredOn, note: next.note, projectID: next.projectID }
        if (patch.transferAmountMinor !== undefined) {
          updated.amountMinor = Math.abs(Math.round(patch.transferAmountMinor))
          store.applyPostingSnapshot(updated)
        }
        draft.putTx(updated)
      }
    }
  })
  return ok ? { ok: true, transaction: next } : { ok: false, reason: 'persistence' }
}

/** 软删（tombstone）。转账两腿一起。 */
export async function deleteEntry(store, id) {
  const current = store.transaction(id)
  if (!current) return { ok: false, reason: 'notFound' }
  const now = Date.now()
  const ok = await store.mutate((draft) => {
    draft.putTx({ ...current, deletedAt: now })
    if (current.transferPeerID) {
      const peer = draft.tx(current.transferPeerID)
      if (peer) draft.putTx({ ...peer, deletedAt: now })
    }
  })
  return ok ? { ok: true, transaction: current } : { ok: false, reason: 'persistence' }
}

/** 撤销删除。转账两腿一起。 */
export async function restoreEntry(store, id) {
  const key = store.txMonth.get(id)
  if (key === null || key === undefined) return { ok: false, reason: 'notFound' }
  const current = (store.months[key] ?? []).find((row) => row.id === id)
  if (!current) return { ok: false, reason: 'notFound' }
  const ok = await store.mutate((draft) => {
    draft.putTx({ ...current, deletedAt: null })
    if (current.transferPeerID) {
      const peer = draft.tx(current.transferPeerID)
      if (peer) draft.putTx({ ...peer, deletedAt: null })
    }
  })
  return ok ? { ok: true } : { ok: false, reason: 'persistence' }
}

/** 永久删除（物理移除）。转账两腿一起。 */
export async function purgeEntry(store, id) {
  const key = store.txMonth.get(id)
  if (key === null || key === undefined) return { ok: false, reason: 'notFound' }
  const current = (store.months[key] ?? []).find((row) => row.id === id)
  if (!current) return { ok: false, reason: 'notFound' }
  const ok = await store.mutate((draft) => {
    draft.dropTx(id)
    if (current.transferPeerID) draft.dropTx(current.transferPeerID)
  })
  return ok ? { ok: true } : { ok: false, reason: 'persistence' }
}

/** 最近删除列表：`deletedAt != nil`，按 deletedAt 倒序，上限 200，**转账两腿只展示一条**。 */
export function recentlyDeleted(store, limit = 200) {
  const rows = store.allTransactionsIncludingDeleted()
    .filter((row) => !!row.deletedAt)
    .sort((a, b) => b.deletedAt - a.deletedAt)
  const seen = new Set()
  const out = []
  for (const row of rows) {
    // 以「两个 id 里字典序较小的那个」作为配对键去重。
    const key = row.transferPeerID
      ? [row.id, row.transferPeerID].sort()[0]
      : row.id
    if (seen.has(key)) continue
    seen.add(key)
    out.push(row)
    if (out.length >= limit) break
  }
  return out
}

/** 按日分组：日期倒序，组内按 createdAt 倒序。 */
export function groupByDay(transactions) {
  const map = new Map()
  for (const row of transactions) {
    const key = dayStart(row.occurredOn)
    if (!map.has(key)) map.set(key, [])
    map.get(key).push(row)
  }
  return [...map.entries()]
    .sort((a, b) => b[0] - a[0])
    .map(([day, rows]) => ({ day, rows: rows.sort((a, b) => b.createdAt - a.createdAt) }))
}

export { monthKeyOf }

// 金额表达式求值（对应原生 LedgerAmountExpression）。
//
// 纪律：**全程零浮点**。词法 + 递归下降解析成精确有理数（BigInt 分子/分母），
// 只在最后一步 `×100 四舍五入到分` 时才落成整数。原生用 Swift `Decimal`；这里用有理数，
// 精度只会更好（`10/3*3` 在定点数下会漂成 9.99，有理数恒等于 10）。
//
// 文法（标准优先级 + 括号）：
//   expression := term (('+' | '-') term)*
//   term       := factor (('*' | '/') factor)*
//   factor     := '+' factor | '-' factor | '(' expression ')' | number
//   number     := digit+ ( ('.' | ',') digit+ )?      // 最多一个分隔符；',' 等同小数点

/** 错误码，与原生 `LedgerAmountExpression.Error` 一一对应。 */
export const ExprError = {
  empty: 'empty',
  invalidToken: 'invalidToken',
  missingOperand: 'missingOperand',
  mismatchedParenthesis: 'mismatchedParenthesis',
  divisionByZero: 'divisionByZero',
  trailingInput: 'trailingInput',
}

export class ExpressionError extends Error {
  constructor(code) {
    super(code)
    this.code = code
    this.name = 'ExpressionError'
  }
}

// MARK: - 有理数（BigInt 分子 / 分母，分母恒 > 0，恒约分）

function gcd(a, b) {
  let x = a < 0n ? -a : a
  let y = b < 0n ? -b : b
  while (y) { const t = x % y; x = y; y = t }
  return x
}

function rat(n, d) {
  if (d === 0n) throw new ExpressionError(ExprError.divisionByZero)
  let num = n
  let den = d
  if (den < 0n) { num = -num; den = -den }
  const g = gcd(num, den)
  if (g > 1n) { num /= g; den /= g }
  return { n: num, d: den }
}

const ZERO = { n: 0n, d: 1n }

const add = (a, b) => rat(a.n * b.d + b.n * a.d, a.d * b.d)
const sub = (a, b) => rat(a.n * b.d - b.n * a.d, a.d * b.d)
const mul = (a, b) => rat(a.n * b.n, a.d * b.d)
const neg = (a) => ({ n: -a.n, d: a.d })

function div(a, b) {
  if (b.n === 0n) throw new ExpressionError(ExprError.divisionByZero)
  return rat(a.n * b.d, a.d * b.n)
}

/** 有理数 × 100 → 整数分，四舍五入（half away from zero，与 Swift `.plain` 一致）。 */
export function ratToMinor(value) {
  const num = value.n * 100n
  const den = value.d
  const negative = num < 0n
  const abs = negative ? -num : num
  // floor(abs/den) + (余数×2 >= den ? 1 : 0)
  let q = abs / den
  const r = abs % den
  if (r * 2n >= den) q += 1n
  return Number(negative ? -q : q)
}

// MARK: - 预归一

/** 进解析器前逐字符替换：全角运算符与逗号。 */
export function normalizeExpression(input) {
  let out = ''
  for (const ch of String(input ?? '')) {
    if (ch === '−') out += '-'           // − 减号
    else if (ch === '×') out += '*'      // ×
    else if (ch === '÷') out += '/'      // ÷
    else if (ch === '，') out += ','      // 全角逗号
    else out += ch
  }
  return out
}

// MARK: - 词法

const DIGITS = '0123456789'

function tokenize(source) {
  const tokens = []
  let i = 0
  while (i < source.length) {
    const ch = source[i]
    if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r') { i += 1; continue }
    if (DIGITS.includes(ch) || ch === '.' || ch === ',') {
      let digits = ''
      let fraction = ''
      let separatorSeen = false
      while (i < source.length) {
        const c = source[i]
        if (DIGITS.includes(c)) {
          if (separatorSeen) fraction += c
          else digits += c
          i += 1
        } else if (c === '.' || c === ',') {
          // 一个数里出现两个分隔符 → invalidToken
          if (separatorSeen) throw new ExpressionError(ExprError.invalidToken)
          separatorSeen = true
          i += 1
        } else break
      }
      if (digits.length === 0 && fraction.length === 0) throw new ExpressionError(ExprError.invalidToken)
      const whole = digits.length > 0 ? digits : '0'
      const scale = BigInt(10) ** BigInt(fraction.length)
      const n = BigInt(whole) * scale + (fraction.length > 0 ? BigInt(fraction) : 0n)
      tokens.push({ kind: 'number', value: rat(n, scale) })
      continue
    }
    if ('+-*/()'.includes(ch)) { tokens.push({ kind: ch }); i += 1; continue }
    throw new ExpressionError(ExprError.invalidToken)
  }
  return tokens
}

// MARK: - 递归下降

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.index = 0
  }

  peek() { return this.index < this.tokens.length ? this.tokens[this.index] : null }

  expression() {
    let value = this.term()
    for (;;) {
      const token = this.peek()
      if (!token || (token.kind !== '+' && token.kind !== '-')) return value
      this.index += 1
      const right = this.term()
      value = token.kind === '+' ? add(value, right) : sub(value, right)
    }
  }

  term() {
    let value = this.factor()
    for (;;) {
      const token = this.peek()
      if (!token || (token.kind !== '*' && token.kind !== '/')) return value
      this.index += 1
      const right = this.factor()
      value = token.kind === '*' ? mul(value, right) : div(value, right)
    }
  }

  factor() {
    const token = this.peek()
    if (!token) throw new ExpressionError(ExprError.missingOperand)
    if (token.kind === '+') { this.index += 1; return this.factor() }
    if (token.kind === '-') { this.index += 1; return neg(this.factor()) }
    if (token.kind === '(') {
      this.index += 1
      const value = this.expression()
      const closing = this.peek()
      if (!closing || closing.kind !== ')') throw new ExpressionError(ExprError.mismatchedParenthesis)
      this.index += 1
      return value
    }
    if (token.kind === 'number') { this.index += 1; return token.value }
    if (token.kind === ')') throw new ExpressionError(ExprError.mismatchedParenthesis)
    throw new ExpressionError(ExprError.missingOperand)
  }
}

/** 求值成有理数。抛 `ExpressionError`。 */
export function evaluateRational(input) {
  const source = normalizeExpression(input).trim()
  if (source.length === 0) throw new ExpressionError(ExprError.empty)
  const parser = new Parser(tokenize(source))
  const value = parser.expression()
  const rest = parser.peek()
  if (rest) {
    if (rest.kind === ')') throw new ExpressionError(ExprError.mismatchedParenthesis)
    throw new ExpressionError(ExprError.trailingInput)
  }
  return value
}

/** 求值成整数分（round_half_up(value × 100)）。抛 `ExpressionError`。 */
export function evaluateMinor(input) {
  return ratToMinor(evaluateRational(input))
}

/** 求值成整数分；失败返回 null（UI 用，不想接异常的地方）。 */
export function tryEvaluateMinor(input) {
  try { return evaluateMinor(input) } catch (error) { return null }
}

/**
 * 折叠成显示串（按「=」时把表达式收成结果串）。
 *
 * ⚠️ 复刻原生怪癖：内部走「取绝对值」的纯数字格式化，**负结果会丢负号**（`-5` → `5`）。
 * 因为保存要求 > 0，实际不影响落账。见 README「有意保留的原生怪癖」。
 */
export function displayValue(input) {
  const minor = evaluateMinor(input)
  const abs = Math.abs(minor)
  const whole = Math.trunc(abs / 100)
  const cents = abs % 100
  if (cents === 0) return String(whole)
  if (cents % 10 === 0) return `${whole}.${cents / 10}`
  return `${whole}.${String(cents).padStart(2, '0')}`
}

// MARK: - 计算器键盘的输入规则（§2.7 ⑥）

const OPERATORS = '+-−*×/÷'
const TOKEN_BREAKERS = '+−-×*÷/()'

/** 取当前正在输入的数字 token（切分符 = `+ − × ÷ * / ( )`）。 */
export function currentToken(input) {
  const text = String(input ?? '')
  let start = text.length
  while (start > 0 && !TOKEN_BREAKERS.includes(text[start - 1])) start -= 1
  return text.slice(start)
}

/** 追加一个运算符。空串时只允许负号；末尾已是运算符则替换。 */
export function appendOperator(input, op) {
  const text = String(input ?? '')
  if (text.length === 0) return op === '−' ? op : text
  const last = text[text.length - 1]
  if (OPERATORS.includes(last)) return text.slice(0, -1) + op
  return text + op
}

/** 追加小数点：当前 token 已有小数点则忽略；token 为空时补成 `0.`。 */
export function appendDot(input) {
  const text = String(input ?? '')
  const token = currentToken(text)
  if (token.includes('.')) return text
  if (token.length === 0) return `${text}0.`
  return `${text}.`
}

/** 追加数字：小数位已 ≥ 2 则忽略；token 恰为 "0" 时先删掉（禁止 `07`）。 */
export function appendDigit(input, digit) {
  const text = String(input ?? '')
  const token = currentToken(text)
  const dot = token.indexOf('.')
  if (dot >= 0 && token.length - dot - 1 >= 2) return text
  if (token === '0') return `${text.slice(0, -1)}${digit}`
  return `${text}${digit}`
}

// 汇率与换算（§4.2）。纯函数，输入是币种表数组，不依赖 store。
//
// 铁律：**没有可用汇率的外币一律按 0 计入汇总**，绝不静默按 1:1 伪造金额。

export const RATE_ENDPOINT_HOST = 'open.er-api.com'

export function baseCurrency(currencies) {
  return currencies.find((row) => row.isBase) ?? currencies[0] ?? null
}

export function baseCode(currencies) {
  const base = baseCurrency(currencies)
  return base ? base.code : 'CNY'
}

export function currencyRow(currencies, code) {
  const upper = String(code ?? '').toUpperCase()
  return currencies.find((row) => row.code === upper) ?? null
}

/** 该币种是否可用于统计（基准币恒可用）。 */
export function hasUsableRate(currencies, code) {
  const row = currencyRow(currencies, code)
  if (!row) return String(code ?? '').toUpperCase() === baseCode(currencies)
  if (row.isBase) return true
  return !!row.rateConfigured && Number(row.rateToBase) > 0
}

/**
 * 原币分 → 基准币分。
 *   未登记的 code   → code === base ? minor : 0
 *   isBase          → minor
 *   未配置汇率/≤0   → 0        ← 从汇总里排除
 */
export function toBaseMinor(currencies, minor, code) {
  const value = Math.round(Number(minor) || 0)
  const upper = String(code ?? '').toUpperCase()
  const row = currencyRow(currencies, upper)
  if (!row) return upper === baseCode(currencies) ? value : 0
  if (row.isBase) return value
  const rate = Number(row.rateToBase)
  if (!row.rateConfigured || !(rate > 0)) return 0
  return Math.round(value * rate)
}

/** 任意币 → 任意币（先过基准币）。 */
export function convertMinor(currencies, minor, from, to) {
  const source = String(from ?? '').toUpperCase()
  const target = String(to ?? '').toUpperCase()
  if (source === target) return Math.round(Number(minor) || 0)
  const base = toBaseMinor(currencies, minor, source)
  const targetRow = currencyRow(currencies, target)
  if (!targetRow) return target === baseCode(currencies) ? base : 0
  if (targetRow.isBase) return base
  const rate = Number(targetRow.rateToBase)
  if (!targetRow.rateConfigured || !(rate > 0)) return 0
  return Math.round(base / rate)
}

/**
 * 报表/统计的唯一口径：优先用**入账那一刻冻结的基准币金额**（历史成本），
 * 这样刷新汇率不会让过去月份的数字漂移。只有切换基准币时才对冻结值做一次跨基准换算。
 */
export function reportingBaseMinor(currencies, txn) {
  const snapshot = txn.baseAmountMinorAtPosting
  const snapshotCode = txn.baseCurrencyAtPosting
  if (snapshot !== null && snapshot !== undefined && snapshotCode) {
    const current = baseCode(currencies)
    if (String(snapshotCode).toUpperCase() === current) return Math.round(snapshot)
    return convertMinor(currencies, snapshot, snapshotCode, current)
  }
  return toBaseMinor(currencies, txn.amountMinor, txn.currency)
}

/**
 * 入账快照：新增和「实质金额/账户/币种变更」时触发。
 * 该币种没有可用汇率 → 四个快照字段全部清空。
 */
export function applyPostingSnapshot(currencies, txn, now = Date.now()) {
  const row = currencyRow(currencies, txn.currency)
  const base = baseCurrency(currencies)
  if (!base || !row || (!row.isBase && (!row.rateConfigured || !(Number(row.rateToBase) > 0)))) {
    txn.baseAmountMinorAtPosting = null
    txn.baseCurrencyAtPosting = null
    txn.fxRateToBaseAtPosting = null
    txn.fxRateDate = null
    return txn
  }
  const rate = row.isBase ? 1 : Number(row.rateToBase)
  txn.baseAmountMinorAtPosting = Math.round(txn.amountMinor * rate)
  txn.baseCurrencyAtPosting = base.code
  txn.fxRateToBaseAtPosting = rate
  txn.fxRateDate = now
  return txn
}

/** 汇率显示格式：`>= 100` 用 4 位整数化的 2 位小数，否则 4 位小数。 */
export function formatRate(rate) {
  const value = Number(rate) || 0
  return value >= 100 ? value.toFixed(2) : value.toFixed(4)
}

/**
 * 在线汇率：`GET https://open.er-api.com/v6/latest/{BASE}`（免费、无需 key），超时 12 秒。
 * 返回 `rates[X] = 1 基准币 = 多少 X`；失败一律返回 null（**静默降级**，绝不用 1 兜底）。
 * 隐私：只把基准币码发出去，不含任何用户财务数据。
 */
export async function fetchRates(base, httpGetJSON) {
  const code = String(base ?? '').toUpperCase()
  if (code.length !== 3) return null
  const result = await httpGetJSON(`https://${RATE_ENDPOINT_HOST}/v6/latest/${code}`, { timeoutMs: 12000 })
  if (!result.ok || !result.body) return null
  const payload = result.body
  if (payload.result === 'error') return null
  const rates = payload.rates
  if (!rates || typeof rates !== 'object' || Object.keys(rates).length === 0) return null
  return rates
}

// 宿主桥的薄封装。三条纪律（与资讯包一致）：
//  1. 每个能力**先探测再使用**——宿主没装/没授权时 `window.aibox.<ns>` 根本不存在，
//     入口要整块不渲染，而不是点了没反应；
//  2. 调用不抛到 UI 层，失败回落成可判定的返回值；
//  3. 没有 aibox 时（普通浏览器预览、Node 自测）退化成内存实现，页面仍能跑。
//
// **例外：`db` 的失败必须抛出**——记账是财务数据，写失败绝不能被吞掉后照常刷新 UI
// （§4.7 可靠性契约）。所以 db 相关调用不在这里兜底，见 lib/db.js。

const bridge = () => (typeof window !== 'undefined' ? window.aibox : undefined)

export function hasNamespace(name, method) {
  const api = bridge()
  if (!api || !api[name]) return false
  return method ? typeof api[name][method] === 'function' : true
}

export const capabilities = {
  get db() { return hasNamespace('db', 'query') },
  get tabs() { return hasNamespace('tabs', 'getState') },
  get toolbar() { return hasNamespace('toolbar', 'on') },
  get menu() { return hasNamespace('menu', 'update') },
  get navigation() { return hasNamespace('navigation', 'setTitle') },
  get scene() { return hasNamespace('scene', 'getState') },
  get ai() { return hasNamespace('ai', 'generate') },
  get net() { return hasNamespace('net', 'fetch') },
  get ui() { return hasNamespace('ui', 'confirm') },
  get picker() { return hasNamespace('picker', 'file') },
  get resource() { return hasNamespace('resource', 'readText') },
  get shareFile() { return hasNamespace('share', 'file') },
  get shareText() { return hasNamespace('share', 'text') },
  get haptics() { return hasNamespace('haptics', 'impact') },
}

// MARK: - storage（轻量偏好；不承载账本主数据）

const memoryStore = new Map()

export const storage = {
  async get(key) {
    const api = bridge()
    if (!api || !api.storage) return memoryStore.has(key) ? memoryStore.get(key) : null
    try {
      const value = await api.storage.get(key)
      return value === undefined ? null : value
    } catch (error) { return null }
  },
  async set(key, value) {
    const api = bridge()
    if (!api || !api.storage) { memoryStore.set(key, value); return true }
    try { await api.storage.set(key, value); return true } catch (error) { return false }
  },
}

// MARK: - net（原生代理，无 CORS 问题）

/** GET → `{ ok, status, body }`；软超时由调用方给（桥不接受 per-request timeout）。 */
export async function httpGetJSON(url, { timeoutMs = 12000 } = {}) {
  const api = bridge()
  if (!api || !api.net || typeof api.net.fetch !== 'function') return { ok: false }
  let timer = null
  const timeout = new Promise((resolve) => { timer = setTimeout(() => resolve({ __timeout: true }), timeoutMs) })
  try {
    const response = await Promise.race([
      api.net.fetch(url, { method: 'GET', responseType: 'json' }),
      timeout,
    ])
    if (!response || response.__timeout) return { ok: false }
    const status = Number(response.status || 0)
    if (status < 200 || status >= 300) return { ok: false, status }
    const body = typeof response.body === 'string' ? safeParse(response.body) : response.body
    return { ok: !!body, status, body }
  } catch (error) {
    return { ok: false }
  } finally {
    if (timer) clearTimeout(timer)
  }
}

function safeParse(text) {
  try { return JSON.parse(text) } catch (error) { return null }
}

// MARK: - ui（原生对话框；缺席时由调用方走自绘弹层）

export async function nativeConfirm({ title, message, confirmTitle, destructive }) {
  const api = bridge()
  if (!api || !api.ui || typeof api.ui.confirm !== 'function') return null
  try {
    const result = await api.ui.confirm({
      title,
      message,
      actions: [
        { id: 'confirm', title: confirmTitle, role: destructive ? 'destructive' : 'default' },
        { id: 'cancel', title: '', role: 'cancel' },
      ],
    })
    return !!(result && result.actionId === 'confirm' && !result.cancelled)
  } catch (error) { return null }
}

export async function nativeAlert({ title, message }) {
  const api = bridge()
  if (!api || !api.ui || typeof api.ui.alert !== 'function') return false
  try { await api.ui.alert({ title, message }); return true } catch (error) { return false }
}

/** 原生 action sheet（长按菜单）。返回选中的 id；不可用返回 undefined。 */
export async function nativeActionSheet({ title, message, actions }) {
  const api = bridge()
  if (!api || !api.ui || typeof api.ui.actionSheet !== 'function') return undefined
  try {
    const result = await api.ui.actionSheet({ title, message, actions })
    if (!result || result.cancelled) return null
    return result.actionId ?? null
  } catch (error) { return undefined }
}

// MARK: - picker / resource（CSV 导入）

/** 弹系统文档选择器读一个文本文件。返回 `{ ok, text, name }`。 */
export async function pickTextFile(types) {
  const api = bridge()
  if (!api || !api.picker || typeof api.picker.file !== 'function') return { ok: false, reason: 'unavailable' }
  try {
    const picked = await api.picker.file({ types, multiple: false })
    if (!picked || picked.cancelled) return { ok: false, reason: 'cancelled' }
    const item = (picked.items ?? [])[0]
    if (!item) return { ok: false, reason: 'cancelled' }
    if (!api.resource || typeof api.resource.readText !== 'function') return { ok: false, reason: 'unavailable' }
    const text = await api.resource.readText(item.handle)
    return { ok: true, text: String(text ?? ''), name: item.name ?? '' }
  } catch (error) {
    return { ok: false, reason: String((error && error.message) || error) }
  }
}

// MARK: - share（CSV 导出）

/**
 * 导出一个带文件名的文件。优先 `aibox.share.file`（合同见 app-shell-and-market.md §3.5）；
 * 宿主还没实现时降级到 `aibox.share.text`（接收方拿到的是一段文字而不是文件，调用方要告知用户）。
 * 返回 `'file' | 'text' | false`。
 */
export async function shareFile({ filename, content, mimeType }) {
  const api = bridge()
  if (api && api.share && typeof api.share.file === 'function') {
    try { await api.share.file({ filename, content, mimeType }); return 'file' } catch (error) { /* 降级 */ }
  }
  if (api && api.share && typeof api.share.text === 'function') {
    try { await api.share.text({ text: content, title: filename }); return 'text' } catch (error) { return false }
  }
  return false
}

// MARK: - ai

export async function aiAvailability() {
  const api = bridge()
  if (!api || !api.ai || typeof api.ai.availability !== 'function') return { available: false }
  try {
    const info = await api.ai.availability()
    return info && typeof info === 'object' ? info : { available: false }
  } catch (error) { return { available: false } }
}

export async function aiGenerate(input) {
  const api = bridge()
  if (!api || !api.ai || typeof api.ai.generate !== 'function') throw new Error('aibox/ai-unavailable')
  return api.ai.generate(input)
}

// MARK: - 事件总线 / 外壳

export function onEvent(name, handler) {
  const api = bridge()
  if (!api || !api.events || typeof api.events.on !== 'function') return () => {}
  return api.events.on(name, handler)
}

export function onNamespaceEvent(namespace, event, handler) {
  const api = bridge()
  if (!api || !api[namespace] || typeof api[namespace].on !== 'function') return () => {}
  return api[namespace].on(event, handler)
}

export function bridgeAPI() {
  return bridge()
}

/** 轻微触感（有就用，没有就算了）。 */
export function tapFeedback() {
  const api = bridge()
  if (api && api.haptics && typeof api.haptics.impact === 'function') {
    try { api.haptics.impact({ style: 'light' }) } catch (error) { /* 无所谓 */ }
  }
}

// 金额格式化与主单位↔分互转（§6.1）。
//
// 三条纪律：
//  1. 存储与运算一律**整数分**，浮点只允许出现在最终显示格式化这一步；
//  2. 负号一律用 U+2212「−」，不是 ASCII 连字符；
//  3. 所有金额文本用等宽数字（CSS `font-variant-numeric: tabular-nums`）。

import { currencyDecimals, currencySymbol } from './currencies.js'
import { evaluateMinor } from './expression.js'

export const MINUS = '−'

function groupInteger(text) {
  let out = ''
  let count = 0
  for (let i = text.length - 1; i >= 0; i -= 1) {
    out = text[i] + out
    count += 1
    if (count % 3 === 0 && i > 0) out = `,${out}`
  }
  return out
}

/**
 * `money(1234_56, 'CNY')` → `"¥1,234.56"`；`signed` 为真时正数补 `+`。
 * `decimals` 显式给时覆盖币种目录（0 位币不输出小数部分）。
 */
export function money(minor, currency, { signed = false, grouping = true, decimals } = {}) {
  const value = Math.round(Number(minor) || 0)
  const symbol = currencySymbol(currency)
  const digits = decimals === undefined || decimals === null ? currencyDecimals(currency) : decimals
  const negative = value < 0
  const abs = Math.abs(value)
  const whole = Math.trunc(abs / 100)
  const cents = abs % 100
  const wholeText = grouping ? groupInteger(String(whole)) : String(whole)
  let body = wholeText
  if (digits > 0) {
    const fraction = String(cents).padStart(2, '0').slice(0, Math.min(2, digits))
    body = `${wholeText}.${digits > 2 ? fraction.padEnd(digits, '0') : fraction}`
  }
  const sign = negative ? MINUS : (signed ? '+' : '')
  return `${sign}${symbol}${body}`
}

/** 紧凑金额：≥1,000,000 → `¥1.2M`；≥1,000 → `¥12.3k`；否则整数化。 */
export function moneyCompact(minor, currency) {
  const value = Math.round(Number(minor) || 0)
  const symbol = currencySymbol(currency)
  const negative = value < 0
  const major = Math.abs(value) / 100
  const sign = negative ? MINUS : ''
  if (major >= 1000000) return `${sign}${symbol}${(major / 1000000).toFixed(1)}M`
  if (major >= 1000) return `${sign}${symbol}${(major / 1000).toFixed(1)}k`
  return `${sign}${symbol}${Math.round(major)}`
}

/** `"1234.56"`——**取绝对值、丢符号、无千分位**；用于 CSV 导出与输入框预填。 */
export function plainMajor(minor) {
  const abs = Math.abs(Math.round(Number(minor) || 0))
  return `${Math.trunc(abs / 100)}.${String(abs % 100).padStart(2, '0')}`
}

/** 主单位串 → 分：先去空白/千分位/常见货币符号，再走定点解析。失败返回 null。 */
export function parseMajorToMinor(text) {
  const cleaned = String(text ?? '')
    .replace(/[\s ]/g, '')
    .replace(/,/g, '')
    .replace(/[¥$€£₩₫₹₱฿]/g, '')
  if (cleaned.length === 0) return null
  try {
    return evaluateMinor(cleaned)
  } catch (error) {
    return null
  }
}

/**
 * JS number 主单位（AI/CSV 传进来的 12.5）→ 分。
 *
 * ⚠️ **不要写 `Math.round(value * 100)`**：`1.005 * 100 === 100.49999999999999`，
 * 会把 1.005 记成 1.00。这里先把数字打成十进制字面量，再走与计算器完全同一套的
 * 精确有理数解析——「AI 给的浮点」和「用户敲的表达式」共用一条精度路径。
 */
export function majorNumberToMinor(value) {
  const number = Number(value)
  if (!Number.isFinite(number)) return 0
  const text = String(number)
  // 指数记法（1e+21 这种天文数字）超出记账量级，退回朴素路径而不是解析失败。
  if (text.includes('e') || text.includes('E')) {
    const scaled = number * 100
    return scaled < 0 ? -Math.round(-scaled) : Math.round(scaled)
  }
  try {
    return evaluateMinor(text)
  } catch (error) {
    return 0
  }
}

// 轻量偏好（§2.7 ⑧ / §9.2 19）。键名照抄原生 AppStorage，落 localStorage。
// 这些是「越用越顺手」的记忆，不是账本主数据，丢了不影响正确性，所以不进 db、不参与 WAL。

export const PREF_KEYS = {
  lastExpenseAccountID: 'ledger.entry.lastExpenseAccountID',
  lastIncomeAccountID: 'ledger.entry.lastIncomeAccountID',
  lastTransferAccountID: 'ledger.entry.lastTransferAccountID',
  recentExpenseCategories: 'ledger.entry.recentExpenseCategories',
  recentIncomeCategories: 'ledger.entry.recentIncomeCategories',
  localOCR: 'ledger.photo.localOCR',
}

const RECENT_LIMIT = 8

function read(key) {
  try {
    return typeof localStorage !== 'undefined' ? localStorage.getItem(key) : null
  } catch (error) { return null }
}

function write(key, value) {
  try {
    if (typeof localStorage !== 'undefined') localStorage.setItem(key, value)
  } catch (error) { /* 隐私模式等场景静默降级 */ }
}

/** 按收支方向记住上次账户；账户被归档则回落默认账户。 */
export function lastAccountID(store, direction) {
  const key = direction === 'income' ? PREF_KEYS.lastIncomeAccountID
    : direction === 'transfer' ? PREF_KEYS.lastTransferAccountID
      : PREF_KEYS.lastExpenseAccountID
  const stored = read(key)
  if (stored) {
    const account = store.account(stored)
    if (account && !account.isArchived) return account.id
  }
  const fallback = store.defaultAccount()
  return fallback ? fallback.id : null
}

export function rememberAccount(direction, accountID) {
  if (!accountID) return
  const key = direction === 'income' ? PREF_KEYS.lastIncomeAccountID
    : direction === 'transfer' ? PREF_KEYS.lastTransferAccountID
      : PREF_KEYS.lastExpenseAccountID
  write(key, accountID)
}

/** 最近使用分类（逗号分隔的 uuid 串，最多 8 个）。 */
export function recentCategories(kind) {
  const key = kind === 'income' ? PREF_KEYS.recentIncomeCategories : PREF_KEYS.recentExpenseCategories
  const raw = read(key)
  if (!raw) return []
  return raw.split(',').map((piece) => piece.trim()).filter((piece) => piece.length > 0)
}

export function rememberCategory(kind, categoryID) {
  if (!categoryID) return
  const key = kind === 'income' ? PREF_KEYS.recentIncomeCategories : PREF_KEYS.recentExpenseCategories
  const current = recentCategories(kind).filter((id) => id !== categoryID)
  write(key, [categoryID, ...current].slice(0, RECENT_LIMIT).join(','))
}

/**
 * 一级分类排序 = **最近使用优先**：把子类的使用次序归到其父类打分，同分再按 sortOrder；
 * 没有历史时直接按 sortOrder。
 */
export function sortRootCategoriesByRecency(store, roots, kind) {
  const recents = recentCategories(kind)
  if (recents.length === 0) return roots
  const score = new Map()
  recents.forEach((id, index) => {
    const rootID = store.rootCategoryID(id)
    if (!rootID) return
    if (!score.has(rootID)) score.set(rootID, index)
  })
  return [...roots].sort((a, b) => {
    const left = score.has(a.id) ? score.get(a.id) : Number.MAX_SAFE_INTEGER
    const right = score.has(b.id) ? score.get(b.id) : Number.MAX_SAFE_INTEGER
    if (left !== right) return left - right
    return a.sortOrder - b.sortOrder
  })
}

// 筛选与聚合（§4.3）。**UI 报表页与 AI 的 ledger_stats 共用这一份实现** ——
// 模型说的数和界面显示的数永远同源。

import { KIND, countsInFlow } from './store.js'
import { DAY_MS, dayStart, isoDay, monthKeyOf, monthTitle, shortDate } from './dates.js'

/**
 * 筛选。默认 `includeNonFlow = false` —— 没有显式指定 kind 时**自动剔除转账两腿与校准**。
 * 日期区间：`dateFrom` 含当天 00:00，`dateTo` **含当天**（内部转成次日 00:00 的开区间）。
 */
export function filterTransactions(store, filter = {}) {
  const kinds = filter.kinds ? new Set(filter.kinds) : null
  const from = filter.dateFrom !== undefined && filter.dateFrom !== null ? dayStart(filter.dateFrom) : null
  const to = filter.dateTo !== undefined && filter.dateTo !== null ? dayStart(filter.dateTo) + DAY_MS : null
  const includeNonFlow = filter.includeNonFlow === true || !!kinds
  const tag = filter.tag ? String(filter.tag).toLowerCase() : null

  return store.allTransactions().filter((txn) => {
    if (kinds && !kinds.has(txn.kind)) return false
    if (!includeNonFlow && !countsInFlow(txn)) return false
    if (from !== null && txn.occurredOn < from) return false
    if (to !== null && txn.occurredOn >= to) return false
    if (filter.accountID && txn.accountID !== filter.accountID) return false
    if (filter.projectID !== undefined && filter.projectID !== null && txn.projectID !== filter.projectID) return false
    if (filter.categoryID) {
      const root = store.rootCategoryID(txn.categoryID)
      if (txn.categoryID !== filter.categoryID && root !== filter.categoryID) return false
    }
    if (tag && !(txn.tags ?? []).some((row) => String(row).toLowerCase() === tag)) return false
    if (filter.reimbursable !== undefined && filter.reimbursable !== null
      && !!txn.reimbursable !== !!filter.reimbursable) return false
    if (filter.minAmountMinor !== undefined && filter.minAmountMinor !== null
      && txn.amountMinor < filter.minAmountMinor) return false
    if (filter.maxAmountMinor !== undefined && filter.maxAmountMinor !== null
      && txn.amountMinor > filter.maxAmountMinor) return false
    if (filter.keyword) {
      const needle = String(filter.keyword).trim().toLowerCase()
      if (needle.length > 0) {
        const haystack = [txn.merchant ?? '', txn.note ?? '', ...(txn.tags ?? [])].join(' ').toLowerCase()
        if (!haystack.includes(needle)) return false
      }
    }
    return true
  })
}

/**
 * 明细页的搜索匹配（§2.1 ⑤）：去空白小写后子串 contains，任一命中即算。
 * 覆盖 note / merchant / 任一 tag / **账户名** / **分类展示路径** / **项目名**。
 */
export function matchesSearch(store, txn, query) {
  const needle = String(query ?? '').trim().toLowerCase()
  if (needle.length === 0) return true
  const account = store.account(txn.accountID)
  const project = txn.projectID ? store.project(txn.projectID) : null
  const fields = [
    txn.note ?? '',
    txn.merchant ?? '',
    ...(txn.tags ?? []),
    account ? account.name : '',
    txn.categoryID ? store.categoryPath(txn.categoryID) : '',
    project ? project.name : '',
  ]
  return fields.some((field) => String(field).toLowerCase().includes(needle))
}

export const UNCATEGORIZED_KEY = '__uncat__'
export const UNTAGGED_KEY = '__untagged__'
export const NO_PROJECT_KEY = '__noproject__'

/**
 * 聚合成桶。
 * `metric`：`expense` 只留支出 / `income` 只留收入 / `net` 留 countsInFlow（收入 +、支出 −）。
 * 排序：`byDay` / `byMonth` 按 key **升序**（时间正序，给趋势图用）；其余按 **|金额| 降序**。
 * ⚠️ `byTag`：一笔多标签会给每个标签都加全额（**有意重复计数**）。
 */
export function buckets(store, transactions, dimension, metric, locale = 'en', labels = {}) {
  const map = new Map()
  const push = (key, label, amount, colorHex) => {
    let bucket = map.get(key)
    if (!bucket) {
      bucket = { key, label, amountMinor: 0, count: 0, colorHex: colorHex ?? null }
      map.set(key, bucket)
    }
    bucket.amountMinor += amount
    bucket.count += 1
    if (!bucket.colorHex && colorHex) bucket.colorHex = colorHex
  }

  for (const txn of transactions) {
    if (metric === 'expense' && txn.kind !== KIND.expense) continue
    if (metric === 'income' && txn.kind !== KIND.income) continue
    if (metric === 'net' && !countsInFlow(txn)) continue
    const base = store.reportingBaseMinor(txn)
    const amount = metric === 'net' ? (txn.kind === KIND.income ? base : -base) : base

    switch (dimension) {
      case 'byCategory': {
        const rootID = store.rootCategoryID(txn.categoryID)
        const category = rootID ? store.category(rootID) : null
        push(rootID ?? UNCATEGORIZED_KEY, category ? category.name : (labels.uncategorized ?? 'Uncategorized'),
          amount, category ? category.colorHex : null)
        break
      }
      case 'bySubcategory': {
        const category = txn.categoryID ? store.category(txn.categoryID) : null
        push(txn.categoryID ?? UNCATEGORIZED_KEY,
          category ? store.categoryPath(txn.categoryID) : (labels.uncategorized ?? 'Uncategorized'),
          amount, category ? category.colorHex : null)
        break
      }
      case 'byAccount': {
        const account = store.account(txn.accountID)
        push(txn.accountID ?? UNCATEGORIZED_KEY, account ? account.name : '—', amount, account ? account.colorHex : null)
        break
      }
      case 'byTag': {
        const tags = txn.tags ?? []
        if (tags.length === 0) push(UNTAGGED_KEY, labels.noTag ?? 'No tag', amount)
        else for (const tag of tags) push(`tag:${String(tag).toLowerCase()}`, String(tag), amount)
        break
      }
      case 'byDay':
        push(isoDay(txn.occurredOn), shortDate(txn.occurredOn, locale), amount)
        break
      case 'byMonth': {
        const key = monthKeyOf(txn.occurredOn)
        push(String(key), monthTitle(key, locale), amount)
        break
      }
      case 'byProject': {
        const project = txn.projectID ? store.project(txn.projectID) : null
        push(txn.projectID ?? NO_PROJECT_KEY, project ? project.name : (labels.noProject ?? 'No project'),
          amount, project ? project.colorHex : null)
        break
      }
      default:
        break
    }
  }

  const rows = [...map.values()]
  if (dimension === 'byDay' || dimension === 'byMonth') rows.sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0))
  else rows.sort((a, b) => Math.abs(b.amountMinor) - Math.abs(a.amountMinor))
  return rows
}

/** 期间语义（AI 工具的 `period`）。返回 `{from, to}`（含当天，ms）。 */
export function periodRange(period, now = Date.now()) {
  const today = dayStart(now)
  const date = new Date(today)
  switch (period) {
    case 'today': return { from: today, to: today }
    case 'this_week': {
      const weekday = (date.getDay() + 6) % 7 // 周一为一周之始
      return { from: today - weekday * DAY_MS, to: today }
    }
    case 'last_7_days': return { from: today - 6 * DAY_MS, to: today }
    case 'last_30_days': return { from: today - 29 * DAY_MS, to: today }
    case 'this_month': return { from: new Date(date.getFullYear(), date.getMonth(), 1).getTime(), to: today }
    case 'last_month': {
      const start = new Date(date.getFullYear(), date.getMonth() - 1, 1).getTime()
      const end = new Date(date.getFullYear(), date.getMonth(), 1).getTime() - DAY_MS
      return { from: start, to: end }
    }
    case 'this_year': return { from: new Date(date.getFullYear(), 0, 1).getTime(), to: today }
    case 'all': return { from: null, to: null }
    default: return { from: null, to: null }
  }
}

// 把 8 个 `ledger_*` 工具接到 `aibox.action.register`。
//
// 宿主把 manifest.actions[] 投影成**延迟工具**（不进常驻 tools 数组，AI 经 tool_search /
// describe / call 发现调用），执行回到页面里跑。三条硬要求：
//  1. 处理器必须在**无 UI 状态**下也能跑 —— 只依赖 store 与 lib/ 的纯函数；
//  2. 走的是与 UI **同一条带 WAL 的写路径**（store.mutate），不绕过去直接写库；
//  3. 返回 JSON 可序列化的结果，写失败时返回明确的「未保存」错误文本。

import { actionBudget, actionQuery, actionRecord, actionStats } from './actions.js'
import { actionAccount, actionCategory, actionCurrency, actionProject } from './actions-entities.js'

/** manifest.actions[].name → 处理器。 */
export const ACTION_HANDLERS = {
  record: actionRecord,
  query: actionQuery,
  stats: actionStats,
  budget: actionBudget,
  account: actionAccount,
  category: actionCategory,
  currency: actionCurrency,
  project: actionProject,
}

/**
 * `context()` 每次调用时求值，拿到当时的 store / locale —— 处理器不持有过期引用。
 * 返回退订函数（宿主没有 action 命名空间时是空函数）。
 */
export function registerLedgerActions(context) {
  const api = typeof window !== 'undefined' ? window.aibox : undefined
  if (!api || !api.action || typeof api.action.register !== 'function') return () => {}

  for (const [name, handler] of Object.entries(ACTION_HANDLERS)) {
    api.action.register(name, async (input) => {
      const { store, locale, labels } = context()
      const args = input && typeof input === 'object' ? input : {}
      // 库还没打开（冷启动 headless 调用）→ 先打开再执行。
      if (store.state === 'unopened') await store.open(locale)
      try {
        return await handler(store, args, locale, labels)
      } catch (error) {
        return { ok: false, text: `The ledger action failed and nothing was saved: ${String((error && error.message) || error)}` }
      }
    })
  }
  return () => {}
}

// 报表与预算聚合（§4.3）。UI 预算页与 AI 的 ledger_budget 共用 `budgetPayload`。

import { KIND } from './store.js'
import { addMonths, daysRemainingInMonth, monthEnd, monthKeyOf, monthStart } from './dates.js'

/** 月度收支：该月 income / expense 各自 `reportingBaseMinor` 之和。 */
export function monthlyFlow(store, monthKey) {
  let income = 0
  let expense = 0
  for (const txn of store.monthTransactions(monthKey)) {
    if (txn.kind === KIND.income) income += store.reportingBaseMinor(txn)
    else if (txn.kind === KIND.expense) expense += store.reportingBaseMinor(txn)
  }
  return { income, expense, net: income - expense }
}

/** 某分类（含其全部二级子类）在某月的支出合计（基准币）。`categoryID = null` 表示当月全部支出。 */
export function spentMinor(store, monthKey, categoryID) {
  let total = 0
  for (const txn of store.monthTransactions(monthKey)) {
    if (txn.kind !== KIND.expense) continue
    if (categoryID !== null && categoryID !== undefined) {
      if (store.rootCategoryID(txn.categoryID) !== categoryID && txn.categoryID !== categoryID) continue
    }
    total += store.reportingBaseMinor(txn)
  }
  return total
}

function budgetRow(store, monthKey, categoryID) {
  return store.budgets.find((row) => row.monthKey === monthKey && (row.categoryID ?? null) === (categoryID ?? null)) ?? null
}

/**
 * 有效额度（含结转，递归，最多回看 120 个月）：
 *   当月没有该 scope 的预算行 → (0, 0)
 *   上月存在同 scope 的行 **且上月 carryover == true**：
 *       carried = max(0, 上月有效额度 − 上月实际支出)   // 超支不产生负结转
 *       → (当月 limit + carried, carried)
 * 结转开关挂在**上一个月那一行**上。
 */
export function effectiveBudget(store, monthKey, categoryID, depth = 0) {
  const current = budgetRow(store, monthKey, categoryID)
  if (!current) return { limitMinor: 0, carriedMinor: 0 }
  if (depth >= 120) return { limitMinor: current.limitMinor, carriedMinor: 0 }
  const previousKey = addMonths(monthKey, -1)
  const previous = budgetRow(store, previousKey, categoryID)
  if (previous && previous.carryover) {
    const prior = effectiveBudget(store, previousKey, categoryID, depth + 1)
    const priorSpent = spentMinor(store, previousKey, categoryID)
    const carried = Math.max(0, prior.limitMinor - priorSpent)
    return { limitMinor: current.limitMinor + carried, carriedMinor: carried }
  }
  return { limitMinor: current.limitMinor, carriedMinor: 0 }
}

/**
 * 预算负载。
 *  - lines **按额度从大到小**排序
 *  - 总额度：有「categoryID == null 的总预算行」就用它的有效额度；否则 = **各分类有效额度之和**
 *  - `dailyRemaining = daysLeft > 0 ? max(0, remaining) / daysLeft : max(0, remaining)`
 */
export function budgetPayload(store, monthKey, now = Date.now()) {
  const totalSpent = spentMinor(store, monthKey, null)
  const lines = []
  for (const row of store.budgets) {
    if (row.monthKey !== monthKey || !row.categoryID) continue
    const effective = effectiveBudget(store, monthKey, row.categoryID)
    const category = store.category(row.categoryID)
    lines.push({
      categoryID: row.categoryID,
      name: category ? category.name : '—',
      colorHex: category ? category.colorHex : null,
      limitMinor: effective.limitMinor,
      carriedMinor: effective.carriedMinor,
      spentMinor: spentMinor(store, monthKey, row.categoryID),
      carryover: !!row.carryover,
    })
  }
  lines.sort((a, b) => b.limitMinor - a.limitMinor)

  const overall = budgetRow(store, monthKey, null)
  let totalLimit = 0
  let totalCarried = 0
  if (overall) {
    const effective = effectiveBudget(store, monthKey, null)
    totalLimit = effective.limitMinor
    totalCarried = effective.carriedMinor
  } else {
    for (const line of lines) { totalLimit += line.limitMinor; totalCarried += line.carriedMinor }
  }

  const remaining = totalLimit - totalSpent
  const daysLeft = daysRemainingInMonth(monthKey, now)
  const dailyRemaining = daysLeft > 0 ? Math.round(Math.max(0, remaining) / daysLeft) : Math.max(0, remaining)
  return {
    monthKey,
    totalLimitMinor: totalLimit,
    totalCarriedMinor: totalCarried,
    totalSpentMinor: totalSpent,
    remainingMinor: remaining,
    daysLeft,
    dailyRemainingMinor: dailyRemaining,
    hasExplicitTotal: !!overall,
    lines,
  }
}

/** 该月的流水（报表页口径：只保留 countsInFlow）。 */
export function monthFlowTransactions(store, monthKey) {
  return store.monthTransactions(monthKey)
    .filter((txn) => txn.kind === KIND.expense || txn.kind === KIND.income)
}

export { monthKeyOf, monthStart, monthEnd }

// 名称解析（§4.5）—— AI 工具与 CSV 导入共用的自愈逻辑。
//
// 纪律：**多候选时绝不静默默认**，而是回一份候选清单让模型重问。
// 返回 `{ found, value }` 或 `{ found: false, candidates: [...] }`。

const SEPARATORS = ['/', '／', '>', '-', '·']

const hit = (value) => ({ found: true, value })
const miss = (candidates) => ({ found: false, candidates: candidates ?? [] })

function lower(text) {
  return String(text ?? '').trim().toLowerCase()
}

/**
 * 分类：
 *  1. 含分隔符 → 取**最后一段**在二级分类里找同名
 *  2. 精确同名（不分大小写）：1 个命中；多个 → 候选展示路径列表
 *  3. 模糊（互相 contains）：0 未找到；1 命中；多个 → 候选列表
 */
export function resolveCategory(store, raw, kind) {
  const needle = lower(raw)
  if (needle.length === 0) return miss()
  const pool = store.categories.filter((row) => row.kind === kind && !row.isArchived)

  for (const separator of SEPARATORS) {
    if (!needle.includes(separator)) continue
    const tail = lower(needle.split(separator).pop())
    if (tail.length === 0) continue
    const child = pool.find((row) => row.parentID && lower(row.name) === tail)
    if (child) return hit(child)
  }

  const exact = pool.filter((row) => lower(row.name) === needle)
  if (exact.length === 1) return hit(exact[0])
  if (exact.length > 1) return miss(exact.map((row) => store.categoryPath(row.id)))

  const fuzzy = pool.filter((row) => lower(row.name).includes(needle) || needle.includes(lower(row.name)))
  if (fuzzy.length === 1) return hit(fuzzy[0])
  if (fuzzy.length > 1) return miss(fuzzy.map((row) => store.categoryPath(row.id)))
  return miss()
}

// 账户「种类词」。判定顺序**从专有到宽泛**：先 debit 再 ewallet，
// 否则「银行卡」会被「钱包」的子串规则误吞。
const KIND_WORDS = [
  ['credit', ['credit', '信用卡', '信用', '花呗', '白条']],
  ['prepaid', ['prepaid', '储值', '充值卡', '交通卡', '饭卡', '会员卡', '预付']],
  ['investment', ['investment', 'invest', '投资', '理财', '证券']],
  ['debit', ['debit', '储蓄卡', '储蓄', '借记卡', '银行卡', '银行账户']],
  ['ewallet', ['ewallet', 'e-wallet', 'e wallet', '电子钱包', '钱包', '移动支付', '第三方支付', 'wallet']],
  ['cash', ['cash', '现金', '现钞', '现钱']],
]

// 中文品牌别名 → 英文名子串。
const BRAND_ALIASES = [
  [['支付宝', 'alipay', '蚂蚁'], ['alipay', '支付宝']],
  [['微信', 'wechat', 'weixin'], ['wechat', 'weixin', '微信']],
  [['云闪付', 'unionpay', '银联'], ['unionpay', '云闪付', '银联']],
  [['paypal', '贝宝'], ['paypal', '贝宝']],
  [['touch n go', 'touchngo', 'tng', '一触即通'], ['tng', 'touch']],
]

/** 账户：层层放宽（精确 → 种类词 → 品牌别名 → 模糊 → 币种收窄）。 */
export function resolveAccount(store, raw, preferCurrency) {
  const needle = lower(raw)
  const pool = store.accounts.filter((row) => !row.isArchived)
  if (needle.length === 0) return miss(pool.map((row) => row.name))

  const narrow = (rows) => {
    if (rows.length === 1) return hit(rows[0])
    if (rows.length > 1 && preferCurrency) {
      const same = rows.filter((row) => row.currency === String(preferCurrency).toUpperCase())
      if (same.length === 1) return hit(same[0])
    }
    return rows.length > 1 ? miss(rows.map((row) => row.name)) : null
  }

  const exact = narrow(pool.filter((row) => lower(row.name) === needle))
  if (exact) return exact

  for (const [kind, words] of KIND_WORDS) {
    if (!words.some((word) => needle.includes(word))) continue
    const byKind = narrow(pool.filter((row) => row.kind === kind))
    if (byKind) return byKind
    break
  }

  for (const [triggers, fragments] of BRAND_ALIASES) {
    if (!triggers.some((word) => needle.includes(word))) continue
    const branded = narrow(pool.filter((row) => fragments.some((piece) => lower(row.name).includes(piece))))
    if (branded) return branded
    break
  }

  const fuzzy = narrow(pool.filter((row) => lower(row.name).includes(needle) || needle.includes(lower(row.name))))
  if (fuzzy) return fuzzy
  return miss(pool.map((row) => row.name))
}

/** 项目：精确 → 唯一模糊 → 未找到。 */
export function resolveProject(store, raw) {
  const needle = lower(raw)
  if (needle.length === 0) return miss()
  const pool = store.projects.filter((row) => !row.isArchived)
  const exact = pool.filter((row) => lower(row.name) === needle)
  if (exact.length === 1) return hit(exact[0])
  if (exact.length > 1) return miss(exact.map((row) => row.name))
  const fuzzy = pool.filter((row) => lower(row.name).includes(needle) || needle.includes(lower(row.name)))
  if (fuzzy.length === 1) return hit(fuzzy[0])
  if (fuzzy.length > 1) return miss(fuzzy.map((row) => row.name))
  return miss()
}

const ME_WORDS = ['me', '我', 'myself', 'i', 'self']

/** 成员：精确 → me/我/myself/i/self → 唯一模糊。 */
export function resolveMember(store, projectID, raw) {
  const needle = lower(raw)
  const pool = store.projectMembers(projectID)
  if (needle.length === 0) return miss(pool.map((row) => row.name))
  const exact = pool.filter((row) => lower(row.name) === needle)
  if (exact.length === 1) return hit(exact[0])
  if (ME_WORDS.includes(needle)) {
    const me = pool.find((row) => row.isMe)
    if (me) return hit(me)
  }
  const fuzzy = pool.filter((row) => lower(row.name).includes(needle) || needle.includes(lower(row.name)))
  if (fuzzy.length === 1) return hit(fuzzy[0])
  if (fuzzy.length > 1) return miss(fuzzy.map((row) => row.name))
  return miss(pool.map((row) => row.name))
}

/** 「不归项目」的显式说法。 */
export function isNoneToken(raw) {
  const needle = lower(raw)
  return ['none', '无', '不', '-', 'null'].includes(needle)
}

// 内置种子（§4.8 完整清单）。
//
// 触发时机：**分类表为空**时（首次启动）一次性物化成可编辑的数据行，按当时的 App 内语言解析名称；
// 之后归用户所有（可改名/归档/增删），**永不回灌**。币种表为空时另外种入基准币 CNY（rate 1、isBase）。
// 二级分类**继承父类的颜色**。`isSeed = true` 标记内置来源。

