    children: [
      { en: 'Breakfast', zh: '早餐', icon: 'cup.and.saucer.fill' },
      { en: 'Lunch', zh: '午餐', icon: 'takeoutbag.and.cup.and.straw.fill' },
      { en: 'Dinner', zh: '晚餐', icon: 'fork.knife' },
