// AA 分摊、成员净额与结算（§4.6）。金额一律**基准币分**。

import { KIND, newID } from './store.js'
import { dayStart } from './dates.js'

export const SPLIT_MODES = ['equal', 'exact', 'shares', 'percent']

/**
 * 分摊求解：返回 `[{memberID, amountMinor}]`，**Σ 恒等于 total**。
 * 零头加到**份额数组第一位**；调用方总把付款人排到首位 → 付款人吃零头。
 */
export function resolveSplit(split, totalMinor) {
  const shares = (split && Array.isArray(split.shares)) ? split.shares : []
  if (shares.length === 0) return []
  const total = Math.round(totalMinor)
  const mode = split.mode ?? 'equal'
  const out = shares.map((share) => ({ memberID: share.memberID, amountMinor: 0 }))

  if (mode === 'equal') {
    const each = Math.trunc(total / shares.length)
    for (const row of out) row.amountMinor = each
  } else if (mode === 'exact') {
    shares.forEach((share, index) => {
      const value = Number(share.value) || 0
      out[index].amountMinor = value < 0 ? -Math.round(-value * 100) : Math.round(value * 100)
    })
  } else if (mode === 'shares') {
    const weights = shares.map((share) => Math.max(0, Number(share.value) || 0))
    const sum = weights.reduce((acc, value) => acc + value, 0)
    if (sum > 0) weights.forEach((weight, index) => { out[index].amountMinor = Math.round(total * weight / sum) })
  } else if (mode === 'percent') {
    shares.forEach((share, index) => {
      const percent = Math.max(0, Number(share.value) || 0)
      out[index].amountMinor = Math.round(total * percent / 100)
    })
  }

  const assigned = out.reduce((acc, row) => acc + row.amountMinor, 0)
  out[0].amountMinor += total - assigned
  return out
}

/** 项目里的「我」（没有则 null）。 */
export function meMember(store, projectID) {
  return store.projectMembers(projectID).find((row) => row.isMe) ?? null
}

/**
 * 成员净额（基准币分，全体加总恒为 0）：
 *   付款人先垫付全额 → 每个分摊人扣自己应担 → 未分摊则全归付款人自担（净 0）
 *   再叠加已记录的结算：net[from] += 金额；net[to] -= 金额
 * `>0` = 别人欠 TA；`<0` = TA 欠别人。
 */
export function memberBalances(store, projectID) {
  const members = store.projectMembers(projectID)
  const net = {}
  for (const member of members) net[member.id] = 0
  const me = members.find((row) => row.isMe)

  for (const txn of store.allTransactions()) {
    if (txn.projectID !== projectID || txn.kind !== KIND.expense) continue
    const base = store.reportingBaseMinor(txn)
    const payerID = txn.payerMemberID ?? (me ? me.id : null)
    if (!payerID || net[payerID] === undefined) continue
    net[payerID] += base
    const resolved = txn.split ? resolveSplit(txn.split, base) : []
    if (resolved.length > 0) {
      for (const row of resolved) {
        if (net[row.memberID] === undefined) continue
        net[row.memberID] -= row.amountMinor
      }
    } else {
      net[payerID] -= base
    }
  }

  for (const settlement of store.projectSettlements(projectID)) {
    if (net[settlement.fromMemberID] !== undefined) net[settlement.fromMemberID] += settlement.amountBaseMinor
    if (net[settlement.toMemberID] !== undefined) net[settlement.toMemberID] -= settlement.amountBaseMinor
  }
  return net
}

/** 贪心 min-cash-flow：最少笔数把所有净额归零。返回 `[{fromMemberID, toMemberID, amountMinor}]`。 */
export function settlementPlan(store, projectID) {
  const net = memberBalances(store, projectID)
  const creditors = Object.entries(net).filter(([, value]) => value > 0)
    .map(([id, value]) => ({ id, value })).sort((a, b) => b.value - a.value)
  const debtors = Object.entries(net).filter(([, value]) => value < 0)
    .map(([id, value]) => ({ id, value: -value })).sort((a, b) => b.value - a.value)

  const plan = []
  let ci = 0
  let di = 0
  while (ci < creditors.length && di < debtors.length) {
    const amount = Math.min(creditors[ci].value, debtors[di].value)
    if (amount > 0) plan.push({ fromMemberID: debtors[di].id, toMemberID: creditors[ci].id, amountMinor: amount })
    creditors[ci].value -= amount
    debtors[di].value -= amount
    if (creditors[ci].value <= 0) ci += 1
    if (debtors[di].value <= 0) di += 1
  }
  return plan
}

/**
 * 记一次结算。若 from/to 里有「我」→ **自动生成一笔真实流水**
 * （我收 = income、我付 = expense，换算到该账户币种，source='settlement'，
 * **刻意不挂 projectID** —— 否则会被对账逻辑重复计入），并用 linkedTransactionID 关联。
 * 结算记录与流水在同一次 mutate 里落地（WAL 保证不会只写一半）。
 */
export async function recordSettlement(store, projectID, fromMemberID, toMemberID, amountBaseMinor, options = {}) {
  const amount = Math.abs(Math.round(amountBaseMinor))
  if (amount <= 0) return { ok: false, reason: 'invalidAmount' }
  const from = store.member(fromMemberID)
  const to = store.member(toMemberID)
  if (!from || !to) return { ok: false, reason: 'notFound' }

  const now = Date.now()
  let linked = null
  if (from.isMe || to.isMe) {
    const account = options.account ?? store.defaultAccount()
    if (account) {
      const counterpart = from.isMe ? to : from
      const converted = store.convertMinor(amount, store.baseCode, account.currency)
      linked = store.makeTransaction({
        kind: from.isMe ? KIND.expense : KIND.income,
        amountMinor: converted,
        accountID: account.id,
        currency: account.currency,
        occurredOn: now,
        source: 'settlement',
        note: from.isMe
          ? `AA settlement to ${counterpart.name}`
          : `AA settlement from ${counterpart.name}`,
        projectID: null,
      })
      store.applyPostingSnapshot(linked)
    }
  }

  const settlement = {
    id: newID(),
    projectID,
    fromMemberID,
    toMemberID,
    amountBaseMinor: amount,
    occurredOn: dayStart(now),
    createdAt: now,
    linkedTransactionID: linked ? linked.id : null,
  }
  const ok = await store.mutate((draft) => {
    if (linked) draft.putTx(linked)
    draft.table('settlements').push(settlement)
  })
  return ok ? { ok: true, settlement, transaction: linked } : { ok: false, reason: 'persistence' }
}

/** 删除结算 → 连带软删关联流水。 */
export async function removeSettlement(store, id) {
  const settlement = store.settlements.find((row) => row.id === id)
  if (!settlement) return { ok: false, reason: 'notFound' }
  const now = Date.now()
  const ok = await store.mutate((draft) => {
    const rows = draft.table('settlements')
    const index = rows.findIndex((row) => row.id === id)
    if (index >= 0) rows.splice(index, 1)
    if (settlement.linkedTransactionID) {
      const linked = draft.tx(settlement.linkedTransactionID)
      if (linked) draft.putTx({ ...linked, deletedAt: now })
    }
    return true
  })
  return ok ? { ok: true } : { ok: false, reason: 'persistence' }
}

/** 项目已花（基准币，支出合计）。 */
export function projectSpentMinor(store, projectID) {
  let total = 0
  for (const txn of store.allTransactions()) {
    if (txn.projectID !== projectID || txn.kind !== KIND.expense) continue
    total += store.reportingBaseMinor(txn)
  }
  return total
}

export function projectIncomeMinor(store, projectID) {
  let total = 0
  for (const txn of store.allTransactions()) {
    if (txn.projectID !== projectID || txn.kind !== KIND.income) continue
    total += store.reportingBaseMinor(txn)
  }
  return total
}

// LedgerStore：内存模型 + 唯一写门面（对应原生 LedgerStore + LedgerReliability §4.7）。
//
// 持久层四态与原生一一对应：
//   unopened / ready / degradedMemory(reason) / readOnly(reason)
// 只有 ready 可写。**所有调用方在向用户或模型宣告成功前，必须检查 lastMutationSucceeded。**
//
// 写路径只有一条：`mutate(fn)` → Draft 上改 → 算出脏文档 → 走 db.commit（带 WAL）→
// 成功才把 Draft 换进内存并 revision += 1；失败则内存**原样不动**（天然回滚）、切只读、记录问题。

import { commit as dbCommit, databaseAvailable, loadAll, txDocID } from './db.js'
import { monthKeyOf, dayStart } from './dates.js'
import {
  ACCOUNT_SEEDS, EXPENSE_SEEDS, INCOME_SEEDS, seedName,
} from './seeds.js'
import { applyPostingSnapshot, baseCode, currencyRow, reportingBaseMinor, toBaseMinor, convertMinor, hasUsableRate } from './fx.js'
import { currencyDecimals, currencySymbol } from './currencies.js'

export const TABLE_NAMES = [
  'accounts', 'categories', 'currencies', 'budgets', 'projects', 'members', 'settlements', 'snapshots', 'meta',
]

export const KIND = {
  expense: 'expense',
  income: 'income',
  transferOut: 'transferOut',
  transferIn: 'transferIn',
  adjustment: 'adjustment',
}

export const SCHEMA_VERSION = 2

export function newID() {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') return crypto.randomUUID()
  return `x-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 12)}`
}

/** 是否计入收支报表：**转账两腿与校准都不计**。 */
export function countsInFlow(txn) {
  return txn.kind === KIND.expense || txn.kind === KIND.income
}

/** 只对账户余额有意义的有符号金额。 */
export function signedAmountMinor(txn) {
  switch (txn.kind) {
    case KIND.expense:
    case KIND.transferOut: return -txn.amountMinor
    case KIND.income:
    case KIND.transferIn: return txn.amountMinor
    case KIND.adjustment: return txn.signedAdjustment ?? 0
    default: return 0
  }
}

// MARK: - Draft（写事务的暂存层）

class Draft {
  constructor(store) {
    this.store = store
    this.tables = {}
    this.months = {}
    this.txMonth = new Map()   // id → monthKey 的覆盖层
    this.dirtyTables = new Set()
    this.dirtyMonths = new Set()
  }

  /** 可写取表（首次访问时浅拷贝并标脏）。 */
  table(name) {
    if (!(name in this.tables)) {
      this.tables[name] = (this.store.tables[name] ?? []).slice()
      this.dirtyTables.add(name)
    }
    return this.tables[name]
  }

  /** 只读取表（不标脏）。 */
  read(name) {
    return name in this.tables ? this.tables[name] : (this.store.tables[name] ?? [])
  }

  month(key) {
    if (!(key in this.months)) {
      this.months[key] = (this.store.months[key] ?? []).slice()
      this.dirtyMonths.add(key)
    }
    return this.months[key]
  }

  monthOf(id) {
    if (this.txMonth.has(id)) return this.txMonth.get(id)
    return this.store.txMonth.get(id) ?? null
  }

  /** 读一笔流水（Draft 覆盖优先）。 */
  tx(id) {
    const key = this.monthOf(id)
    if (key === null || key === undefined) return null
    const rows = key in this.months ? this.months[key] : (this.store.months[key] ?? [])
    return rows.find((row) => row.id === id) ?? null
  }

  /** 整条 put（自动处理跨月搬家）。 */
  putTx(txn) {
    const next = monthKeyOf(txn.occurredOn)
    const previous = this.monthOf(txn.id)
    if (previous !== null && previous !== undefined && previous !== next) {
      const old = this.month(previous)
      const index = old.findIndex((row) => row.id === txn.id)
      if (index >= 0) old.splice(index, 1)
    }
    const rows = this.month(next)
    const index = rows.findIndex((row) => row.id === txn.id)
    if (index >= 0) rows[index] = txn
    else rows.push(txn)
    this.txMonth.set(txn.id, next)
    return txn
  }

  /** 物理删除（仅「最近删除」的永久删除用；日常删除是写 deletedAt 的软删）。 */
  dropTx(id) {
    const key = this.monthOf(id)
    if (key === null || key === undefined) return
    const rows = this.month(key)
    const index = rows.findIndex((row) => row.id === id)
    if (index >= 0) rows.splice(index, 1)
    this.txMonth.set(id, null)
  }

  /** 生成 db 操作序列。 */
  operations() {
    const ops = []
    for (const name of this.dirtyTables) {
      ops.push({ c: 'tables', id: name, rows: this.tables[name] })
    }
    for (const key of this.dirtyMonths) {
      const rows = this.months[key]
      if (rows.length === 0) ops.push({ c: 'tx', id: txDocID(key), del: true })
      else ops.push({ c: 'tx', id: txDocID(key), rows })
    }
    return ops
  }
}

// MARK: - Store

export class LedgerStore {
  constructor() {
    this.state = 'unopened'
    this.stateReason = ''
    this.lastMutationSucceeded = true
    this.problems = []
    this.revision = 0
    this.locale = 'en'
    this.tables = Object.fromEntries(TABLE_NAMES.map((name) => [name, []]))
    this.months = {}
    this.txMonth = new Map()
    this.listeners = new Set()
    this._allCache = null
    this._allCacheRevision = -1
  }

  subscribe(listener) {
    this.listeners.add(listener)
    return () => this.listeners.delete(listener)
  }

  emit() {
    this.revision += 1
    for (const listener of this.listeners) listener()
  }

  get canMutate() { return this.state === 'ready' }

  recordProblem(reason) {
    this.problems = [...this.problems.slice(-9), { reason: String(reason), at: Date.now() }]
  }

  // MARK: 打开

  async open(locale) {
    this.locale = locale
    if (!databaseAvailable()) {
      this.state = 'degradedMemory'
      this.stateReason = 'aibox/db-unavailable'
      this.recordProblem('结构化存储不可用，账本只读')
      this.emit()
      return
    }
    try {
      const { tables, tx } = await loadAll()
      for (const name of TABLE_NAMES) this.tables[name] = Array.isArray(tables[name]) ? tables[name] : []
      this.months = {}
      this.txMonth = new Map()
      for (const [key, rows] of Object.entries(tx)) {
        const monthKey = Number(key)
        this.months[monthKey] = rows
        for (const row of rows) this.txMonth.set(row.id, monthKey)
      }
      this.state = 'ready'
      this.stateReason = ''
      await this.seedIfNeeded()
    } catch (error) {
      this.state = 'degradedMemory'
      this.stateReason = String((error && error.message) || error)
      this.recordProblem(this.stateReason)
    }
    this.emit()
  }

  // MARK: 唯一写门面

  /**
   * 执行一次写。`fn(draft)` 在 Draft 上改；返回 false 可主动放弃。
   * 返回是否**真的落盘成功** —— 调用方在向用户或模型宣告成功前必须看它。
   */
  async mutate(fn) {
    this.lastMutationSucceeded = false
    if (!this.canMutate) {
      this.recordProblem('账本只读，改动已被阻止')
      this.emit()
      return false
    }
    const draft = new Draft(this)
    let outcome
    try {
      outcome = fn(draft)
    } catch (error) {
      this.recordProblem(`写入前校验失败：${String((error && error.message) || error)}`)
      this.emit()
      return false
    }
    if (outcome === false) { this.lastMutationSucceeded = false; return false }
    const ops = draft.operations()
    if (ops.length === 0) { this.lastMutationSucceeded = true; return true }
    try {
      await dbCommit(ops)
    } catch (error) {
      // 落盘失败：内存原样不动（Draft 直接丢弃 = 回滚），切只读并显式告知。
      this.state = 'readOnly'
      this.stateReason = String((error && error.message) || error)
      this.recordProblem(this.stateReason)
      this.lastMutationSucceeded = false
      this.emit()
      return false
    }
    for (const name of draft.dirtyTables) this.tables[name] = draft.tables[name]
    for (const key of draft.dirtyMonths) {
      const rows = draft.months[key]
      if (rows.length === 0) delete this.months[key]
      else this.months[key] = rows
    }
    for (const [id, key] of draft.txMonth) {
      if (key === null) this.txMonth.delete(id)
      else this.txMonth.set(id, key)
    }
    this.lastMutationSucceeded = true
    this._allCache = null
    this.emit()
    return true
  }

  // MARK: 种子

  /** 分类表为空时一次性物化；币种表为空时种入基准币 CNY。**永不回灌**。 */
  async seedIfNeeded() {
    const needCategories = this.tables.categories.length === 0
    const needCurrencies = this.tables.currencies.length === 0
    const needAccounts = this.tables.accounts.length === 0 && needCategories
    if (!needCategories && !needCurrencies && !needAccounts) return
    const locale = this.locale
    await this.mutate((draft) => {
      if (needCurrencies) {
        draft.table('currencies').push({
          code: 'CNY', symbol: currencySymbol('CNY'), decimals: currencyDecimals('CNY'),
          rateToBase: 1, isBase: true, manualRate: false, rateConfigured: true,
          sortOrder: 0, updatedAt: Date.now(),
        })
      }
      if (needCategories) {
        const rows = draft.table('categories')
        let order = 0
        for (const seed of EXPENSE_SEEDS) {
          const parentID = newID()
          rows.push({
            id: parentID, name: seedName(seed, locale), systemImage: seed.icon, kind: 'expense',
            parentID: null, colorHex: seed.color, sortOrder: order, isArchived: false, isSeed: true,
          })
          order += 1
          let childOrder = 0
          for (const child of seed.children ?? []) {
            rows.push({
              id: newID(), name: seedName(child, locale), systemImage: child.icon, kind: 'expense',
              parentID, colorHex: seed.color, sortOrder: childOrder, isArchived: false, isSeed: true,
            })
            childOrder += 1
          }
        }
        let incomeOrder = 0
        for (const seed of INCOME_SEEDS) {
          rows.push({
            id: newID(), name: seedName(seed, locale), systemImage: seed.icon, kind: 'income',
            parentID: null, colorHex: seed.color, sortOrder: incomeOrder, isArchived: false, isSeed: true,
          })
          incomeOrder += 1
        }
      }
      if (needAccounts) {
        const rows = draft.table('accounts')
        let order = 0
        for (const seed of ACCOUNT_SEEDS) {
          rows.push({
            id: newID(), name: seedName(seed, locale), kind: seed.kind, currency: 'CNY',
            initialBalanceMinor: 0, includeInNetWorth: true, creditLimitMinor: 0,
            iconName: seed.icon, colorHex: seed.color, sortOrder: order,
            isArchived: false, createdAt: Date.now(),
          })
          order += 1
        }
      }
      draft.table('meta')
      const meta = draft.tables.meta
      if (meta.length === 0) meta.push({ id: 'schema', version: SCHEMA_VERSION, seededAt: Date.now(), seedLocale: locale })
    })
  }

  // MARK: 读

  get accounts() { return this.tables.accounts }
  get categories() { return this.tables.categories }
  get currencies() { return this.tables.currencies }
  get budgets() { return this.tables.budgets }
  get projects() { return this.tables.projects }
  get members() { return this.tables.members }
  get settlements() { return this.tables.settlements }
  get snapshots() { return this.tables.snapshots }

  /** 全部未软删流水，按 occurredOn 倒序 + createdAt 倒序（= 原生 allTransactions 的顺序）。 */
  allTransactions() {
    if (this._allCache && this._allCacheRevision === this.revision) return this._allCache
    const rows = []
    for (const key of Object.keys(this.months)) {
      for (const row of this.months[key]) if (!row.deletedAt) rows.push(row)
    }
    rows.sort((a, b) => (b.occurredOn - a.occurredOn) || (b.createdAt - a.createdAt))
    this._allCache = rows
    this._allCacheRevision = this.revision
    return rows
  }

  /** 含软删的全量（最近删除页用）。 */
  allTransactionsIncludingDeleted() {
    const rows = []
    for (const key of Object.keys(this.months)) rows.push(...this.months[key])
    return rows
  }

  /** 指定月份的流水（未软删）。 */
  monthTransactions(monthKey) {
    return (this.months[monthKey] ?? []).filter((row) => !row.deletedAt)
  }

  /** `from` 之后（含）的全部未软删流水，倒序。 */
  transactionsSince(from) {
    return this.allTransactions().filter((row) => row.occurredOn >= from)
  }

  transaction(id) {
    const key = this.txMonth.get(id)
    if (key === null || key === undefined) return null
    return (this.months[key] ?? []).find((row) => row.id === id) ?? null
  }

  account(id) { return this.accounts.find((row) => row.id === id) ?? null }
  category(id) { return this.categories.find((row) => row.id === id) ?? null }
  project(id) { return this.projects.find((row) => row.id === id) ?? null }
  member(id) { return this.members.find((row) => row.id === id) ?? null }

  activeAccounts() {
    return this.accounts.filter((row) => !row.isArchived).sort((a, b) => a.sortOrder - b.sortOrder)
  }

  /** 默认账户 = 排序最前的未归档账户。 */
  defaultAccount() {
    return this.activeAccounts()[0] ?? null
  }

  activeProjects() {
    return this.projects.filter((row) => !row.isArchived).sort((a, b) => a.sortOrder - b.sortOrder)
  }

  currentProject() {
    return this.projects.find((row) => row.isActive && !row.isArchived) ?? null
  }

  projectMembers(projectID) {
    return this.members.filter((row) => row.projectID === projectID).sort((a, b) => a.sortOrder - b.sortOrder)
  }

  projectSettlements(projectID) {
    return this.settlements.filter((row) => row.projectID === projectID)
  }

  /** 一级分类（未归档），按 sortOrder。 */
  rootCategories(kind) {
    return this.categories
      .filter((row) => row.kind === kind && !row.parentID && !row.isArchived)
      .sort((a, b) => a.sortOrder - b.sortOrder)
  }

  childCategories(parentID) {
    return this.categories
      .filter((row) => row.parentID === parentID && !row.isArchived)
      .sort((a, b) => a.sortOrder - b.sortOrder)
  }

  /** 展示路径：一级用自身名，二级用「父名 / 子名」。 */
  categoryPath(id) {
    const row = this.category(id)
    if (!row) return ''
    if (!row.parentID) return row.name
    const parent = this.category(row.parentID)
    return parent ? `${parent.name} / ${row.name}` : row.name
  }

  /** 一级归并：二级返回其父 id。 */
  rootCategoryID(id) {
    const row = this.category(id)
    if (!row) return null
    return row.parentID ?? row.id
  }

  // MARK: 币种面（委托 fx.js）

  get baseCode() { return baseCode(this.currencies) }
  currencyRow(code) { return currencyRow(this.currencies, code) }
  hasUsableRate(code) { return hasUsableRate(this.currencies, code) }
  toBaseMinor(minor, code) { return toBaseMinor(this.currencies, minor, code) }
  convertMinor(minor, from, to) { return convertMinor(this.currencies, minor, from, to) }
  reportingBaseMinor(txn) { return reportingBaseMinor(this.currencies, txn) }
  applyPostingSnapshot(txn) { return applyPostingSnapshot(this.currencies, txn) }

  /** 新建一条空白流水骨架。 */
  makeTransaction(input) {
    const now = Date.now()
    return {
      id: input.id ?? newID(),
      kind: input.kind ?? KIND.expense,
      amountMinor: Math.abs(Math.round(input.amountMinor ?? 0)),
      currency: input.currency ?? this.baseCode,
      baseAmountMinorAtPosting: null,
      baseCurrencyAtPosting: null,
      fxRateToBaseAtPosting: null,
      fxRateDate: null,
      calculationExpression: input.calculationExpression ?? null,
      idempotencyKey: input.idempotencyKey ?? null,
      batchID: input.batchID ?? null,
      sourceFingerprint: input.sourceFingerprint ?? null,
      occurredOn: dayStart(input.occurredOn ?? now),
      createdAt: input.createdAt ?? now,
      categoryID: input.categoryID ?? null,
      accountID: input.accountID ?? null,
      transferPeerID: input.transferPeerID ?? null,
      merchant: input.merchant ?? null,
      note: input.note ?? '',
      tags: normalizeTags(input.tags),
      reimbursable: !!input.reimbursable,
      refundOfID: input.refundOfID ?? null,
      source: input.source ?? 'manual',
      bookID: null,
      projectID: input.projectID ?? null,
      payerMemberID: input.payerMemberID ?? null,
      split: input.split ?? null,
      deletedAt: null,
      signedAdjustment: input.signedAdjustment ?? 0,
    }
  }
}

/** 标签：去空白、丢空串。 */
export function normalizeTags(value) {
  if (!Array.isArray(value)) return []
  const out = []
  for (const raw of value) {
    const text = String(raw ?? '').trim()
    if (text.length > 0 && !out.includes(text)) out.push(text)
  }
  return out
}

// 子页导航 —— 把本应用的路由栈**镜像**成宿主的系统原生页栈。
//
// 用户的原话：「在小应用里面的页面导航栈，你要用系统的，这样我才能够完整地做滑返回到
// 上一个页面，而且能实时看到上一个页面。」这件事宿主已经做完了（真 `UINavigationController`
// + 冻结像素 + 活 WebView 住栈顶，见 docs/capabilities/applet/native-navigation.md），
// 应用侧要做的只有三件：
//
//   ① manifest 声明 `presentation.subpages: true` —— 这是这条能力的 opt-in 开关；
//   ② 进子页时先 `aibox.navigation.push()` **并等顺序屏障**，再渲染新路由；
//   ③ 返回一律经 `popstate` 回来，把自己的栈**对齐到 history 深度**。
//
// 不接 ②③ 的后果不是「返回没有动画」，而是「返回手势是错的」：`history.pushState`
// 从未发生 → 宿主看到的 `webDepth` 恒为 0 → 认为在根路由 → 最左缘左滑**直接退出整个
// 小应用**，用户的子页栈无声消失。这正是真机上被抱怨的那个形状。
//
// 降级（逐点与改造前一致）：宿主不在（浏览器里调试）、形态是 card/sheet/drawer、
// 或没声明 subpages 时，这里退化成纯内存栈 + 纯 Web History，功能不变。

import React from 'react'

function hostNavigation() {
  const api = (typeof window !== 'undefined' && window.aibox) || null
  return (api && api.navigation) || null
}

/**
 * 宿主桥在 `history.state` 上维护的深度标记（`AppletHostBridge` 包装了 pushState/popstate）。
 * 返回 null = 桥不在（或这条 history 记录不是桥写的）→ 调用方回落纯内存栈。
 */
export function historyDepth() {
  try {
    const state = window.history.state
    const marked = state ? Number(state.__aiboxDepth) : NaN
    return Number.isFinite(marked) ? Math.max(0, marked) : null
  } catch (error) {
    return null
  }
}

/**
 * 进一层：先让宿主冻结**当前页**的像素，再由调用方渲染新路由。
 *
 * 顺序屏障是这里唯一的技术要点：`navigation.push()` 是纯 JS，返回的是一个**已解决的**
 * Promise，`await` 它只让出一个微任务，不足以保证宿主已经处理完 `stateChanged`（= 冻结）。
 * 紧接着 `await getState()` 才是真屏障 —— 两条消息走同一个 reply handler、宿主按 FIFO
 * 在主线程处理，`getState` 的回包到达时 `stateChanged` 必然已处理完。
 *
 * 违反屏障是**观感退化而非功能损坏**：冻结下来的会是新页面的像素，于是拖动中露出的
 * 「上一页」看着像当前页；返回本身照常工作。
 */
async function hostPush(path, title) {
  const nav = hostNavigation()
  if (!nav || typeof nav.push !== 'function') return false
  try {
    await nav.push(title ? { route: path, title } : { route: path })
  } catch (error) {
    return false
  }
  if (typeof nav.getState === 'function') {
    try { await nav.getState() } catch (error) { /* 屏障失败只影响观感 */ }
  }
  return true
}

function hostBack() {
  const nav = hostNavigation()
  if (nav && typeof nav.back === 'function') {
    try { nav.back().catch(() => {}) } catch (error) { return false }
    return true
  }
  if (typeof window !== 'undefined' && window.history) { window.history.back(); return true }
  return false
}

function hostPopToRoot() {
  const nav = hostNavigation()
  if (nav && typeof nav.popToRoot === 'function') {
    try { nav.popToRoot().catch(() => {}) } catch (error) { /* 桥拒绝：栈已在本地清空 */ }
    return
  }
  const depth = historyDepth()
  if (typeof window !== 'undefined' && window.history && depth) window.history.go(-depth)
}

/** 宿主是否真的装了原生页栈。页面据此决定要不要自绘转场（本仓四个应用都不自绘）。 */
export async function subpageTransition() {
  const nav = hostNavigation()
  if (!nav || typeof nav.getState !== 'function') return 'web'
  try {
    const state = await nav.getState()
    return (state && state.transition) || 'web'
  } catch (error) {
    return 'web'
  }
}

/**
 * 路由栈 + 宿主页栈的镜像。
 *
 * - `pathFor(route)` → `#/...`，只用于宿主诊断与 `getState().url`，页面自己不读它；
 * - `titleFor(route)` → 顶栏标题；宿主会把它记进标题栈，返回时自动还原。
 */
export function useSubpageStack(options) {
  const configRef = React.useRef(options || {})
  configRef.current = options || {}

  const [stack, setStack] = React.useState([])

  // 所有返回路径（系统手势、宿主顶栏返回键、页面自己的返回键、popToRoot）最后都落到
  // popstate。这里**对齐到深度**而不是「弹一层」——popToRoot 会一次退多层。
  React.useEffect(() => {
    const onPopState = () => {
      const depth = historyDepth()
      setStack((rows) => {
        const target = depth === null ? rows.length - 1 : depth
        const clamped = Math.max(0, Math.min(rows.length, target))
        return clamped === rows.length ? rows : rows.slice(0, clamped)
      })
    }
    window.addEventListener('popstate', onPopState)
    return () => window.removeEventListener('popstate', onPopState)
  }, [])

  const push = React.useCallback((route) => {
    const { pathFor, titleFor } = configRef.current
    const path = pathFor ? pathFor(route) : `#/${(route && route.name) || 'page'}`
    const title = titleFor ? titleFor(route) : null
    // 渲染新路由必须等屏障回来，否则冻结的是新页面的像素（见 hostPush 注释）。
    hostPush(path, title).then(() => setStack((rows) => [...rows, route]))
  }, [])

  const back = React.useCallback(() => {
    // **不乐观更新**：返回要么由宿主的原生 pop 驱动、要么由 WebKit 的 back-forward 手势
    // 驱动，两条路最后都落到 popstate。抢先 setState 会让宿主的转场演给一个空页面看。
    const depth = historyDepth()
    if (depth !== null && depth > 0 && hostBack()) return
    setStack((rows) => rows.slice(0, -1))
  }, [])

  const reset = React.useCallback(() => {
    // 切 Tab 是「整条子页栈作废」，没有转场可言：乐观清空 + 通知宿主对账（幂等）。
    const depth = historyDepth()
    if (depth) hostPopToRoot()
    setStack((rows) => (rows.length === 0 ? rows : []))
  }, [])

  return {
    stack,
    route: stack.length > 0 ? stack[stack.length - 1] : null,
    push,
    back,
    reset,
  }
}

