\":\"Omit for no split (the payer bears the whole cost).\"},\"split_with\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Member names taking part; omit for everyone.\"},\"split_values\":{\"type\":\"array\",\"items\":{\"type\":\"number\"},\"description\":\"Aligned with split_with: exact amounts, weights, or percentages. Not needed for equal.\"},\"reimbursable\":{\"type\":\"boolean\"},\"refund_of\":{\"type\":\"string\",\"description\":\"transaction_id of the expense this income refunds; 'none' unlinks on update.\"},\"request_id\":{\"type\":\"string\",\"description\":\"Idempotency key (use a UUID). The same key never posts twice — reuse it when retrying.\"},\"batch_id\":{\"type\":\"string\"},\"source_fingerprint\":{\"type\":\"string\"},\"transaction_id\":{\"type\":\"string\",\"description\":\"Required for update and delete.\"}},\"additionalProperties\":false}",
      "outputSchemaJSON": "{\"type\":\"object\",\"properties\":{\"ok\":{\"type\":\"boolean\"},\"text\":{\"type\":\"string\"},\"id\":{\"type\":\"string\"},\"amountMinor\":{\"type\":\"integer\"},\"currency\":{\"type\":\"string\"},\"duplicate\":{\"type\":\"boolean\"}}}",
      "headless": true,
      "visibility": ["agent", "automation", "shortcut"],
      "effect": "write",
      "readOnly": false,
      "destructive": false,
      "idempotent": false,
      "execution": { "mode": "sequential" }
    },
    {
      "id": "ledger.query",
      "name": "query",
      "displayName": "查流水",
      "summary": "List individual ledger entries matching filters. Returns the count, the expense total in the base currency, and one line per entry ending in [id: …] so it can be updated or deleted afterwards. An unresolvable category/account/project name comes back as a candidate list rather than being silently ignored.",
      "keywords": ["ledger", "entries", "transactions", "history", "流水", "明细", "查账"],
      "inputSchemaJSON": "{\"type\":\"object\",\"properties\":{\"type\":{\"type\":\"string\",\"enum\":[\"expense\",\"income\",\"transfer\"]},\"category\":{\"type\":\"string\"},\"account\":{\"type\":\"string\"},\"project\":{\"type\":\"string\"},\"tag\":{\"type\":\"string\"},\"keyword\":{\"type\":\"string\",\"description\":\"Matches merchant, note and tags.\"},\"reimbursable\":{\"type\":\"boolean\"},\"period\":{\"type\":\"string\",\"enum\":[\"today\",\"this_week\",\"last_7_days\",\"last_30_days\",\"this_month\",\"last_month\",\"this_year\",\"all\"],\"description\":\"Defaults to this_month. Ignored when date_from/date_to are given.\"},\"date_from\":{\"type\":\"string\",\"description\":\"YYYY-MM-DD, inclusive.\"},\"date_to\":{\"type\":\"string\",\"description\":\"YYYY-MM-DD, inclusive.\"},\"min_amount\":{\"type\":\"number\"},\"max_amount\":{\"type\":\"number\"},\"limit\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":100,\"description\":\"Defaults to 20.\"}},\"additionalProperties\":false}",
      "outputSchemaJSON": "{\"type\":\"object\",\"properties\":{\"ok\":{\"type\":\"boolean\"},\"text\":{\"type\":\"string\"},\"count\":{\"type\":\"integer\"},\"totalExpenseMinor\":{\"type\":\"integer\"},\"baseCurrency\":{\"type\":\"string\"},\"entries\":{\"type\":\"array\",\"items\":{\"type\":\"object\"}}}}",
      "headless": true,
      "visibility": ["agent", "automation"],
      "effect": "read",
      "readOnly": true,
      "idempotent": true
