      "inputSchemaJSON": "{\"type\":\"object\",\"properties\":{\"dimension\":{\"type\":\"string\",\"enum\":[\"by_category\",\"by_subcategory\",\"by_day\",\"by_month\",\"by_account\",\"by_tag\",\"by_project\"],\"description\":\"Defaults to by_category.\"},\"metric\":{\"type\":\"string\",\"enum\":[\"expense\",\"income\",\"net\"],\"description\":\"Defaults to expense.\"},\"project\":{\"type\":\"string\"},\"period\":{\"type\":\"string\",\"enum\":[\"today\",\"this_week\",\"last_7_days\",\"last_30_days\",\"this_month\",\"last_month\",\"this_year\",\"all\"]},\"date_from\":{\"type\":\"string\"},\"date_to\":{\"type\":\"string\"},\"top_n\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":50,\"description\":\"Time dimensions are never truncated.\"},\"compare_previous\":{\"type\":\"boolean\",\"description\":\"Also compute the immediately preceding window of equal length.\"}},\"additionalProperties\":false}",
      "outputSchemaJSON": "{\"type\":\"object\",\"properties\":{\"ok\":{\"type\":\"boolean\"},\"text\":{\"type\":\"string\"},\"totalMinor\":{\"type\":\"integer\"},\"previousTotalMinor\":{\"type\":[\"integer\",\"null\"]},\"baseCurrency\":{\"type\":\"string\"},\"buckets\":{\"type\":\"array\",\"items\":{\"type\":\"object\"}}}}",
